window.DATA = {"grupos": [{"grupo": "hud_combate", "titulo": "HUD de combate", "ordem": 1, "resumo": "Elementos de interface do combate: vida do herói, veneno, barra do boss com fases, guarda do escudo, recursos dos golpes especiais, barrinha de recovery/recarga, lua, relógio do dia e marcadores sobre inimigos. Tudo em moldura de metal velho rebitado com ossos e acento vermelho-lua, legível sobre o mapa escuro.", "itens": [{"id": "hud_vida", "nome": "Barra de vida do herói", "categoria": "HUD", "mecanica": "Vida do herói (HP-01..HP-11)", "conceito": "A barra de vida do canto superior esquerdo, feita como se o herói tivesse montado o painel com sucata: uma régua de ferro escuro rebitada, arranhada e com manchas de ferrugem, presa a um medalhão redondo de metal que guarda um coração anatômico vermelho (com aorta e veias, não um coração de desenho). A régua tem um friso vermelho-lua fino embaixo do chanfro de cima e um pedaço de osso amarrado na ponta direita como trava. Dentro, 10 segmentos de 10 HP cada, separados por divisórias de metal, com brilho em cima, sombra embaixo e listras diagonais leves para não parecer cor lisa. A cor do recheio muda por faixa (verde, amarelo, vermelho), a ghost bar é uma camada clara atrás da principal e a cura aparece como verde-claro na frente. No veneno tudo fica roxo com bolhas subindo e o coração ganha tom arroxeado; no hit tudo vira quase branco por 80 ms.", "partes": [{"parte": "Medalhão do coração", "descricao": "Disco de metal 40×40 px em x 2..42, y 4..44, borda chanfrada #5a5662/#2a2630, 6 rebites #c9ced4 ao redor, arranhões claros. Fundo interno escuro #1a1418 com brilho vermelho atrás do coração."}, {"parte": "Coração anatômico", "descricao": "~22×24 px: corpo #b8283a com lobos, aorta e artérias em cima #d24a5a, veias azuladas #5a4a8a, brilho #ff9aa0 em cima-esquerda; na vida baixa fica mais vermelho/escuro, no veneno roxo #8a4ab0, no flash quase branco."}, {"parte": "Régua (moldura da barra)", "descricao": "Retângulo 212×26 px em x 40..252, y 11..37, metal #3a3640 com chanfro claro em cima, borda escura, rebites, arranhões, manchas de ferrugem #8a4e2e, respingo de sangue seco #5a161c, friso vermelho-lua #c8323a de 1 px. Ponta direita com osso #d8ccb0 amarrado por corda #b59a62."}, {"parte": "Segmentos", "descricao": "10 células de ~19×14 px em x 48..246, y 17..31, divisórias de metal de 1 px; vazio = rebaixo escuro #140e12 com sombra interna; cheio = cor da faixa com 2 px de brilho no topo, 2 px de sombra embaixo, listras diagonais e borda viva clara na ponta do recheio."}, {"parte": "Ghost bar / prévia de cura", "descricao": "Ghost: rosa-creme claro #f0d8c8 nos segmentos perdidos recentemente (70% → 100%). Cura: verde-claro #b8f0a0 à frente do verde (de 60% até 80%)."}, {"parte": "Bolhas de veneno", "descricao": "Bolhinhas roxas claras #d8a8ff de 2-3 px saindo de cima do recheio, e gotas na moldura."}], "paleta": [{"nome": "Metal escuro", "hex": "#3a3640"}, {"nome": "Chanfro", "hex": "#5a5662"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Osso", "hex": "#d8ccb0"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Vida verde", "hex": "#4fb04a"}, {"nome": "Vida amarela", "hex": "#e0b42a"}, {"nome": "Vida vermelha", "hex": "#d23038"}, {"nome": "Ghost", "hex": "#f0d8c8"}, {"nome": "Cura", "hex": "#b8f0a0"}, {"nome": "Veneno", "hex": "#9a4ad0"}, {"nome": "Rebaixo", "hex": "#140e12"}], "arquivo": "sprites/hud_vida.png", "fw": 256, "fh": 48, "cols": 8, "quadros": ["cheia verde (100%)", "70% com ghost bar clara (dano recente)", "60% com prévia de cura verde-clara (até 80%)", "amarela (40%)", "vermelha (20%)", "vermelha pulsando (2º quadro, mais clara)", "envenenada roxa (60%, bolhas)", "flash branco do hit"], "anims": [{"nome": "pulso vida baixa", "quadros": [4, 5], "dur": [420, 420], "loop": true}, {"nome": "hit", "quadros": [7, 0], "dur": [80, 300], "loop": false}], "uso": "Âncora no canto superior esquerdo (pivô = canto sup. esq.). Na prática o jogo recorta o recheio pelo HP real (largura proporcional) usando os quadros como paleta/estado; smooth drain, tremor do hit e vinheta vermelha são transformações em tempo real.", "w": 2048, "h": 48}, {"id": "hud_veneno", "nome": "Ícone de veneno e timer", "categoria": "HUD", "mecanica": "Veneno (HP-09, HP-10, HP-11)", "conceito": "Ícone que aparece ao lado da barra de vida enquanto o herói está envenenado. É um frasco de vidro grosso, meio torto, cheio de líquido roxo borbulhante, com rolha de cortiça amarrada e uma caveira pintada em osso na frente; uma gota roxa escorre pelo gargalo. Atrás do frasco há um anel de metal rebitado que funciona como cronômetro: o arco roxo brilhante vai se apagando no sentido horário conforme os 5 s passam, deixando o trilho escuro. Lê de longe como 'perigo, tóxico' pela forma do frasco e pela cor.", "partes": [{"parte": "Frasco", "descricao": "Vidro ~26×30 px centrado em (32,36): bojo redondo, gargalo 8 px, vidro #6a5a7a com reflexo branco em faixa, líquido #9a4ad0/#5a1e86 até 2/3, bolhas #d8a8ff."}, {"parte": "Rolha", "descricao": "Cortiça #9a7a4a 8×6 px com barbante #b59a62 e pontinhos de textura."}, {"parte": "Caveira", "descricao": "Caveira de osso #e8dcc0 de 10×10 px na frente do bojo com órbitas e dentes escuros #2a1a2a."}, {"parte": "Anel do timer", "descricao": "Anel de raio 30/25 px: trilho de metal #2a2630 com 4 rebites; arco roxo brilhante #c070ff com borda clara, cobrindo 100/75/50/25/5% começando no topo."}], "paleta": [{"nome": "Líquido roxo", "hex": "#9a4ad0"}, {"nome": "Roxo escuro", "hex": "#5a1e86"}, {"nome": "Brilho veneno", "hex": "#d8a8ff"}, {"nome": "Vidro", "hex": "#6a5a7a"}, {"nome": "Osso", "hex": "#e8dcc0"}, {"nome": "Cortiça", "hex": "#9a7a4a"}, {"nome": "Trilho", "hex": "#2a2630"}], "arquivo": "sprites/hud_veneno.png", "fw": 64, "fh": 64, "cols": 6, "quadros": ["ícone sem anel", "anel 100% (5 s)", "anel 75%", "anel 50%", "anel 25%", "anel 5% (quase acabando)"], "anims": [{"nome": "timer", "quadros": [1, 2, 3, 4, 5], "dur": [1000, 1000, 1000, 1000, 1000], "loop": false}], "uso": "Fica à direita da barra de vida (pivô no centro). O jogo pode usar o quadro mais próximo do tempo restante; ao reaplicar veneno volta ao quadro 1.", "w": 384, "h": 64}, {"id": "hud_boss", "nome": "Barra do boss", "categoria": "HUD", "mecanica": "Boss e fases (BOSS-06, BOSS-10, BF-01, BF-03, BF-08)", "conceito": "Barra larga do rodapé para lutas contra boss (o Açougueiro e os próximos). À esquerda uma placa de ferro pesada, com caveira de osso e dois cutelos cruzados, e rebaixos escuros onde o jogo escreve o nome do boss e o nome da fase. A régua da barra é grossa, com rebites em toda a borda, arranhões, ferrugem e respingos de sangue, e termina num osso amarrado. Dentro há marcadores dourados em 65% e 30% (pinos de latão em losango que atravessam a barra) e, na fase 3, uma linha pontilhada clara em 10% (desespero). A cor do recheio muda por fase: vermelho-carne na fase 1, laranja-ferrugem na fase 2 e vermelho vivo pulsante na fúria, com a palavra FÚRIA em letras próprias numa etiqueta acima. Quando a fase vira, o marcador dourado explode em cacos.", "partes": [{"parte": "Placa do nome", "descricao": "Placa 128×52 px em x 2..130, y 6..58, metal #3a3640 com rebites, caveira ~22×22 px de osso #e8dcc0 sobre cutelos cruzados #9aa0a8; rebaixo do nome #140e12 em x 48..124 y 14..32 e da fase em y 37..50, com friso vermelho-lua."}, {"parte": "Régua", "descricao": "Retângulo ~376×28 px em x 128..504, y 20..48, metal com chanfro, rebites, arranhões, ferrugem, sangue seco; ponta direita com osso amarrado."}, {"parte": "Recheio", "descricao": "Área interna ~360×16 px (x 136..496, y 26..42). Fase 1 #b8283a, fase 2 #d0622a, fúria #ff3030/#ff6a5a (2 quadros), com brilho no topo, sombra embaixo, listras diagonais e veios escuros tipo carne."}, {"parte": "Marcadores", "descricao": "Pinos dourados #f2c230/#b8861a em losango 7×24 px em 65% e 30%; marcador já passado aparece estilhaçado (toco quebrado). Linha pontilhada creme #f0e0c0 em 10% na fase 3/desespero."}, {"parte": "Etiqueta FÚRIA", "descricao": "Plaquinha vermelha #8a141c com contorno dourado acima da barra, letras FÚRIA de 2 px de escala em creme #fff0d8; brilha mais no 2º quadro."}, {"parte": "Cacos", "descricao": "Cacos dourados de 2-4 px voando do marcador de 65% em 3 quadros, com faísca branca."}], "paleta": [{"nome": "Metal", "hex": "#3a3640"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro escuro", "hex": "#b8861a"}, {"nome": "Carne (F1)", "hex": "#b8283a"}, {"nome": "Ferrugem (F2)", "hex": "#d0622a"}, {"nome": "Fúria", "hex": "#ff3030"}, {"nome": "Osso", "hex": "#e8dcc0"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}], "arquivo": "sprites/hud_boss.png", "fw": 512, "fh": 64, "cols": 3, "quadros": ["vazia (entrando)", "fase 1 cheia", "fase 2 (laranja, 65% estilhaçado, 55%)", "fase 3 fúria A (25%)", "fase 3 fúria B (pulso claro)", "desespero (8%, linha 10%)", "marcador estilhaçando 1", "marcador estilhaçando 2", "marcador estilhaçando 3"], "anims": [{"nome": "fúria pulsando", "quadros": [3, 4], "dur": [300, 300], "loop": true}, {"nome": "estilhaço do marcador", "quadros": [6, 7, 8, 2], "dur": [70, 90, 110, 400], "loop": false}], "uso": "Centralizada no rodapé (pivô centro-baixo). O jogo recorta o recheio pelo HP real e escreve nome e fase com a fonte do jogo dentro dos rebaixos. Entrada enchendo 0→100% em 0,8 s é recorte em tempo real a partir do quadro 1 sobre o quadro 0.", "w": 1536, "h": 192}, {"id": "hud_guarda", "nome": "Barra de guarda do escudo", "categoria": "HUD", "mecanica": "Defesa com escudo (DEF-02, DEF-09)", "conceito": "Barrinha azul que aparece sob a barra de vida quando o herói tem escudo. À esquerda um escudo redondo de madeira com aro e umbo de metal, como os escudos improvisados do jogo (tampa de tambor rebitada); à direita uma régua estreita rebitada com 5 entalhes, cheia de energia azul-aço com reflexo. Quando a guarda zera o escudo racha ao meio, a barra fica vermelha vazia com rachaduras e aparecem faíscas. Recarregando, a barra fica azul mais apagada com chevrons claros correndo.", "partes": [{"parte": "Ícone do escudo", "descricao": "Escudo 26×26 px centrado em (15,16): madeira #8b5e34 com tábuas, aro metal #7d848c, umbo #c9ced4, rebites. Quebrado: rachadura preta em zigue-zague, metades afastadas, tinta vermelha #c8323a."}, {"parte": "Régua", "descricao": "~128×18 px em x 28..156, y 7..25, metal #3a3640 com rebites e arranhões; interior ~120×10 px."}, {"parte": "Recheio", "descricao": "Azul #3a8ae0 com brilho #a8d8ff no topo e sombra #1a4a90, entalhes a cada 20% (20 de guarda = golpe normal). Recarregando #4a6a9a dessaturado com chevrons claros."}], "paleta": [{"nome": "Azul guarda", "hex": "#3a8ae0"}, {"nome": "Azul brilho", "hex": "#a8d8ff"}, {"nome": "Azul escuro", "hex": "#1a4a90"}, {"nome": "Madeira", "hex": "#8b5e34"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Quebrada", "hex": "#c8323a"}], "arquivo": "sprites/hud_guarda.png", "fw": 160, "fh": 32, "cols": 5, "quadros": ["cheia (100)", "metade (50)", "quase vazia (15)", "quebrada (0, ícone rachado, vermelho)", "recarregando (40, azul apagado)"], "anims": [], "uso": "Abaixo da barra de vida (pivô canto sup. esq.). Recorte do recheio pela guarda real; o texto GUARDA QUEBRADA é texto do jogo.", "w": 800, "h": 32}, {"id": "hud_energia", "nome": "Barras de recurso dos golpes especiais", "categoria": "HUD", "mecanica": "Golpes especiais (KMH-06..08, RSG-08, GTS-08, CHD-07, LSR-07, LSR-08)", "conceito": "Quatro barras de carga, uma por recurso, no mesmo corpo de metal rebitado com um soquete à esquerda que mostra o símbolo do recurso: esfera azul de ki (Kamehameha), espiral ciano de chakra (Rasengan/Chidori), lua crescente vermelha e preta de reiatsu (Getsuga) e bateria verde-ciano (laser). A barra tem marca de mínimo (entalhe claro) e marca de carga cheia (entalhe dourado). Carregando, a energia sobe com brilho na ponta; cheia, a barra inteira brilha e solta faíscas; na sobrecarga (só ki e chakra) fica branco-dourada e instável; no resfriamento a barra fica vermelha descendo com vapor. A célula de energia é dividida em 4 células físicas em vez de recheio contínuo.", "partes": [{"parte": "Soquete do ícone", "descricao": "Disco ~26 px em (14,16) metal com rebites; ícone 16 px: ki = esfera azul #4a9aff com núcleo branco; chakra = espiral ciano #4ae0e8; reiatsu = crescente vermelho #e02a2a sobre preto #120a0e; célula = bateria verde-ciano #3ae0a0 com raio."}, {"parte": "Régua", "descricao": "~164×18 px em x 26..190, y 7..25, rebites, arranhões, friso da cor do recurso. Marca de mínimo creme em ~25% e marca de cheia dourada em ~85%."}, {"parte": "Recheio", "descricao": "Cor do recurso com brilho no topo e listras; reiatsu é vermelho com veios pretos; célula tem 4 blocos separados por divisória grossa. Sobrecarga #fff0b0/#f2c230. Resfriamento #c8323a com vapor cinza #b8b0c0."}, {"parte": "Faíscas", "descricao": "Brilho e faíscas de 3-5 px em volta da barra nos quadros cheia/sobrecarga."}], "paleta": [{"nome": "Ki", "hex": "#4a9aff"}, {"nome": "Chakra", "hex": "#4ae0e8"}, {"nome": "Reiatsu", "hex": "#e02a2a"}, {"nome": "Reiatsu preto", "hex": "#120a0e"}, {"nome": "Célula", "hex": "#3ae0a0"}, {"nome": "Sobrecarga", "hex": "#fff0b0"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Resfriamento", "hex": "#c8323a"}], "arquivo": "sprites/hud_energia.png", "fw": 192, "fh": 32, "cols": 5, "quadros": ["ki vazia", "ki carregando (passou do mínimo)", "ki carga cheia brilhando", "ki sobrecarga", "ki resfriamento", "chakra vazia", "chakra carregando", "chakra carga cheia brilhando", "chakra sobrecarga", "chakra recarga", "reiatsu vazia", "reiatsu carregando", "reiatsu carga cheia brilhando", "reiatsu cheia brilho 2", "reiatsu recarga", "célula vazia", "célula carregando (2 de 4)", "célula carga cheia brilhando", "célula cheia brilho 2", "célula resfriamento"], "anims": [{"nome": "ki sobrecarga", "quadros": [2, 3], "dur": [90, 90], "loop": true}, {"nome": "chakra sobrecarga", "quadros": [7, 8], "dur": [90, 90], "loop": true}, {"nome": "reiatsu cheia", "quadros": [12, 13], "dur": [200, 200], "loop": true}, {"nome": "célula cheia", "quadros": [17, 18], "dur": [250, 250], "loop": true}], "uso": "Uma linha por recurso; só a do golpe equipado aparece no HUD (pivô canto sup. esq.). A posição real da carga é recorte em tempo real; os quadros dão o estado/cor.", "w": 960, "h": 128}, {"id": "hud_recuperacao", "nome": "Barrinha de recovery e recarga", "categoria": "HUD", "mecanica": "Recovery do martelo e recarga (HAM-07, TIR-08, LSR-07)", "conceito": "Barrinha pequena que flutua sobre a cabeça do herói. É uma plaquinha de metal com rebites e um ícone à esquerda: um martelo para o recovery do golpe pesado e um cartucho de bala para a recarga da arma. Para o martelo a barra enche em branco-creme e, a partir de 0,3 s (54%), fica azul indicando que outro toque cancela; para a recarga enche em laranja-latão com marcas de munição. Pequena mas legível, com contorno escuro grosso para destacar do chão.", "partes": [{"parte": "Plaquinha", "descricao": "Retângulo ~60×14 px em x 2..62, y 5..19, metal #3a3640, rebites, chanfro."}, {"parte": "Ícone", "descricao": "~10×12 px à esquerda: martelo (cabeça #7d848c, cabo #8a6a42) ou cartucho (latão #d0a040, ponta cobre #b8683a)."}, {"parte": "Recheio", "descricao": "Interior ~44×6 px. Martelo: creme #f0e6d0 antes de 54%, azul #4a9aff depois (com brilho). Recarga: laranja #e09a30 com 5 marquinhas."}], "paleta": [{"nome": "Creme", "hex": "#f0e6d0"}, {"nome": "Azul cancelável", "hex": "#4a9aff"}, {"nome": "Latão", "hex": "#e09a30"}, {"nome": "Metal", "hex": "#3a3640"}], "arquivo": "sprites/hud_recuperacao.png", "fw": 64, "fh": 24, "cols": 5, "quadros": ["martelo 0%", "martelo 35%", "martelo 55% (azul, cancelável)", "martelo 80% (azul)", "martelo 100% (azul)", "recarga 0%", "recarga 25%", "recarga 50%", "recarga 75%", "recarga 100%"], "anims": [{"nome": "recovery", "quadros": [0, 1, 2, 3, 4], "dur": [110, 110, 110, 110, 110], "loop": false}, {"nome": "recarga", "quadros": [5, 6, 7, 8, 9], "dur": [200, 200, 200, 200, 200], "loop": false}], "uso": "Pivô centro-baixo, 8 px acima da cabeça do herói. Pode recortar o recheio pelo progresso real.", "w": 320, "h": 48}, {"id": "hud_lua", "nome": "Ícone da Lua", "categoria": "HUD", "mecanica": "Lua de Sangue (LUA-03)", "conceito": "A lua no canto do HUD que avisa a chegada da Lua de Sangue. É uma lua cheia pixelada com crateras e mares escuros, presa num aro de ferro rebitado com quatro garras de osso. Normal ela é branco-creme com luz fria; nos últimos 10 minutos vai ficando rosada, depois vermelha, e pulsa (o segundo quadro é mais claro e com halo maior). Com a Lua de Sangue ativa ela fica vermelho-sangue escuro com escorridos de sangue embaixo e uma aura vermelha pulsante em volta.", "partes": [{"parte": "Aro", "descricao": "Anel de metal raio 25/21 px centrado em (32,32), #3a3640, rebites e 4 garras de osso #d8ccb0 nas diagonais."}, {"parte": "Lua", "descricao": "Disco raio 19 px: branca #ece6d6, rosada #e8b0b0, vermelha #d84848, sangue #a8141c; crateras de 2-5 px com borda clara, mares escuros, terminador sombreado na direita-baixo."}, {"parte": "Aura / sangue", "descricao": "Halo vermelho #ff3a3a quantizado; na Lua de Sangue escorridos de sangue #6a0a10 saindo de baixo."}], "paleta": [{"nome": "Lua branca", "hex": "#ece6d6"}, {"nome": "Rosada", "hex": "#e8b0b0"}, {"nome": "Vermelha", "hex": "#d84848"}, {"nome": "Sangue", "hex": "#a8141c"}, {"nome": "Aura", "hex": "#ff3a3a"}, {"nome": "Osso", "hex": "#d8ccb0"}], "arquivo": "sprites/hud_lua.png", "fw": 64, "fh": 64, "cols": 7, "quadros": ["lua branca normal", "ficando rosada", "vermelha", "vermelha pulsando A", "vermelha pulsando B (clara, halo)", "Lua de Sangue ativa A", "Lua de Sangue ativa B (aura maior)"], "anims": [{"nome": "aviso pulsando", "quadros": [3, 4], "dur": [500, 500], "loop": true}, {"nome": "lua de sangue", "quadros": [5, 6], "dur": [600, 600], "loop": true}], "uso": "Canto superior direito, pivô no centro. O ritmo do pulso pode acompanhar a batida do coração (acelera).", "w": 448, "h": 64}, {"id": "hud_relogio", "nome": "Relógio do dia (arco sol/lua)", "categoria": "HUD", "mecanica": "Dia e noite (DN-01)", "conceito": "Arco de metal em meia-lua que mostra a hora do mapa: uma régua curva de ferro rebitado com marcas das horas, sobre um céu recortado que muda de cor com o período. O sol (disco amarelo com raios) ou a lua andam pelo arco: nasce à esquerda, fica no topo ao meio-dia e desce à direita no entardecer; à noite a lua branca fica no alto com estrelas, e na Lua de Sangue a lua é vermelha com céu bordô. Embaixo do arco há uma faixa onde o jogo escreve a hora e o nome do período, e um horizonte de prédios do Recife em silhueta.", "partes": [{"parte": "Arco", "descricao": "Semicírculo de raio 58/50 px centrado em (64,56), metal #3a3640 com marcas de hora #c9ced4 e rebites, ponta de osso nas duas extremidades."}, {"parte": "Céu", "descricao": "Interior do semicírculo raio 49: amanhecer laranja/rosa #e88a5a→#6a4a8a, meio-dia azul #5aa0d8, entardecer laranja-vermelho #d8603a→#4a2a5a, noite #1a1a3a com estrelas, Lua de Sangue #3a0a14 com estrelas vermelhas."}, {"parte": "Skyline", "descricao": "Silhuetas de prédios e torre #14101a na base do céu, janelas acesas raras."}, {"parte": "Astro", "descricao": "Sol raio 7 px #ffd84a com raios; lua raio 6 px #ece6d6 com crateras; lua de sangue #d82a2a com aura."}, {"parte": "Faixa", "descricao": "Placa ~112×9 px em y 55..64 metal escuro com rebaixo para o texto do jogo."}], "paleta": [{"nome": "Sol", "hex": "#ffd84a"}, {"nome": "Céu dia", "hex": "#5aa0d8"}, {"nome": "Amanhecer", "hex": "#e88a5a"}, {"nome": "Noite", "hex": "#1a1a3a"}, {"nome": "Lua de Sangue", "hex": "#d82a2a"}, {"nome": "Skyline", "hex": "#14101a"}], "arquivo": "sprites/hud_relogio.png", "fw": 128, "fh": 64, "cols": 5, "quadros": ["amanhecer", "meio-dia", "entardecer", "noite", "Lua de Sangue"], "anims": [], "uso": "Topo central do HUD, pivô centro-baixo. O jogo troca o quadro no início do período.", "w": 640, "h": 64}, {"id": "hud_alvo_inimigo", "nome": "Marcadores sobre inimigos", "categoria": "HUD", "mecanica": "Inimigos (LUA-09, DEF-10, HP-03)", "conceito": "Pequenos sinais que flutuam acima da cabeça dos zumbis. A mini barra de vida é uma régua fina de metal com recheio vermelho e ghost clara; o mini boss tem uma versão mais grossa com caveira e moldura dourada. A etiqueta RARO é uma plaquinha dourada com rebites e letras escuras, com brilho, para a variante rara da Lua de Sangue. Os sinais de telegrafia são um '!' grosso com contorno escuro: amarelo para golpe normal, vermelho com aura pulsante para golpe pesado e roxo com aura e correntes para agarrão que não dá para defender.", "partes": [{"parte": "Mini barra", "descricao": "40×8 px centrada em x 32, y ~44..52, metal #3a3640, recheio vermelho #d23038 com brilho, ghost #f0d8c8."}, {"parte": "Barra de mini boss", "descricao": "~52×12 px, moldura dourada #b8861a/#f2c230 e caveira de osso ~10×10 px à esquerda, recheio vermelho-carne."}, {"parte": "Etiqueta RARO", "descricao": "Placa ~34×13 px dourada #f2c230 com chanfro, 2 rebites, letras RARO 3×5 em #3a2a08 e sparkles brancos."}, {"parte": "Exclamação", "descricao": "'!' de ~10×28 px com bisel: amarelo #ffd23a, vermelho #ff3a3a com aura #ff5a5a, roxo #b04aff com aura e elos de corrente."}], "paleta": [{"nome": "Vida inimigo", "hex": "#d23038"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Aviso amarelo", "hex": "#ffd23a"}, {"nome": "Aviso vermelho", "hex": "#ff3a3a"}, {"nome": "Agarrão roxo", "hex": "#b04aff"}], "arquivo": "sprites/hud_alvo_inimigo.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["mini barra cheia", "mini barra 45% com ghost", "barra de mini boss (70%)", "etiqueta RARO", "! amarelo (golpe normal)", "! vermelho com aura A (pesado)", "! vermelho com aura B", "! roxo (agarrão, indefensável)"], "anims": [{"nome": "! pesado", "quadros": [5, 6], "dur": [120, 120], "loop": true}], "uso": "Pivô centro-baixo, colado acima da cabeça do inimigo (mini barra) ou um pouco acima dela (!/RARO). Recorte do recheio pelo HP real.", "w": 512, "h": 64}]}, {"grupo": "progressao_dialogo", "titulo": "XP, recompensas e diálogo", "ordem": 2, "resumo": "Interface de progressão (barra de XP, selos de nível, cartas de recompensa, burst de level up, barra de recrutar, resumo/relatório) e do sistema de diálogo (caixa, extras, retratos, balões/emotes). Tudo em moldura de madeira gasta e metal rebitado, com acento vermelho-lua e dourado; o texto é escrito pelo jogo por cima, o sprite só deixa os espaços.", "itens": [{"id": "ui_xp", "nome": "Barra de XP do rodapé", "categoria": "Interface", "mecanica": "Progressão (LVL-02, LVL-03)", "conceito": "Barra comprida que fica no rodapé do HUD, feita de uma régua de madeira escura presa por chapas de metal rebitadas, como se tivesse sido arrancada de uma placa de rua do Recife Antigo. À esquerda fica o selo do nível: um medalhão vermelho-lua com aro dourado e um disco escuro no meio onde o jogo escreve o número. A canaleta da barra é funda e escura, com marcas de 10 em 10%, e o preenchimento é ouro líquido em faixas (brilho em cima, ouro no meio, âmbar embaixo) com uma ponta mais clara. Acima de 85% a barra pulsa (dois quadros: normal e brilhando) e quando enche pisca branco antes do level up.", "partes": [{"parte": "Selo do nível", "descricao": "medalhão de 36×36 px em x 2..37, coroa de 12 dentes em vermelho-lua #c8323a com aro dourado #f2c230/#b8861a, disco central escuro #1e1418 de ~18 px de diâmetro VAZIO para o número, 4 rebites; nos quadros de pulso o aro ganha brilho"}, {"parte": "Casco da barra", "descricao": "régua de madeira #7d5430/#5a3a22 de 348×26 px (x 32..379, y 7..32) com veios, emendas de tábua a cada ~64 px, chapas de metal #7d848c nas pontas e no meio com rebites #c9ced4, ferrugem #8a4e2e e um respingo de sangue seco"}, {"parte": "Canaleta", "descricao": "fundo #1a1218 de 320×14 px (x 46..365, y 13..26) com borda interna escura, 9 marcas verticais de 10%, leve brilho roxo embaixo"}, {"parte": "Preenchimento", "descricao": "faixas horizontais: linha de luz #fff2b0, ouro #f2c230, ouro escuro #d9a020, âmbar #b8861a e linha #7a5410; ponta com 2 px clara; nos quadros de pulso fica mais clara e ganha halo; no quadro de cheia piscando vira branco #fffbea"}], "paleta": [{"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Madeira", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Canaleta", "hex": "#1a1218"}], "arquivo": "sprites/ui_xp.png", "fw": 384, "fh": 40, "cols": 7, "quadros": ["vazia", "30%", "60%", "85% (pulso A)", "85% (pulso B, brilhando)", "cheia", "cheia piscando branco"], "anims": [{"nome": "pulso", "quadros": [3, 4], "dur": [260, 260], "loop": true}, {"nome": "cheia", "quadros": [5, 6, 5, 6], "dur": [90, 90, 90, 90], "loop": false}], "uso": "Âncora no canto inferior esquerdo do HUD. Os quadros de % são referência visual; no jogo o preenchimento real pode ser recortado do quadro 'cheia' (canaleta x 46..365) para qualquer valor, com o ease-out de 0,4 s. O número do nível é escrito pelo jogo centrado em (19, 19). '+N XP' é texto do jogo.", "w": 2688, "h": 40}, {"id": "ui_selo_nivel", "nome": "Selo / brasão de nível", "categoria": "Interface", "mecanica": "Progressão (LVL-02, LVL-06)", "conceito": "Brasão redondo de metal com coroa dentada e duas fitas penduradas embaixo, mostrando a faixa de nível do herói. Cada tier troca o material e ganha enfeites: bronze simples e arranhado, prata com rebites, ouro com estrela e louros, lunar vermelho em pedra escura com lua crescente em cima, e lunar dourado com runas vermelhas brilhando em volta e raios de luz. O miolo é um disco escuro afundado onde o jogo escreve o número. Os tiers mais altos são reconhecíveis de longe pelo brilho e pela silhueta mais recortada.", "partes": [{"parte": "Coroa dentada", "descricao": "anel com 14 dentes, raio externo 22 px centrado em (32, 29); cor do tier com luz de cima-esquerda e arranhões"}, {"parte": "Aro interno", "descricao": "anel de 4 px em tom mais escuro do material, com rebites (prata em diante) ou runas (lunar dourado)"}, {"parte": "Miolo", "descricao": "disco #1e1418 de raio 11 px VAZIO para o número, borda de sombra e um brilho no canto superior esquerdo"}, {"parte": "Fitas", "descricao": "duas fitas de 9×16 px com ponta em V saindo de baixo (y 44..60): marrom (bronze), azul (prata), vermelha (ouro), vinho (lunar vermelho), preta com filete dourado (lunar dourado)"}, {"parte": "Enfeites", "descricao": "ouro: estrela em cima e ramos de louro; lunar vermelho: lua crescente vermelha em cima; lunar dourado: lua dourada, 6 runas vermelhas #ff5a5a e halo"}], "paleta": [{"nome": "Bronze", "hex": "#b87333"}, {"nome": "Bronze escuro", "hex": "#7a4a22"}, {"nome": "Prata", "hex": "#c0c4cc"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Runa brilho", "hex": "#ff5a5a"}], "arquivo": "sprites/ui_selo_nivel.png", "fw": 64, "fh": 64, "cols": 5, "quadros": ["tier 1 bronze (N1-9)", "tier 2 prata (N10-19)", "tier 3 ouro (N20-29)", "tier 4 lunar vermelho (N30-39)", "tier 5 lunar dourado com runas (N40+)"], "uso": "Ícone de nível no perfil, no level up (embaixo de 'Nível N') e opcionalmente no lugar do selo da ui_xp (escalado 0,5×). Número centrado em (32, 29). Faixas de nível por tier são proposta.", "w": 320, "h": 64}, {"id": "ui_carta", "nome": "Cartas do show de recompensas", "categoria": "Interface", "mecanica": "Progressão / Boss (LVL-07, BF-13)", "conceito": "Cartas de recompensa que entram uma a uma com pop depois do level up ou do baú do boss. Cada carta tem moldura dourada com cantoneiras rebitadas e um fio de brilho na borda, uma janela de ícone com fundo escuro e halo na cor do tipo, uma faixa vazia para o título e um painel escuro embaixo para o texto 'antes → depois'. O verso é vinho escuro com uma lua de sangue dourada e treliça de losangos, usado quando a carta vira. Os ícones são grandes e bem detalhados: coração com curativo, punho com fita segurando um facão, escudo de tábuas, estrela de XP, cutelo ensanguentado do boss, chave de ouro com lua, fragmento lunar brilhando e bandeira fincada nos escombros.", "partes": [{"parte": "Moldura", "descricao": "retângulo 88×120 px (x 4..91, y 4..123) em dourado #f2c230/#b8861a com 3 px, linha interna na cor do tipo, cantoneiras de metal com rebite nos 4 cantos e brilho #fff2b0 piscado na borda externa"}, {"parte": "Janela do ícone", "descricao": "área 72×58 px (x 12..83, y 12..69) fundo #1e1820 com halo da cor do tipo; ícone de ~40 px centrado em (48, 41)"}, {"parte": "Faixa do título", "descricao": "fita 80×13 px (y 73..85) na cor do tipo, pontas dobradas, VAZIA para o nome"}, {"parte": "Painel de valor", "descricao": "painel escuro 68×26 px (x 14..81, y 90..115) com borda afundada e 2 rebites, VAZIO para '+4 HP' / 'antes → depois'"}, {"parte": "Verso", "descricao": "fundo vinho #4a141c com treliça dourada escura, lua crescente vermelha com aro dourado no centro, 4 estrelinhas"}], "paleta": [{"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro escuro", "hex": "#b8861a"}, {"nome": "Brilho", "hex": "#fff2b0"}, {"nome": "Fundo", "hex": "#1e1820"}, {"nome": "Vida", "hex": "#d8394a"}, {"nome": "Força", "hex": "#e0702a"}, {"nome": "Defesa", "hex": "#4a8fe0"}, {"nome": "XP", "hex": "#f2c230"}, {"nome": "Lunar", "hex": "#c8323a"}, {"nome": "Região", "hex": "#4fb06a"}, {"nome": "Verso vinho", "hex": "#4a141c"}], "arquivo": "sprites/ui_carta.png", "fw": 96, "fh": 128, "cols": 9, "quadros": ["verso", "Vida (+4 HP, coração)", "Força (punho e facão)", "Defesa (escudo)", "XP (estrela)", "Arma do boss (cutelo)", "Chave de ouro", "Material (fragmento lunar)", "Região libertada (bandeira)"], "uso": "Centro da tela, uma carta por recompensa com 0,15 s (level up) ou 0,28 s (boss) de intervalo; pop com overshoot e virada (verso → frente) são transformações em tempo real (escala X). Título e valores são texto do jogo nas áreas vazias.", "w": 864, "h": 128}, {"id": "ui_levelup_fx", "nome": "Burst do level up", "categoria": "Efeito", "mecanica": "Progressão (LVL-03, LVL-04)", "conceito": "Efeito grande desenhado em volta do herói na hora do level up. Começa com o build up: faíscas douradas com rastro sendo sugadas para o centro enquanto um brilho cresce. Vem o flash branco-dourado em estrela, depois a onda de choque: um anel branco com borda dourada que se expande e vai esfriando para laranja e vermelho-lua, se quebrando nas pontas. Fecha com raios de luz dourados longos e curtos girando, com brilhinhos. É todo semitransparente, para somar com o herói e o mapa.", "partes": [{"parte": "Partículas", "descricao": "faíscas de 2-3 px #fff2b0/#f2c230 com rastro de 4-10 px apontando para o centro (build up) ou para fora (onda); 18-24 por quadro"}, {"parte": "Brilho central", "descricao": "halo radial em degraus #f2c230 → #fff6c8, raio 12 px (build 1), 22 px (build 2), 44 px (flash)"}, {"parte": "Onda de choque", "descricao": "anel com núcleo branco e bordas douradas, raio 30 / 56 / 84 px, espessura 9 / 6 / 3 px, alfa caindo, cor esfriando para #e0702a e #c8323a"}, {"parte": "Raios", "descricao": "12 raios em cunha alternando 90 e 60 px, ouro com miolo claro, e 6 brilhos em cruz"}], "paleta": [{"nome": "Branco quente", "hex": "#fffbea"}, {"nome": "Brilho", "hex": "#fff2b0"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Laranja", "hex": "#e0702a"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}], "arquivo": "sprites/ui_levelup_fx.png", "fw": 192, "fh": 192, "cols": 7, "quadros": ["build up 1 (partículas longe)", "build up 2 (partículas perto)", "flash", "onda 1", "onda 2", "onda 3", "raios de luz"], "anims": [{"nome": "build", "quadros": [0, 1], "dur": [350, 350], "loop": false}, {"nome": "burst", "quadros": [2, 3, 4, 5, 6], "dur": [250, 160, 170, 170, 400], "loop": false}], "uso": "Centro do quadro (96, 96) no centro do herói, camada acima do herói. A onda real até ~6 tiles é escala em tempo real dos quadros de onda; rotação lenta dos raios, câmera lenta, escurecer a tela e tremor são do jogo.", "w": 1344, "h": 192}, {"id": "dlg_caixa", "nome": "Caixa de diálogo", "categoria": "Interface", "mecanica": "Diálogo (DLG-01..06)", "conceito": "Caixa larga que sobe do rodapé quando alguém fala. É uma moldura de tábuas escuras pregadas com cantoneiras de metal rebitadas, painel interno escuro levemente texturizado onde o texto é escrito, e à esquerda um nicho afundado para o retrato. Em cima, à esquerda, uma placa de nome pregada na borda. A cor da fita interna, da placa e das pedrinhas dos cantos muda com quem fala: vermelho-lua para o herói, âmbar para NPC sobrevivente, verde para recruta e cinza para mensagens do sistema. Tem marcas de faca, ferrugem e uma mancha de sangue seco para não parecer limpa demais.", "partes": [{"parte": "Moldura", "descricao": "retângulo 508×122 px (x 2..509, y 20..141), borda de tábua de 8 px #7d5430/#5a3a22 com veios e pregos #c9c3b0, cantoneiras de metal #7d848c 18×18 px com 3 rebites e uma pedra na cor de quem fala"}, {"parte": "Fita de cor", "descricao": "filete de 2 px dentro da tábua na cor de quem fala (herói #c8323a, NPC #e0902a, recruta #4fb06a, sistema #9a98a0) com brilho claro em cima"}, {"parte": "Nicho do retrato", "descricao": "quadrado 100×100 px (x 12..111, y 32..131) afundado, fundo #120c12, VAZIO para o dlg_retrato (96×96 em x 14, y 34)"}, {"parte": "Painel do texto", "descricao": "área x 120..500, y 30..133 fundo #231a22 com textura e vinheta, VAZIA para o texto; canto inferior direito reservado para o ▼"}, {"parte": "Placa de nome", "descricao": "placa 150×24 px (x 118..267, y 6..29) na cor de quem fala com 2 pregos, VAZIA para o nome"}], "paleta": [{"nome": "Madeira", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Painel", "hex": "#231a22"}, {"nome": "Herói", "hex": "#c8323a"}, {"nome": "NPC", "hex": "#e0902a"}, {"nome": "Recruta", "hex": "#4fb06a"}, {"nome": "Sistema", "hex": "#9a98a0"}], "arquivo": "sprites/dlg_caixa.png", "fw": 512, "fh": 144, "cols": 2, "quadros": ["herói (vermelho-lua)", "NPC sobrevivente (âmbar)", "recruta (verde)", "sistema (cinza, sem retrato)"], "uso": "Ancorada embaixo no centro da tela; sobe de baixo (tween do jogo). Retrato em (14, 34), nome em (126..260, 10..26), texto em (124..496, 36..128), ▼ em (~480, 118). No modo sem speaker (DLG-06 desligado) usar o quadro sistema.", "w": 1024, "h": 288}, {"id": "dlg_extras", "nome": "Extras do diálogo", "categoria": "Interface", "mecanica": "Diálogo (DLG-02, DLG-06)", "conceito": "Peças pequenas que completam a caixa de diálogo. O triângulo ▼ dourado com borda vermelha indica que a fala terminou e pisca entre dois quadros. A cauda é uma ponta de madeira com o mesmo painel escuro da caixa, apontando para cima, para quem fala. A placa de nome vem em peças de 9-slice (ponta esquerda, meio repetível sem emenda, ponta direita) para caber qualquer nome. O botão de escolha é uma plaquinha de madeira com painel escuro; selecionado ganha borda dourada e seta ▶.", "partes": [{"parte": "Triângulo ▼", "descricao": "triângulo 16×12 px centrado em (32, 30), ouro #f2c230 com contorno #7a1a22; quadro B desce 3 px e escurece"}, {"parte": "Cauda", "descricao": "cunha de 40 px de base (y 63) e ponta em (26, 6), tábua #7d5430 nas laterais e miolo #231a22, base aberta para encaixar na borda da caixa"}, {"parte": "Placa (9-slice)", "descricao": "faixa de 24 px de altura (y 20..43): ponta esquerda chanfrada com prego, meio repetível 64 px com veio periódico, ponta direita espelhada; cor âmbar-madeira #9a6a3c com filete dourado"}, {"parte": "Botão de escolha", "descricao": "placa 60×36 px (x 2..61, y 14..49), tábua com painel #231a22 VAZIO; selecionado: borda #f2c230, brilho e seta ▶ vermelha à esquerda"}], "paleta": [{"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Vinho", "hex": "#7a1a22"}, {"nome": "Madeira", "hex": "#7d5430"}, {"nome": "Madeira clara", "hex": "#9a6a3c"}, {"nome": "Painel", "hex": "#231a22"}], "arquivo": "sprites/dlg_extras.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["▼ aceso", "▼ apagado/baixo", "cauda apontando para cima", "placa ponta esquerda", "placa meio (repetível)", "placa ponta direita", "botão de escolha", "botão de escolha selecionado"], "anims": [{"nome": "seta_piscando", "quadros": [0, 1], "dur": [400, 400], "loop": true}], "uso": "▼ no canto inferior direito do painel de texto. Cauda posicionada no x do falante sobre a borda superior da caixa (pode espelhar). Placa: ponta esquerda + N meios + ponta direita, a peça útil ocupa y 20..43. Botões empilhados acima da caixa (escolhas fora da demo).", "w": 512, "h": 64}, {"id": "dlg_retrato", "nome": "Retratos de sobreviventes", "categoria": "Interface", "mecanica": "Diálogo (DLG-06)", "conceito": "Retratos de busto de dois NPCs sobreviventes para a caixa de diálogo, numa moldura de madeira com cantos de metal e fundo de noite roxa com a lua de sangue atrás. Dona Socorro é uma senhora mais velha, pele negra, lenço vermelho estampado amarrado na cabeça, mechas grisalhas, brincos dourados, rugas e um xale; olhar cansado mas firme. Biu é um rapaz moreno de boné azul desbotado com remendo, camiseta listrada suja, curativo na bochecha e barba rala. Cada um tem 4 quadros para a boca mexer e os olhos piscarem.", "partes": [{"parte": "Moldura", "descricao": "96×96 px, tábua 4 px #7d5430 com cantoneiras de metal e rebites; fundo #2a1f3a com lua #c8323a parcial no canto superior direito e silhueta de prédios"}, {"parte": "Dona Socorro", "descricao": "cabeça ~36×40 px, pele #7a4a30, lenço #b8452e com bolinhas #e8c070 e nó atrás, cabelo grisalho #b0aab0 nas têmporas, brincos #f2c230, rugas, xale #6a5a8a sobre blusa #4a6a8a"}, {"parte": "Biu", "descricao": "cabeça ~34×40 px, pele #b07a50, boné #3f6a8c com aba e remendo #8a7a52, cabelo #2a1a14, curativo #e8dcc0 na bochecha, barba rala, camiseta listrada #c8323a/#2a2228 encardida"}, {"parte": "Olhos e boca", "descricao": "olhos 4×3 px (esclera, íris, brilho); piscando = linha de cílio; boca fechada = linha de 6 px; aberta = oval escura 6×4 px com dentes e língua"}], "paleta": [{"nome": "Madeira", "hex": "#7d5430"}, {"nome": "Fundo noite", "hex": "#2a1f3a"}, {"nome": "Lua", "hex": "#c8323a"}, {"nome": "Pele Socorro", "hex": "#7a4a30"}, {"nome": "Lenço", "hex": "#b8452e"}, {"nome": "Pele Biu", "hex": "#b07a50"}, {"nome": "Boné", "hex": "#3f6a8c"}], "arquivo": "sprites/dlg_retrato.png", "fw": 96, "fh": 96, "cols": 4, "quadros": ["Socorro normal", "Socorro piscando", "Socorro boca aberta", "Socorro boca aberta + piscando", "Biu normal", "Biu piscando", "Biu boca aberta", "Biu boca aberta + piscando"], "anims": [{"nome": "socorro_fala", "quadros": [0, 2, 0, 2, 3, 0], "dur": [110, 110, 110, 110, 110, 110], "loop": true}, {"nome": "socorro_pisca", "quadros": [0, 1, 0], "dur": [2900, 120, 10], "loop": true}, {"nome": "biu_fala", "quadros": [4, 6, 4, 6, 7, 4], "dur": [110, 110, 110, 110, 110, 110], "loop": true}, {"nome": "biu_pisca", "quadros": [4, 5, 4], "dur": [2900, 120, 10], "loop": true}], "uso": "Encaixa no nicho da dlg_caixa em (14, 34). O jogo escolhe o quadro: boca abre/fecha enquanto o typewriter escreve, pisca a cada ~3 s (quadro +1).", "w": 384, "h": 192}, {"id": "dlg_balao", "nome": "Balões e emotes", "categoria": "Interface", "mecanica": "Recrutas / Diálogo (REC-01)", "conceito": "Balõezinhos que flutuam sobre a cabeça dos personagens. O balão de fala 💬 com linhas cinzas marca o sobrevivente ainda não recrutado. Os emotes de recruta usam o mesmo balão creme com contorno escuro e rabicho: interrogação, notas musicais, Zz de sono, coração, exclamação vermelha e reticências. Os balões de missão têm borda colorida e ícone: caveira para Caçada e escudo para Proteger. Tudo com sombreado leve e um pouco de sujeira para combinar com o mundo.", "partes": [{"parte": "Balão", "descricao": "oval ~44×34 px centrado em (32, 26), creme #f4efe6 com luz e sombra, contorno #1a0f14, rabicho em (24..30, 44..54) apontando para baixo-esquerda, manchinha de sujeira"}, {"parte": "Ícones", "descricao": "? dourado #f2c230 / notas #4a3a6a / Zz azul #4a8fe0 / coração #d8394a / ! vermelho #c8323a / três pontos #4a4458 / caveira #e8e0d0 em balão de borda vermelha / escudo metal e madeira em balão de borda azul"}], "paleta": [{"nome": "Creme", "hex": "#f4efe6"}, {"nome": "Contorno", "hex": "#1a0f14"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Azul", "hex": "#4a8fe0"}], "arquivo": "sprites/dlg_balao.png", "fw": 64, "fh": 64, "cols": 9, "quadros": ["fala 💬 (não recrutado)", "❓", "🎵", "💤 Zz", "❤", "!", "...", "missão Caçada (caveira)", "missão Proteger (escudo)"], "uso": "Pivô do rabicho em (24, 56): fica ~6 px acima da cabeça do NPC. Flutuar (sobe/desce 2 px) e pop de entrada são transformações em tempo real.", "w": 576, "h": 64}, {"id": "ui_recrutar", "nome": "Barra de tentativa de recrutar", "categoria": "Interface", "mecanica": "Recrutas (REC-09)", "conceito": "Barra de habilidade da tentativa de recrutamento: uma régua de madeira e metal com canaleta escura avermelhada e, no meio, a faixa verde do tamanho da chance. Um marcador dourado (ponteiro com setas em cima e embaixo) corre de um lado para o outro e para; se parar no verde, deu certo. No sucesso a faixa verde acende e solta brilhos; na falha a barra inteira fica vermelha e o marcador some no vermelho com uma rachadura. Há também um quadro só com o marcador para o jogo movimentar.", "partes": [{"parte": "Casco", "descricao": "régua 248×34 px (x 4..251, y 7..40) de madeira #7d5430 com chapas de metal rebitadas nas pontas e no centro"}, {"parte": "Canaleta", "descricao": "x 16..239, y 15..32 (224×18 px), fundo #3a1418 com listras diagonais escuras"}, {"parte": "Faixa verde", "descricao": "centrada em x 128; largura 30% / 60% / 90% da canaleta; verde #4fb06a com luz #9cf0a0 em cima e sombra #2a6a3a, bordas claras; no sucesso fica #9cff9c com halo"}, {"parte": "Marcador", "descricao": "haste 3×26 px #fff2b0 com setas douradas #f2c230 em cima (y 3..9) e embaixo (y 38..44), contorno escuro"}], "paleta": [{"nome": "Verde", "hex": "#4fb06a"}, {"nome": "Verde claro", "hex": "#9cf0a0"}, {"nome": "Canaleta", "hex": "#3a1418"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Falha", "hex": "#c8323a"}], "arquivo": "sprites/ui_recrutar.png", "fw": 256, "fh": 48, "cols": 6, "quadros": ["chance 30%", "chance 60%", "chance 90%", "sucesso (verde brilhando)", "falha (vermelho)", "só o marcador (x 128)"], "uso": "Centro da tela de resultado. A largura real da faixa verde pode ser recortada do quadro 90% (centro em x 128). O marcador (quadro 6, centrado em x 128) é desenhado por cima e movido pelo jogo entre x 16 e 239.", "w": 1536, "h": 48}, {"id": "ui_resumo", "nome": "Prancheta de resumo / relatório", "categoria": "Interface", "mecanica": "Loop / Idle / Invasão (LOOP-08, GRP-13, INV-08)", "conceito": "Prancheta de sobrevivente usada para o resumo ao voltar ('Enquanto você esteve fora') e para o relatório da invasão ao amanhecer. É uma placa de compensado gasta com prendedor de metal enferrujado em cima, segurando uma folha pautada amarelada com margem vermelha, canto dobrado, fita adesiva, marca de copo de café e manchas e digitais de sangue seco. As linhas ficam vazias para o jogo escrever. No relatório a folha ganha caixinhas de checagem na margem e um carimbo vermelho torto com a lua de sangue no canto.", "partes": [{"parte": "Prancheta", "descricao": "placa 240×174 px (x 8..247, y 14..187) #8a5a32/#6a4226 com veio, cantos arredondados lascados e furo de pendurar"}, {"parte": "Prendedor", "descricao": "clipe de metal 60×26 px (x 98..157, y 2..27) #8d969c com mola, 2 rebites, ferrugem #8a4e2e"}, {"parte": "Folha", "descricao": "papel #e8dfc8 (x 20..235, y 24..179) com 11 linhas azuis #9aa8c0 a cada 12 px, margem vermelha #c86060 em x 42, canto inferior direito dobrado, borda direita rasgada"}, {"parte": "Sujeira", "descricao": "mancha e respingos de sangue #6a1a1e/#8a2228, digital, anel de café #a88a60, fita adesiva #e8e0b0 translúcida"}, {"parte": "Carimbo (relatório)", "descricao": "círculo duplo vermelho #c8323a de ~44 px girado -14°, lua crescente no meio, tinta falhada; + caixinhas 6×6 px nas linhas"}], "paleta": [{"nome": "Compensado", "hex": "#8a5a32"}, {"nome": "Papel", "hex": "#e8dfc8"}, {"nome": "Pauta", "hex": "#9aa8c0"}, {"nome": "Margem", "hex": "#c86060"}, {"nome": "Sangue seco", "hex": "#6a1a1e"}, {"nome": "Metal", "hex": "#8d969c"}, {"nome": "Carimbo", "hex": "#c8323a"}], "arquivo": "sprites/ui_resumo.png", "fw": 256, "fh": 192, "cols": 2, "quadros": ["resumo da volta / enquanto você esteve fora", "relatório da invasão (carimbo vermelho)"], "uso": "Painel modal no centro da tela. Título na linha de cima (y ~34..46), uma linha de texto a cada 12 px a partir de y 52, x 48..226. Entra com pop/queda pelo jogo.", "w": 512, "h": 192}]}, {"grupo": "vasculhar", "titulo": "Vasculhar: contêineres e loot", "ordem": 3, "resumo": "Contêineres sólidos do cenário que o herói revira segurando a ação (lixeira, caixote, geladeira, armário de hospital e carro), com quadros de fechado, sendo revirado, abrindo com luz e vasculhado (apagado com ✓ verde), mais o anel de progresso, os efeitos de abertura por raridade, os 20 ícones de loot e a aura de raridade no chão.", "itens": [{"id": "vas_lixeira", "nome": "Lixeira da prefeitura", "categoria": "Vasculhar", "mecanica": "Vasculhar (VAS-01..09, VAS-14..20) — busca 1,0 s, 1–2 itens: Sucata, Pano · Comida enlatada, Pilha · Antídoto", "conceito": "Contêiner de lixo de rua de 240 L, de plástico laranja da prefeitura do Recife, com tampa articulada escura, rodinhas pretas e alça de metal atrás. Depois da Lua de Sangue ninguém mais recolheu nada: os sacos transbordam, um saco preto rasgado está caído ao lado espalhando papel, casca de banana e lata amassada, e as moscas não largam a tampa. O plástico tem nervuras verticais em relevo, arranhões claros, sujeira escura subindo da base, um adesivo de reciclagem descascando e respingos de sangue seco. É o contêiner mais rápido e barulhento, lido de longe pela cor laranja viva.", "partes": [{"parte": "Corpo", "descricao": "trapézio laranja #e0701e de 68×52 px (x 30–98, y 54–106), mais largo em cima; 4 nervuras verticais (linha escura #b4561a + clara #f39a4a), sujeira #a5501a na base, arranhões, selo de reciclagem branco/verde (círculo r7) e etiqueta branca de número, respingos de sangue #6a1a1a."}, {"parte": "Tampa", "descricao": "laje 76×12 px laranja-escuro #c85a18 com frisos e aba frontal #b04e16. Fechada: deitada, com a ponta de um saco preto escapando. Vasculhando: levantada 3 px e 6 px na frente com fresta escura e trapo vermelho pendurado. Aberta: tombada para trás, em pé (76×28 px) mostrando o verso."}, {"parte": "Rodas e eixo", "descricao": "duas rodas pretas r5 em x 40 e 88 com cubo cinza, barra de eixo #3a3636."}, {"parte": "Lixo no chão", "descricao": "saco preto #2a2630 rasgado (22×16 px) à esquerda com papel #d8d0b8 e casca de banana #d8b040 saindo; lata vermelha amassada e jornal à direita; mais lixo jogado no estado vasculhado."}, {"parte": "Moscas", "descricao": "3–5 pontinhos #1a1418 com asa clara #cfd6e0 sobre a tampa; mudam de lugar e se agitam nos quadros de busca."}, {"parte": "Interior", "descricao": "boca escura #1c1218 de 68×10 px; no brilho, sacos iluminados por luz quente; no vasculhado, vazio."}], "paleta": [{"nome": "Laranja prefeitura", "hex": "#e0701e"}, {"nome": "Laranja sombra", "hex": "#b4561a"}, {"nome": "Tampa", "hex": "#c85a18"}, {"nome": "Saco preto", "hex": "#2a2630"}, {"nome": "Sangue seco", "hex": "#6a1a1a"}, {"nome": "Borracha", "hex": "#2a2626"}], "arquivo": "sprites/vas_lixeira.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["fechado", "vasculhando 1", "vasculhando 2", "abrindo (brilho)", "vasculhado (aberto, ✓)"], "anims": [{"nome": "vasculhando", "quadros": [1, 2], "dur": [140, 140], "loop": true}, {"nome": "abrir", "quadros": [3, 4], "dur": [600, 1200], "loop": false}], "uso": "Âncora no centro da base (64, 112), gy = 112, camada de objetos ordenada por y. Sólido (hitbox ~68×20 px na base). O wobble (±4°) e o squash/stretch/slam (VAS-14..16) são transformações em tempo real sobre o quadro de busca, com pivô na base. O quadro 'abrindo' dura o clarão (VAS-17), depois fica o 'vasculhado' até a região renascer.", "w": 640, "h": 128}, {"id": "vas_caixa", "nome": "Caixote de feira", "categoria": "Vasculhar", "mecanica": "Vasculhar (VAS-01..09, VAS-14..20) — busca 1,5 s, 2–3 itens: Madeira, Pregos · Corda, Fita adesiva · Munição", "conceito": "Caixote pesado de madeira da feira de São José, com tábuas pregadas, travessa diagonal na frente e tampa de ripas lacrada com fita silver tape. Alguém encheu de mantimentos e palha para guardar e nunca voltou. A madeira tem veios, pregos enferrujados, um carimbo vermelho de 'FRÁGIL' meio apagado e uma mão de sangue seco na quina. No chão ficam folhas de couve e um tomate esmagado da feira abandonada. Lê de longe como um bloco marrom com a faixa prata da fita.", "partes": [{"parte": "Frente", "descricao": "68×44 px (x 30–98, y 64–108): montantes #7d5430 de 8 px nas quinas, 3 tábuas #9a6a3c com veios e frestas escuras #3a2414, travessa diagonal #8b5e34 de 7 px, pregos #c9c3b0 com ferrugem, carimbo vermelho #a8323a pontilhado."}, {"parte": "Tampa", "descricao": "3 ripas #a87444 de 68×5 px vistas de cima (y 48–64) com fita prata #a8acb0 de 12 px descendo pela frente. Vasculhando: levanta 3/6 px na frente, fita rasgada e palha escapando. Aberta: em pé atrás, articulada."}, {"parte": "Interior", "descricao": "cavidade #24160e com palha #d6b45a; vazia e palha espalhada no chão no vasculhado."}, {"parte": "Resto de feira", "descricao": "folha de couve #6a8a3a e tomate #c03a2a esmagado no chão, fiapos de palha."}], "paleta": [{"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua escura", "hex": "#7d5430"}, {"nome": "Fresta", "hex": "#3a2414"}, {"nome": "Fita prata", "hex": "#a8acb0"}, {"nome": "Palha", "hex": "#d6b45a"}, {"nome": "Carimbo", "hex": "#a8323a"}], "arquivo": "sprites/vas_caixa.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["fechado", "vasculhando 1", "vasculhando 2", "abrindo (brilho)", "vasculhado (aberto, ✓)"], "anims": [{"nome": "vasculhando", "quadros": [1, 2], "dur": [140, 140], "loop": true}, {"nome": "abrir", "quadros": [3, 4], "dur": [600, 1200], "loop": false}], "uso": "Âncora (64, 112), gy = 112. Sólido, hitbox 68×20 px. Wobble e squash são em tempo real com pivô na base; o sprite só troca a tampa entreaberta entre os quadros 1 e 2.", "w": 640, "h": 128}, {"id": "vas_geladeira", "nome": "Geladeira velha", "categoria": "Vasculhar", "mecanica": "Vasculhar (VAS-01..09, VAS-14..20) — busca 1,5 s, 1–3 itens: Água · Comida enlatada · Antídoto", "conceito": "Geladeira antiga de uma porta grande e congelador em cima, de esmalte branco que virou bege sujo, largada de pé na calçada. Tem cantos arredondados, puxadores cromados, grade escura embaixo e ferrugem comendo as bordas e a base. A porta está cheia de ímãs (tomate, disk-pizza, um bilhete preso) e, em cima, o clássico pinguim de geladeira sobre um paninho de crochê. Uma mão de sangue escorrida marca o congelador. Ao abrir, a porta gira para a esquerda mostrando as prateleiras e uma luz interna fraca e fria.", "partes": [{"parte": "Gabinete", "descricao": "48×82 px (x 40–88, y 26–108) esmalte #d8d2c2, topo #e4dfd2 de 10 px, cantos de cima arredondados, ferrugem #8a4e2e nas bordas e base, lascas escuras, encardido #a89c84 embaixo."}, {"parte": "Portas", "descricao": "congelador 46×23 px e porta principal 46×55 px, puxadores cromados #b8bcc0 verticais à direita, emblema cromado ilegível. Vasculhando: a porta principal desencosta (fresta de 2 px e depois 7 px) com luz fria #e8f6ff. Aberta: porta girada à esquerda (20 px de largura em perspectiva) mostrando o lado de dentro cinza #cfd2cc com prateleirinhas."}, {"parte": "Ímãs e bilhete", "descricao": "tomate vermelho r2, retângulo amarelo de disk-pizza, ímã azul, bilhete creme rabiscado; mancha de mão de sangue #6a1a1a escorrendo."}, {"parte": "Pinguim e crochê", "descricao": "pinguim de louça 10×14 px preto/branco com bico amarelo sobre paninho de crochê creme com bordas de bolinhas."}, {"parte": "Interior", "descricao": "cavidade #8f968f com grades cromadas e fundo mais escuro; no brilho fica clara com garrafas em silhueta; vasculhada, escura e vazia."}, {"parte": "Base", "descricao": "grade 44×6 px escura com frestas e pezinhos pretos."}], "paleta": [{"nome": "Esmalte branco sujo", "hex": "#d8d2c2"}, {"nome": "Encardido", "hex": "#a89c84"}, {"nome": "Cromado", "hex": "#b8bcc0"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Interior", "hex": "#8f968f"}, {"nome": "Luz interna", "hex": "#e8f6ff"}], "arquivo": "sprites/vas_geladeira.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["fechado", "vasculhando 1", "vasculhando 2", "abrindo (brilho)", "vasculhado (aberto, ✓)"], "anims": [{"nome": "vasculhando", "quadros": [1, 2], "dur": [140, 140], "loop": true}, {"nome": "abrir", "quadros": [3, 4], "dur": [600, 1200], "loop": false}], "uso": "Âncora (64, 112), gy = 112. Sólido, hitbox 48×16 px na base; alta, então o herói pode passar atrás (ordenar por y). Wobble/squash/slam em tempo real com pivô na base.", "w": 640, "h": 128}, {"id": "vas_armario", "nome": "Armário de hospital", "categoria": "Vasculhar", "mecanica": "Vasculhar (VAS-01..09, VAS-14..20) — busca 2,0 s, 1–2 itens: Pano · Atadura · Kit médico", "conceito": "Armário de aço duplo de vestiário de hospital, verde-acinzentado, com venezianas no alto das portas, plaquinhas de número e uma cruz vermelha pintada num círculo branco. A porta da esquerda foi amassada a pancadas por quem tentou entrar e ainda tem um cadeado de latão. A tinta descasca mostrando metal e ferrugem, há um adesivo amarelo de risco biológico e sangue escorrendo do alto. Em cima ficou uma toalha azul dobrada e uma cuba de inox. Ao abrir, a porta amassada gira para a esquerda e o cadeado quebrado cai no chão.", "partes": [{"parte": "Gabinete", "descricao": "60×78 px (x 34–94, y 30–108) aço #9aa59c, topo #b2bcb2 de 8 px, rodapé escuro #3e4440."}, {"parte": "Porta esquerda (amassada)", "descricao": "29×74 px, 5 venezianas no alto, amassado oval com vincos claros/escuros, tinta lascada #c9ced4 e ferrugem #8a4e2e, cadeado de latão #c9a040. Vasculhando: desencosta 2 px e depois 8 px com algo branco aparecendo. Aberta: girada para a esquerda mostrando espelhinho e foto colada por dentro."}, {"parte": "Porta direita", "descricao": "28×74 px, venezianas, cruz vermelha #c8323a 12×12 px em círculo branco #e8e4da, puxador cromado, adesivo de risco biológico amarelo #e0b030."}, {"parte": "Interior", "descricao": "cavidade #2a2e2c com prateleira, gancho e jaleco verde pendurado; no vasculhado só um cabide."}, {"parte": "Topo", "descricao": "toalha azul #3f6a8c dobrada e cuba de inox."}], "paleta": [{"nome": "Aço verde-cinza", "hex": "#9aa59c"}, {"nome": "Aço sombra", "hex": "#6e7a72"}, {"nome": "Cruz vermelha", "hex": "#c8323a"}, {"nome": "Branco", "hex": "#e8e4da"}, {"nome": "Latão", "hex": "#c9a040"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}], "arquivo": "sprites/vas_armario.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["fechado", "vasculhando 1", "vasculhando 2", "abrindo (brilho)", "vasculhado (aberto, ✓)"], "anims": [{"nome": "vasculhando", "quadros": [1, 2], "dur": [140, 140], "loop": true}, {"nome": "abrir", "quadros": [3, 4], "dur": [600, 1200], "loop": false}], "uso": "Âncora (64, 112), gy = 112. Sólido, hitbox 60×16 px. Wobble/squash em tempo real com pivô na base; é o contêiner mais lento (2 s).", "w": 640, "h": 128}, {"id": "vas_carro", "nome": "Carro abandonado", "categoria": "Vasculhar", "mecanica": "Vasculhar (VAS-01..09, VAS-14..20) — busca 2,5 s, 2–3 itens: Sucata, Peças · Gasolina · Bateria", "conceito": "Hatch popular de duas portas dos anos 90, quadradão, azul-petróleo desbotado e sem marca, largado no meio da rua desde a primeira noite. O vidro da porta foi estourado, o pneu da frente está murcho, há ferrugem nas caixas de roda e na base das portas, amassados na lateral e uma mancha de sangue seco com mão escorrida na porta. A placa caiu e está torta no chão, ilegível. Nos estados de busca o capô desencosta e o porta-malas levanta; vasculhado, fica com capô e tampa traseira escancarados, sem bateria. É o maior contêiner e o mais demorado.", "partes": [{"parte": "Lataria lateral", "descricao": "~210×50 px (x 24–236, y 114–166) azul-petróleo #4f7f8c com textura, friso preto #26222a, vinco de porta, maçaneta, tampa de combustível, amassados, ferrugem #8a4e2e/#5a2e1a nas caixas de roda, sangue seco #5a1414."}, {"parte": "Cabine e teto", "descricao": "teto visto de cima #6a9aa6 de 104×16 px com antena torta, janelas #2a3a4a, coluna B preta; vidro da porta estilhaçado com rachaduras claras e cacos no chão; para-brisa inclinado com reflexo."}, {"parte": "Capô", "descricao": "superfície de cima 40×16 px; vasculhando: levanta 3/7 px na frente com fresta escura; aberto: em pé (pivô no para-brisa) mostrando o forro cinza; vão do motor com bloco, filtro redondo e cabos da bateria soltos."}, {"parte": "Porta-malas", "descricao": "tampa traseira com vidro; aberta: levantada para cima-esquerda (pivô no teto), mostrando o bagageiro escuro com estepe."}, {"parte": "Rodas", "descricao": "pneus #1e1a1c r17 em x 72 e 190, aro cinza #8d969c com parafusos; o da frente murcho (achatado 19×12 px)."}, {"parte": "Para-choques e luzes", "descricao": "para-choques pretos de plástico, farol quadrado (um quebrado), lanterna vermelha atrás, placa caída no chão (branca com faixa azul e marcas ilegíveis)."}], "paleta": [{"nome": "Azul-petróleo desbotado", "hex": "#4f7f8c"}, {"nome": "Teto", "hex": "#6a9aa6"}, {"nome": "Vidro", "hex": "#2a3a4a"}, {"nome": "Plástico preto", "hex": "#2c2a2e"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sangue seco", "hex": "#5a1414"}, {"nome": "Pneu", "hex": "#1e1a1c"}], "arquivo": "sprites/vas_carro.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["fechado", "vasculhando 1 (capô desencostando)", "vasculhando 2 (capô e porta-malas entreabertos)", "abrindo (brilho)", "vasculhado (aberto, ✓)"], "anims": [{"nome": "vasculhando", "quadros": [1, 2], "dur": [160, 160], "loop": true}, {"nome": "abrir", "quadros": [3, 4], "dur": [600, 1200], "loop": false}], "uso": "Âncora (128, 180), gy = 180 num quadro 256×192, ocupa 2×1 tiles. Sólido, hitbox ~210×22 px. Wobble menor (±2°) e squash em tempo real com pivô na base.", "w": 1280, "h": 192}, {"id": "vas_anel", "nome": "Anel de progresso de vasculhar", "categoria": "UI", "mecanica": "VAS-03 (segurar para vasculhar), VAS-04 (progresso guardado)", "conceito": "Anel de progresso que flutua sobre o contêiner enquanto o herói segura a ação. É um aro escuro translúcido com contorno, que vai enchendo no sentido horário a partir do topo com uma faixa creme-dourada brilhante, e uma lupa pequena no meio indica a ação de vasculhar. A ponta que avança tem uma faísca clara. No último quadro o anel completo brilha em dourado com estrelinhas e um ✓ no lugar da lupa.", "partes": [{"parte": "Trilho", "descricao": "aro de raio 23 px e 6 px de espessura, #1c1622 com alfa ~70%, contorno escuro e reflexo interno claro."}, {"parte": "Preenchimento", "descricao": "arco creme #f4e2a8 com borda de luz #fff6d8 e sombra #c89a3a, de 1/8 a 8/8; ponta com faísca branca."}, {"parte": "Ícone central", "descricao": "lupa 14×14 px (aro cromado, lente azulada, cabo marrom); no completo vira ✓ verde #5bd46e."}, {"parte": "Brilho completo", "descricao": "halo dourado #f2c230 e 4 faíscas em volta."}], "paleta": [{"nome": "Trilho", "hex": "#1c1622"}, {"nome": "Progresso", "hex": "#f4e2a8"}, {"nome": "Luz", "hex": "#fff6d8"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Verde ✓", "hex": "#5bd46e"}], "arquivo": "sprites/vas_anel.png", "fw": 64, "fh": 64, "cols": 9, "quadros": ["1/8", "2/8", "3/8", "4/8", "5/8", "6/8", "7/8", "8/8", "completo (brilho)"], "anims": [{"nome": "enchendo", "quadros": [0, 1, 2, 3, 4, 5, 6, 7, 8], "dur": [125, 125, 125, 125, 125, 125, 125, 125, 400], "loop": false}], "uso": "Centro (32, 32) posicionado ~20 px acima do topo do contêiner. O jogo escolhe o quadro pela fração do progresso (floor(p*8)); o quadro 8 aparece no fim, antes do stretch/slam.", "w": 576, "h": 64}, {"id": "vas_fx_abrir", "nome": "Efeitos de abertura", "categoria": "FX", "mecanica": "VAS-17 (light), VAS-18 (shockwave), VAS-19 (stars), VAS-20 (magic dust), VAS-21", "conceito": "Folha de efeitos do momento em que o contêiner abre, um conjunto por raridade (linhas: comum cinza-osso, incomum verde, raro azul). Primeiro um clarão com 12 raios que giram e crescem a partir do contêiner, com núcleo branco. No chão, um anel de onda em elipse se expande e afina até sumir. Por fim estrelas de 5 pontas giram saltando para os lados enquanto brilhinhos de pó mágico sobem. Tudo é semitransparente e em degraus de alfa, sem degradê liso.", "partes": [{"parte": "Clarão (3 quadros)", "descricao": "núcleo r10–16 branco + halo na cor da raridade; 12 raios em cunha de 40 a 84 px girando 0°, 8°, 16°; alfa 200 → 90."}, {"parte": "Shockwave (3 quadros)", "descricao": "elipse no chão (centro 96,132) rx 34 → 62 → 86, ry = 0,38·rx, espessura 7 → 4 → 2 px, alfa caindo."}, {"parte": "Estrelas + pó (2 quadros)", "descricao": "7 estrelas r3–5 na cor clara da raridade com contorno, girando e caindo em arco; 12–16 brilhinhos em cruz subindo."}], "paleta": [{"nome": "Comum", "hex": "#b9b0a0"}, {"nome": "Incomum", "hex": "#4fb06a"}, {"nome": "Raro", "hex": "#4a8fe0"}, {"nome": "Núcleo", "hex": "#ffffff"}], "arquivo": "sprites/vas_fx_abrir.png", "fw": 192, "fh": 192, "cols": 8, "quadros": ["comum clarão 1", "comum clarão 2", "comum clarão 3", "comum onda 1", "comum onda 2", "comum onda 3", "comum estrelas 1", "comum estrelas 2", "incomum clarão 1", "incomum clarão 2", "incomum clarão 3", "incomum onda 1", "incomum onda 2", "incomum onda 3", "incomum estrelas 1", "incomum estrelas 2", "raro clarão 1", "raro clarão 2", "raro clarão 3", "raro onda 1", "raro onda 2", "raro onda 3", "raro estrelas 1", "raro estrelas 2"], "anims": [{"nome": "clarão comum", "quadros": [0, 1, 2], "dur": [200, 200, 200], "loop": true}, {"nome": "onda comum", "quadros": [3, 4, 5], "dur": [130, 130, 140], "loop": true}, {"nome": "estrelas comum", "quadros": [6, 7], "dur": [350, 350], "loop": true}, {"nome": "clarão incomum", "quadros": [8, 9, 10], "dur": [200, 200, 200], "loop": true}, {"nome": "onda incomum", "quadros": [11, 12, 13], "dur": [130, 130, 140], "loop": true}, {"nome": "clarão raro", "quadros": [16, 17, 18], "dur": [200, 200, 200], "loop": true}, {"nome": "onda raro", "quadros": [19, 20, 21], "dur": [130, 130, 140], "loop": true}, {"nome": "estrelas raro", "quadros": [22, 23], "dur": [350, 350], "loop": true}], "uso": "Centro do quadro (96, 96) no centro do contêiner; a onda tem centro em (96, 132) = base do contêiner. Desenhar em camada de FX acima dos objetos, aditivo opcional. Linha = cor da maior raridade obtida. A rotação extra dos raios e a queda das estrelas podem ser interpoladas em tempo real; tudo some se os efeitos estiverem desligados (VAS-21).", "w": 1536, "h": 576}, {"id": "vas_itens", "nome": "Itens de loot", "categoria": "Itens", "mecanica": "Tabela de loot dos contêineres (VAS-01, VAS-07, VAS-08), HP-11 (antídoto), BMB-01 (pólvora), minions (coração)", "conceito": "Os 20 recursos que saem do vasculhar, desenhados como objetos caídos no chão vistos de cima em 3/4, com sombra, contorno e muito desgaste. Cada um tem silhueta própria para ler a 64 px: sucata enferrujada, pano xadrez dobrado, lata com rótulo, pilhas, frasco de antídoto verde, tábuas amarradas, pregos, rolo de corda, silver tape, caixinha de munição aberta, garrafa pet de água, atadura, kit médico, engrenagens, galão de gasolina, bateria de carro, pedras, saco de pólvora, macaxeira com milho da horta e o coração de cura dos minions. Servem tanto no chão (pop do loot) quanto como ícone na mochila.", "partes": [{"parte": "Sucata", "descricao": "chapa dobrada #6b6a66 com ferrugem #8a4e2e, cano e parafuso, 40×26 px."}, {"parte": "Pano", "descricao": "pilha de panos xadrez vermelho/creme dobrados com franja rasgada, 40×24 px."}, {"parte": "Comida enlatada", "descricao": "lata de 20×26 px com rótulo vermelho/amarelo, tampa com anel e amassado, segunda lata deitada."}, {"parte": "Pilha", "descricao": "duas pilhas AA (cobre/preto, polo prata) deitadas cruzadas."}, {"parte": "Antídoto", "descricao": "frasco de vidro com líquido verde #5bd46e brilhando, rolha, rótulo com cruz."}, {"parte": "Madeira", "descricao": "3 tábuas #9a6a3c amarradas com corda, pontas com anéis."}, {"parte": "Pregos", "descricao": "montinho de pregos #c9c3b0 com cabeças e alguns soltos, ferrugem."}, {"parte": "Corda", "descricao": "rolo de corda #b59a62 trançada com ponta e nó."}, {"parte": "Fita adesiva", "descricao": "rolo de silver tape em elipse com furo de papelão e ponta solta."}, {"parte": "Munição", "descricao": "caixinha verde-oliva aberta com fileira de cartuchos de latão e ogivas de cobre, 2 soltos."}, {"parte": "Água", "descricao": "garrafa pet 2 L azulada com tampa azul, rótulo e reflexo, uma deitada atrás."}, {"parte": "Atadura", "descricao": "rolo branco com ponta desenrolada e grampo."}, {"parte": "Kit médico", "descricao": "maleta branca com cruz vermelha, alça e fechos, arranhada."}, {"parte": "Peças", "descricao": "engrenagem grande e pequena de aço, parafuso, porca e mola."}, {"parte": "Gasolina", "descricao": "galão vermelho #b83a2a de 20 L com alça, bico e tampa amarela, gota escorrendo."}, {"parte": "Bateria de carro", "descricao": "caixa preta 36×24 px com polos vermelho/preto, etiqueta e alça."}, {"parte": "Pedra", "descricao": "duas pedras cinza #8e8a84 com faces e musgo."}, {"parte": "Pólvora", "descricao": "saquinho de juta amarrado com chama pintada e pó preto escorrendo."}, {"parte": "Comida da horta", "descricao": "duas macaxeiras marrons com ponta branca e espiga de milho amarela com palha verde."}, {"parte": "Coração", "descricao": "coração vermelho brilhante #e8506a com reflexo e cruz verde de cura (+20 para minion)."}], "paleta": [{"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Madeira", "hex": "#9a6a3c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Verde antídoto", "hex": "#5bd46e"}, {"nome": "Vermelho galão", "hex": "#b83a2a"}, {"nome": "Coração", "hex": "#e8506a"}], "arquivo": "sprites/vas_itens.png", "fw": 64, "fh": 64, "cols": 6, "quadros": ["Sucata", "Pano", "Comida enlatada", "Pilha", "Antídoto", "Madeira", "Pregos", "Corda", "Fita adesiva", "Munição", "Água", "Atadura", "Kit médico", "Peças", "Gasolina", "Bateria de carro", "Pedra", "Pólvora", "Comida (horta)", "Coração (cura de minion +20)"], "uso": "Âncora (32, 52) = base do item, gy = 52 com sombra própria. No pop (VAS-07) o arco e o quique são em tempo real; a aura de raridade (vas_raridade) vai por baixo. Na mochila/HUD usar o mesmo quadro.", "w": 384, "h": 256}, {"id": "vas_raridade", "nome": "Aura de raridade no chão", "categoria": "FX", "mecanica": "VAS-07 (cor e brilho da raridade), raridades do contrato", "conceito": "Brilho que fica no chão por baixo de cada item caído, para o jogador ler a raridade de longe à noite. É uma elipse luminosa em degraus com anel de borda, e a partir do incomum sobe um feixe vertical fraco; o raro tem feixe mais alto e o lunar é vermelho-lua com faíscas douradas. São 2 quadros por raridade (fraco/forte) que piscam em loop.", "partes": [{"parte": "Elipse de chão", "descricao": "rx 24, ry 9 px centrada em (32, 52), anel de borda 1 px mais claro, alfa em degraus."}, {"parte": "Feixe", "descricao": "coluna vertical de 14–18 px de largura subindo 20/34/44 px (incomum/raro/lunar), alfa decrescente."}, {"parte": "Faíscas", "descricao": "2–5 brilhinhos em cruz, dourados #f2c230 no lunar."}], "paleta": [{"nome": "Comum", "hex": "#b9b0a0"}, {"nome": "Incomum", "hex": "#4fb06a"}, {"nome": "Raro", "hex": "#4a8fe0"}, {"nome": "Lunar", "hex": "#c8323a"}, {"nome": "Dourado", "hex": "#f2c230"}], "arquivo": "sprites/vas_raridade.png", "fw": 64, "fh": 64, "cols": 2, "quadros": ["comum fraco", "comum forte", "incomum fraco", "incomum forte", "raro fraco", "raro forte", "lunar fraco", "lunar forte"], "anims": [{"nome": "comum", "quadros": [0, 1], "dur": [400, 400], "loop": true}, {"nome": "incomum", "quadros": [2, 3], "dur": [350, 350], "loop": true}, {"nome": "raro", "quadros": [4, 5], "dur": [300, 300], "loop": true}, {"nome": "lunar", "quadros": [6, 7], "dur": [250, 250], "loop": true}], "uso": "Mesma âncora do ícone de item (32, 52); desenhar por baixo do item, na camada do chão, com pulso de escala opcional em tempo real.", "w": 128, "h": 256}]}, {"grupo": "baus", "titulo": "Baús, chaves e puzzles", "ordem": 4, "resumo": "Os três baús (madeira, ferro e Lua de Sangue) com todos os estados do puzzle/chave/abertura/emperrado, as chaves e a gazua, as peças de UI dos mini puzzles, os itens exclusivos de baú e o feixe dourado de respawn (LUA-06 / BF-13).", "itens": [{"id": "bau_madeira", "nome": "Baú de madeira", "categoria": "Baú", "mecanica": "Baús (BAU-01..07, BAU-11, BAU-13, BAU-15, BAU-17, BAU-19, BAU-22, BAU-23, BAU-08)", "conceito": "Baú de carga de madeira de lei, daqueles de porão de casarão antigo do Recife, achado em casas saqueadas e no fim das hordas. Tampa abaulada (de pirata) feita de 6 ripas curvas, corpo de 4 tábuas horizontais, duas cintas verticais de ferro escuro com rebites e cantoneiras nas quinas. A fechadura é uma chapa de bronze em escudo com buraco de chave, e na tampa desce um ferrolho de bronze. Tem arranhões de unha de zumbi, um nó na madeira, uma mancha de sangue seco e ferrugem escorrendo das cintas. Em jogo lê como o baú mais simples: marrom quente e bronze, puzzles fáceis (gazua, números, pares) e chave de bronze.", "partes": [{"parte": "Corpo (frente)", "descricao": "72×28 px na frente + 5 px de lateral direita (vista 3/4, a lateral fica na sombra). 4 tábuas de 7 px alternando #9a6a3c/#8b5e34, frestas #5a3a22, veios curtos escuros, 1 nó, 3 arranhões claros de unha, mancha de sangue #5a1a1a."}, {"parte": "Cintas e cantoneiras", "descricao": "2 cintas de ferro de 6 px (#5d5f63, ferrugem #8a4e2e) atravessando corpo e tampa, cantoneiras de 4 px nas quinas, rebites 2×2 #c9c3b0 em cada tábua."}, {"parte": "Tampa abaulada", "descricao": "faixa frontal de 8 px + arco de 6 ripas (altura +9 px), cada ripa com tom próprio; gira na dobradiça de trás (0°, 35°, 75°, 108°). Aberta mostra o forro interno de tábua escura #5a3a22."}, {"parte": "Fechadura de bronze", "descricao": "chapa em escudo 14×14 px #b87333 com brilho #e0a85a, 4 rebites e buraco de chave preto; ferrolho de 8×7 px na tampa."}, {"parte": "Pés", "descricao": "4 tocos de madeira 6×3 px sob as quinas."}, {"parte": "Chave girando", "descricao": "chave de bronze na fechadura: quadro 1 o anel de frente (círculo 10 px com furo), quadro 2 de perfil (barra fina 3×11 px) + arcos de giro e faíscas."}, {"parte": "Interior", "descricao": "rim de 3 px, fundo #1a1214, parede de trás e lateral esquerda de tábua escura; aberto cheio tem luz dourada, raios (camada fx semi-transparente) e 3 itens pulando (faca, lanterna, mapa)."}, {"parte": "Emperrado", "descricao": "2 correntes de aço em X por cima da frente (elos de 6 px #8d969c), cadeado torto (−18°) no cruzamento, fumacinha cinza saindo da fechadura e selo de X vermelho #c8323a no canto superior direito."}], "paleta": [{"nome": "Tábua clara", "hex": "#9a6a3c"}, {"nome": "Tábua", "hex": "#8b5e34"}, {"nome": "Tábua escura/fresta", "hex": "#5a3a22"}, {"nome": "Ferro das cintas", "hex": "#5d5f63"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Rebite", "hex": "#c9c3b0"}, {"nome": "Bronze", "hex": "#b87333"}, {"nome": "Bronze brilho", "hex": "#e0a85a"}, {"nome": "Sangue seco", "hex": "#5a1a1a"}, {"nome": "Luz dourada", "hex": "#ffe7a0"}], "arquivo": "sprites/bau_madeira.png", "fw": 128, "fh": 128, "cols": 11, "quadros": ["fechado", "chacoalhando 1 (erro, inclina p/ esquerda)", "chacoalhando 2 (erro, inclina p/ direita)", "chave girando 1 (de frente)", "chave girando 2 (de perfil)", "tampa abrindo 1 (35°)", "tampa abrindo 2 (75°)", "aberto com luz e itens", "aberto vazio", "emperrado 1", "emperrado 2"], "anims": [{"nome": "erro (chacoalhar)", "quadros": [1, 2, 1, 2, 0], "dur": [60, 60, 60, 60, 200], "loop": false}, {"nome": "abrir com chave", "quadros": [3, 4, 3, 4], "dur": [110, 115, 110, 115], "loop": false}, {"nome": "abrir", "quadros": [0, 5, 6, 7], "dur": [120, 90, 90, 700], "loop": false}, {"nome": "emperrado", "quadros": [9, 10], "dur": [320, 320], "loop": true}], "uso": "Objeto de mapa 128×128, pivô no centro da base (64, 110), gy=110, camada dos objetos com sombra própria. Chacoalhar, esticar/achatar (VAS-14..16), raios girando, onda e estrelas (VAS-17..20) são transformações/efeitos em tempo real por cima; estes quadros dão a pose base. O quadro 'aberto vazio' fica no mapa depois de saqueado (BAU-13). Emperrado fica até o fim da expedição, mas ainda abre com chave (BAU-19).", "w": 1408, "h": 128}, {"id": "bau_ferro", "nome": "Baú de ferro (militar)", "categoria": "Baú", "mecanica": "Baús (BAU-01..07, BAU-09, BAU-11, BAU-15..19, BAU-24, BAU-25)", "conceito": "Caixa-forte militar de aço, pintada de verde-oliva do Exército, largada nos postos de bloqueio e nos caminhões do quartel quando a cidade caiu. Tampa chata e reforçada com aba, moldura de aço rebitada em todas as bordas, nervuras verticais, duas travas de alavanca nas laterais da frente e uma fechadura central de prata polida. A tinta está lascada nas quinas mostrando o aço, há ferrugem escorrendo dos rebites, estêncil de estrela e o número 07 meio apagados, e uma alça de carga em U na lateral e outra no topo. Lê como baú do meio: frio, cinza-esverdeado e prata, puzzles de memória, fios e canos, abre com chave de prata.", "partes": [{"parte": "Corpo (frente)", "descricao": "72×28 px, verde-oliva #4f5b3a com lascas de aço #8d969c nas quinas, moldura de aço de 3 px #6b747a com rebites #c9ced4 a cada 6 px, 2 nervuras verticais de 3 px, estêncil de estrela e '07' #d8d4c0 apagados, escorridos de ferrugem #8a4e2e."}, {"parte": "Travas", "descricao": "2 travas de alavanca 7×10 px de aço #7d848c nas laterais da frente, com pino e sombra."}, {"parte": "Fechadura de prata", "descricao": "placa 14×13 px #c9ced4 com brilho #f2f5f7, borda chanfrada, buraco de chave e 4 parafusos; aba de prata na tampa."}, {"parte": "Tampa chata", "descricao": "faixa frontal de 10 px e topo de 26 px de fundo (14 px na tela) com moldura rebitada, faixa de aviso amarelo/preto #d8b030/#1e1e1e e alça de carga em barra no topo. Aberta mostra o interior cinza com espuma #3a3f3a."}, {"parte": "Lateral", "descricao": "lado direito em sombra com alça em U de aço e rebites."}, {"parte": "Pés", "descricao": "2 esquis de aço 72×3 px sob o corpo."}, {"parte": "Interior aberto", "descricao": "fundo escuro, luz azul-branca de item raro #bfe0ff, raios e itens (pistola, kit médico)."}, {"parte": "Emperrado", "descricao": "correntes em X, cadeado torto, fumaça e X vermelho (igual ao de madeira)."}], "paleta": [{"nome": "Verde-oliva", "hex": "#4f5b3a"}, {"nome": "Oliva claro", "hex": "#65734a"}, {"nome": "Aço", "hex": "#6b747a"}, {"nome": "Aço lascado", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Prata", "hex": "#c9ced4"}, {"nome": "Prata brilho", "hex": "#f2f5f7"}, {"nome": "Estêncil", "hex": "#d8d4c0"}, {"nome": "Faixa de aviso", "hex": "#d8b030"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Luz azul", "hex": "#bfe0ff"}], "arquivo": "sprites/bau_ferro.png", "fw": 128, "fh": 128, "cols": 11, "quadros": ["fechado", "chacoalhando 1 (erro, inclina p/ esquerda)", "chacoalhando 2 (erro, inclina p/ direita)", "chave girando 1 (de frente)", "chave girando 2 (de perfil)", "tampa abrindo 1 (35°)", "tampa abrindo 2 (75°)", "aberto com luz e itens", "aberto vazio", "emperrado 1", "emperrado 2"], "anims": [{"nome": "erro (chacoalhar)", "quadros": [1, 2, 1, 2, 0], "dur": [60, 60, 60, 60, 200], "loop": false}, {"nome": "abrir com chave", "quadros": [3, 4, 3, 4], "dur": [110, 115, 110, 115], "loop": false}, {"nome": "abrir", "quadros": [0, 5, 6, 7], "dur": [120, 90, 90, 700], "loop": false}, {"nome": "emperrado", "quadros": [9, 10], "dur": [320, 320], "loop": true}], "uso": "Igual ao baú de madeira: 128×128, pivô (64, 110), gy=110. Efeitos de abertura VAS-14..20 em tempo real; cor dos raios do jogo = maior raridade obtida.", "w": 1408, "h": 128}, {"id": "bau_lua", "nome": "Baú da Lua de Sangue", "categoria": "Baú", "mecanica": "Baús (BAU-01..07, BAU-10, BAU-11, BAU-15..19, BAU-24, BAU-25), BOSS-11, BF-13", "conceito": "Relicário de pedra-obsidiana que só aparece com a Lua de Sangue, ao derrotar bosses e mini bosses. O corpo é de pedra quase preta, polida e lascada, com veios roxos, emoldurada por filetes e cantoneiras de ouro com espirais. Na frente brilha uma fileira de runas vermelhas entalhadas, e a tampa chanfrada tem no topo uma lua de sangue em esmalte vermelho com crateras, cercada por um aro dourado. A fechadura é uma peça de ouro em forma de lua crescente com um rubi, e pés de garra dourados seguram o baú. Uma aura vermelha pulsa em volta, e é o único baú que só abre com chave de ouro ou com os puzzles difíceis (luzes, canos 4×4, fios 5).", "partes": [{"parte": "Corpo (frente)", "descricao": "72×28 px de pedra #2e2836/#3c3446 com veios #4a3e58 e lascas, moldura dourada de 2 px #f2c230/#b8861a, cantoneiras de ouro com espiral nas 4 quinas, 6 runas vermelhas #c8323a com pixel de brilho #ff5a5a."}, {"parte": "Tampa chanfrada", "descricao": "faixa frontal de 8 px com filete dourado e mini lua, chanfro de 7 px, topo de 16 px (9 px na tela) com lua de sangue Ø14×9 px #c8323a com crateras #8a1e26 e aro dourado. Aberta mostra forro de veludo vermelho escuro #5a1420."}, {"parte": "Fechadura de ouro", "descricao": "lua crescente de ouro 14×14 px #f2c230 com sombra #b8861a, rubi #c8323a no centro e buraco de chave."}, {"parte": "Pés de garra", "descricao": "4 garras douradas 7×4 px nas quinas."}, {"parte": "Aura", "descricao": "brilho vermelho #c8323a radial atrás do baú (camada por baixo do sprite), mais forte quando aberto."}, {"parte": "Interior aberto", "descricao": "luz vermelha e dourada, raios vermelho-dourados e itens (fragmento lunar, amuleto)."}, {"parte": "Emperrado", "descricao": "correntes em X, cadeado torto, fumaça e X vermelho."}], "paleta": [{"nome": "Pedra escura", "hex": "#2e2836"}, {"nome": "Pedra", "hex": "#3c3446"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Veio roxo", "hex": "#4a3e58"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro escuro", "hex": "#b8861a"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Runa brilho", "hex": "#ff5a5a"}, {"nome": "Veludo", "hex": "#5a1420"}], "arquivo": "sprites/bau_lua.png", "fw": 128, "fh": 128, "cols": 11, "quadros": ["fechado", "chacoalhando 1 (erro, inclina p/ esquerda)", "chacoalhando 2 (erro, inclina p/ direita)", "chave girando 1 (de frente)", "chave girando 2 (de perfil)", "tampa abrindo 1 (35°)", "tampa abrindo 2 (75°)", "aberto com luz e itens", "aberto vazio", "emperrado 1", "emperrado 2"], "anims": [{"nome": "erro (chacoalhar)", "quadros": [1, 2, 1, 2, 0], "dur": [60, 60, 60, 60, 200], "loop": false}, {"nome": "abrir com chave", "quadros": [3, 4, 3, 4], "dur": [110, 115, 110, 115], "loop": false}, {"nome": "abrir", "quadros": [0, 5, 6, 7], "dur": [120, 90, 90, 700], "loop": false}, {"nome": "emperrado", "quadros": [9, 10], "dur": [320, 320], "loop": true}], "uso": "128×128, pivô (64, 110), gy=110. A aura pode pulsar em tempo real (alpha). Usado também como baú de recompensa do boss (BF-13) junto com bau_respawn.", "w": 1408, "h": 128}, {"id": "bau_chaves", "nome": "Chaves de baú", "categoria": "Chave / HUD", "mecanica": "BAU-14..20", "conceito": "As três chaves que abrem baús sem puzzle e o chaveiro que serve de contador no HUD. A de bronze é simples, de anel redondo e dentes quadrados, gasta e com pátina verde; a de prata tem anel em trevo, haste com colarinho e dentes em escada; a de ouro é ornamentada, com anel em moldura de lua crescente, rubi, filigrana e dentes em forma de runa. Cada chave tem também um quadro 'girando' de perfil fino (o anel visto de lado), usado em sequência com o de frente para a chave girar na fechadura por 0,45 s (BAU-17). O chaveiro do HUD é uma argola de aço com as três chaves penduradas em leque.", "partes": [{"parte": "Chave de bronze", "descricao": "diagonal 45°, ~50 px: anel Ø18 px com furo Ø8, haste de 4 px, 2 dentes quadrados; #b87333 / brilho #e0a85a / pátina #5f8a6a."}, {"parte": "Chave de prata", "descricao": "anel em trevo (3 lóbulos Ø9) com furo, colarinho de 2 anéis, dentes em escada; #c9ced4 / brilho #f2f5f7 / sombra #7d848c."}, {"parte": "Chave de ouro", "descricao": "anel Ø20 com lua crescente vermelha dentro e rubi, pontinhas de filigrana, colarinho duplo, dentes em runa; #f2c230 / #b8861a / rubi #c8323a; brilhinhos."}, {"parte": "Girando", "descricao": "mesma chave achatada a 22% no eixo perpendicular à haste (anel vira um traço fino de ~4 px) + 2 arcos de giro brancos."}, {"parte": "Chaveiro do HUD", "descricao": "argola de aço Ø16 px no topo e as 3 chaves menores (escala 0,6) penduradas em leque (−35°, 0°, +35°)."}], "paleta": [{"nome": "Bronze", "hex": "#b87333"}, {"nome": "Bronze brilho", "hex": "#e0a85a"}, {"nome": "Pátina", "hex": "#5f8a6a"}, {"nome": "Prata", "hex": "#c9ced4"}, {"nome": "Prata sombra", "hex": "#7d848c"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro escuro", "hex": "#b8861a"}, {"nome": "Rubi", "hex": "#c8323a"}, {"nome": "Aço da argola", "hex": "#8d969c"}], "arquivo": "sprites/bau_chaves.png", "fw": 64, "fh": 64, "cols": 7, "quadros": ["chave de bronze", "chave de prata", "chave de ouro", "bronze girando (perfil)", "prata girando (perfil)", "ouro girando (perfil)", "chaveiro do HUD (3 chaves)"], "anims": [{"nome": "bronze girando", "quadros": [0, 3], "dur": [110, 110], "loop": true}, {"nome": "prata girando", "quadros": [1, 4], "dur": [110, 110], "loop": true}, {"nome": "ouro girando", "quadros": [2, 5], "dur": [110, 110], "loop": true}], "uso": "Ícones 64×64 da mochila e do contador de chaves no HUD (o número é desenhado pelo jogo ao lado). Os quadros de frente/perfil alternam para o efeito de chave girando sobre a fechadura (o baú já tem a chave desenhada nos quadros 3-4).", "w": 448, "h": 64}, {"id": "bau_gazua", "nome": "Gazua", "categoria": "Ferramenta / Puzzle", "mecanica": "BAU-08", "conceito": "Gazua improvisada de sobrevivente: uma haste de aço de grampo de cabelo lixada com a ponta em gancho, cabo enrolado em fita isolante vermelha e preta, e a chave de tensão em L presa por um elástico. É o ícone do puzzle de gazua da fechadura redonda. Quando o jogador erra, a gazua quebra: a ponta em gancho se solta e voa, a haste fica rachada e saltam lasquinhas de metal e uma faísca.", "partes": [{"parte": "Haste e gancho", "descricao": "haste de 2-3 px de aço #c9ced4 com sombra #6b747a, ~34 px na diagonal, ponta em gancho de 5 px."}, {"parte": "Cabo", "descricao": "cabo 18×7 px enrolado em fita vermelha #c8323a e preta #1e1a1c em espiral, ponta com argola."}, {"parte": "Chave de tensão", "descricao": "L de aço escuro #8d969c, 20 px + dobra de 6 px, paralela à gazua."}, {"parte": "Quebrada", "descricao": "haste partida no meio: ponta solta deslocada e girada 25°, borda rachada, 3 lascas e faísca #fff4d0."}], "paleta": [{"nome": "Aço", "hex": "#c9ced4"}, {"nome": "Aço sombra", "hex": "#6b747a"}, {"nome": "Fita vermelha", "hex": "#c8323a"}, {"nome": "Fita preta", "hex": "#1e1a1c"}, {"nome": "Faísca", "hex": "#fff4d0"}], "arquivo": "sprites/bau_gazua.png", "fw": 64, "fh": 64, "cols": 2, "quadros": ["gazua inteira", "gazua quebrada"], "uso": "Ícone 64×64 no painel do puzzle de gazua (contador de gazuas/pinos) e feedback de erro (troca para quebrada + tremor).", "w": 128, "h": 64}, {"id": "bau_puzzle", "nome": "Peças dos mini puzzles", "categoria": "UI de puzzle", "mecanica": "BAU-08, BAU-09, BAU-10, BAU-22, BAU-23, BAU-24, BAU-25", "conceito": "Conjunto de peças de interface dos seis mini puzzles de baú, todas desenhadas como objetos físicos de metal, pedra e papel gasto, no mesmo estilo dos sprites (contorno, luz de cima-esquerda, rebites e desgaste). A fechadura redonda da gazua é um disco de aço com aro rebitado, zona verde e o pino; o ponteiro vem separado para girar em volta do centro. Os símbolos de memória são lajotas de pedra com o símbolo entalhado que acendem coloridos; as casas das luzes são lâmpadas em grade; as cartas de pares têm verso de lua e frentes de papel; os canos são de cobre/aço vistos de cima e ficam azuis quando ligados; as pontas de fio são cabos com terminal; e os botões de número são teclas de metal com dígitos desenhados à mão.", "partes": [{"parte": "Fechadura redonda", "descricao": "disco Ø58 px: aro de aço #6b747a com 8 rebites, face escura #2a2e33 com marcas de grau, zona verde #4fb06a em cunha de 50° no topo-direita com borda clara #8fe09a, pino de latão no meio da zona, miolo com buraco de chave."}, {"parte": "Ponteiro", "descricao": "agulha vermelha #c8323a de 26 px apontando para cima a partir do centro (32,32), contrapeso redondo e eixo prata; resto transparente. Gira em tempo real em volta de (32,32)."}, {"parte": "Pino travado", "descricao": "pino cilíndrico de latão #d9a05a 10×22 px com mola por baixo e brilho verde de confirmado (✓)."}, {"parte": "Símbolos de memória ☾ ✶ ☠ ✚", "descricao": "lajota de pedra 54×54 px com borda chanfrada; apagado: símbolo entalhado cinza-escuro #4a4450; aceso: símbolo colorido com brilho (☾ vermelho #c8323a, ✶ amarelo #f2c230, ☠ osso #e8e2d0 com fundo roxo, ✚ verde #4fb06a)."}, {"parte": "Casa das luzes", "descricao": "moldura de metal 56×56 px com lâmpada redonda Ø30: apagada vidro escuro #2e3a3e com reflexo; acesa amarela #ffd36a com filamento e brilho."}, {"parte": "Cartas de pares", "descricao": "carta 40×54 px: verso vermelho-escuro com moldura dourada, losangos e lua; frentes de papel #e8dcc0 com canto gasto e símbolo (lua, caveira, chave)."}, {"parte": "Canos", "descricao": "chapa de piso 64×64 com rebites nos cantos; cano de aço #7d848c de 16 px com flanges nas bordas; reto (esq-dir), curva (dir-baixo), T (esq-dir-baixo), entrada ▶ (válvula na esquerda + seta) e saída ▶ (ralo na direita + seta). Vazio: miolo escuro #22262a; ligado: água azul #3fa8ff com brilho #bfe8ff."}, {"parte": "Pontas de fio", "descricao": "cabo de 8 px vindo da esquerda que termina num terminal de latão com cobre descascado, em 5 cores: vermelho #c8323a, azul #3a6fd0, amarelo #e8c030, verde #3f9a4a, branco #e8e4dc."}, {"parte": "Botões de número", "descricao": "tecla de metal 52×52 px com bisel, parafusos e dígito 1-6 desenhado à mão (traço de 4 px) em creme #f4efe6 com sombra."}], "paleta": [{"nome": "Aço", "hex": "#6b747a"}, {"nome": "Face escura", "hex": "#2a2e33"}, {"nome": "Zona verde", "hex": "#4fb06a"}, {"nome": "Latão", "hex": "#d9a05a"}, {"nome": "Ponteiro", "hex": "#c8323a"}, {"nome": "Pedra", "hex": "#5a5462"}, {"nome": "Lâmpada acesa", "hex": "#ffd36a"}, {"nome": "Papel", "hex": "#e8dcc0"}, {"nome": "Água", "hex": "#3fa8ff"}, {"nome": "Ouro", "hex": "#f2c230"}], "arquivo": "sprites/bau_puzzle.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["fechadura redonda (fundo, zona verde, pino)", "ponteiro (gira em 32,32)", "pino travado", "memória ☾ apagado", "memória ✶ apagado", "memória ☠ apagado", "memória ✚ apagado", "memória ☾ aceso", "memória ✶ aceso", "memória ☠ aceso", "memória ✚ aceso", "luz apagada", "luz acesa", "carta verso", "carta frente lua", "carta frente caveira", "carta frente chave", "cano reto vazio", "cano curva vazio", "cano T vazio", "entrada ▶ vazia", "saída ▶ vazia", "cano reto ligado", "cano curva ligado", "cano T ligado", "entrada ▶ ligada", "saída ▶ ligada", "fio vermelho", "fio azul", "fio amarelo", "fio verde", "fio branco", "botão 1", "botão 2", "botão 3", "botão 4", "botão 5", "botão 6"], "uso": "Peças 64×64 montadas pelo jogo no painel do puzzle. A zona verde muda de tamanho (50°→40°→30°) no jogo: o quadro mostra 50° como referência; o jogo pode desenhar a cunha por código e usar só o disco. Ponteiro e canos giram em tempo real (múltiplos de 90° nos canos; curva base = direita→baixo, T base = esquerda-direita-baixo).", "w": 512, "h": 320}, {"id": "bau_loot", "nome": "Itens exclusivos de baú", "categoria": "Item", "mecanica": "BAU-12 (tabela de loot dos baús)", "conceito": "Os itens que só saem de baú, em ícones grandes e detalhados de 64×64 para a mochila e para o pop do loot. Vão de ferramentas de sobrevivência gastas (lanterna, faca, machado, kit de ferramentas, mapa rabiscado da região) a equipamento militar (pistola, colete, kit médico grande, chave do gerador) e às relíquias da Lua de Sangue (fragmento lunar de cristal vermelho com veios dourados e o amuleto lunar). Todos têm contorno escuro, luz de cima-esquerda, sombra no chão e marcas de uso: ferrugem, fita, arranhões, sangue seco.", "partes": [{"parte": "Fragmento lunar", "descricao": "3 cristais vermelhos #c8323a facetados (claro #ff6a6a, escuro #7a1622) brotando de pedra escura, veios dourados #f2c230, brilho e faíscas."}, {"parte": "Amuleto lunar", "descricao": "corrente dourada em arco, medalhão Ø26 de ouro #f2c230 com lua crescente de rubi e pontinhas de filigrana, pingente de gota."}, {"parte": "Kit de ferramentas", "descricao": "caixa de metal vermelha #a8322a 44×24 com alça, travas e amassados; chave inglesa e chave de fenda saindo por cima."}, {"parte": "Mapa da região", "descricao": "papel #d8c89a dobrado em 3 painéis com sombreado de dobra, ruas, rio azul (Capibaribe), X vermelho, mancha de café e canto rasgado."}, {"parte": "Lanterna", "descricao": "lanterna tática preta/oliva 40×12 em diagonal, anel serrilhado, botão, lente amarela acesa com cone de luz."}, {"parte": "Colete", "descricao": "colete tático oliva #55643f com placas, 3 bolsos com velcro, alças e fivelas pretas, remendo."}, {"parte": "Chave do gerador", "descricao": "chave de ignição com cabeça plástica preta, haste dentada e etiqueta amarela #e8c030 com raio, argola."}, {"parte": "Faca", "descricao": "faca de combate diagonal, lâmina #c9ced4 com fio claro e serrilha, guarda, cabo de paracord, sangue seco na ponta."}, {"parte": "Machado", "descricao": "machado de incêndio: cabo de madeira #9a6a3c com fita, cabeça vermelha #b8322a, fio de aço e sangue."}, {"parte": "Pistola", "descricao": "pistola preta #2e3236 de lado, ferrolho serrilhado, guarda-mato, empunhadura texturizada, brilho na arma."}, {"parte": "Kit médico grande", "descricao": "bolsa médica 46×34 branca-suja #e8e4dc com cruz vermelha, zíper, alça, faixa verde e bolso lateral."}], "paleta": [{"nome": "Cristal", "hex": "#c8323a"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Vermelho ferramenta", "hex": "#a8322a"}, {"nome": "Papel", "hex": "#d8c89a"}, {"nome": "Oliva", "hex": "#55643f"}, {"nome": "Aço", "hex": "#c9ced4"}, {"nome": "Madeira", "hex": "#9a6a3c"}, {"nome": "Preto arma", "hex": "#2e3236"}, {"nome": "Branco sujo", "hex": "#e8e4dc"}], "arquivo": "sprites/bau_loot.png", "fw": 64, "fh": 64, "cols": 6, "quadros": ["Fragmento lunar", "Amuleto lunar", "Kit de ferramentas", "Mapa da região", "Lanterna", "Colete", "Chave do gerador", "Faca", "Machado", "Pistola", "Kit médico grande"], "uso": "Ícone 64×64 de mochila e do item que salta do baú (VAS-07; o jogo pode reduzir a 50%). Brilho de raridade é aplicado pelo jogo por baixo.", "w": 384, "h": 128}, {"id": "bau_respawn", "nome": "Feixe dourado de respawn do baú", "categoria": "FX", "mecanica": "LUA-06, BF-13, BOSS-11", "conceito": "Quando a Lua de Sangue renasce o mundo, ou quando um boss cai, um feixe de luz dourada desce do céu, um baú despenca dentro dele, bate no chão levantando poeira e solta um brilho antes do feixe sumir. O feixe é uma coluna de luz em degraus (miolo branco-dourado, borda dourada translúcida) com partículas subindo e um disco de luz no chão. A sombra no chão cresce à medida que o baú se aproxima. São 6 quadros, uma linha para cada baú (madeira, ferro, Lua de Sangue).", "partes": [{"parte": "Feixe", "descricao": "coluna do topo até o chão (gy=180): fino 6 px no quadro 1, largo 34 px no 2-3 com miolo #fff6c8 e borda #f2c230 translúcida, faixas horizontais de energia e faíscas."}, {"parte": "Disco no chão", "descricao": "elipse dourada 40×8 px em volta do ponto de queda."}, {"parte": "Baú caindo", "descricao": "baú fechado (madeira/ferro/lua) no ar a ~70 px acima do chão no quadro 3, com sombra pequena; no chão nos quadros 4-6."}, {"parte": "Impacto", "descricao": "nuvens de poeira #9c8a70 dos dois lados, pedrinhas e anel de choque claro."}, {"parte": "Brilho", "descricao": "clarão radial dourado + estrelinhas sobre o baú (quadro 5)."}, {"parte": "Feixe sumindo", "descricao": "feixe fino e fraco, faíscas subindo (quadro 6)."}], "paleta": [{"nome": "Miolo do feixe", "hex": "#fff6c8"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Poeira", "hex": "#9c8a70"}, {"nome": "Anel de choque", "hex": "#fff4d0"}], "arquivo": "sprites/bau_respawn.png", "fw": 128, "fh": 192, "cols": 6, "quadros": ["madeira: feixe fino", "madeira: feixe largo", "madeira: baú no ar com sombra", "madeira: impacto com poeira", "madeira: brilho", "madeira: feixe sumindo", "ferro: feixe fino", "ferro: feixe largo", "ferro: baú no ar com sombra", "ferro: impacto com poeira", "ferro: brilho", "ferro: feixe sumindo", "lua: feixe fino", "lua: feixe largo", "lua: baú no ar com sombra", "lua: impacto com poeira", "lua: brilho", "lua: feixe sumindo"], "anims": [{"nome": "respawn madeira", "quadros": [0, 1, 2, 3, 4, 5], "dur": [120, 160, 140, 140, 220, 260], "loop": false}, {"nome": "respawn ferro", "quadros": [6, 7, 8, 9, 10, 11], "dur": [120, 160, 140, 140, 220, 260], "loop": false}, {"nome": "respawn lua", "quadros": [12, 13, 14, 15, 16, 17], "dur": [120, 160, 140, 140, 220, 260], "loop": false}], "uso": "FX 128×192 ancorado no ponto do baú: pivô (64, 180), o chão do quadro é y=180 (o baú no chão fica com a base em 180, igual ao sprite 128×128 com gy=110 deslocado 70 px). Depois do quadro 6 o jogo troca para o sprite fechado do baú. A queda pode ser interpolada em tempo real entre os quadros 3 e 4.", "w": 768, "h": 576}]}, {"grupo": "armas_distancia", "titulo": "Armas de fogo e arco", "ordem": 5, "resumo": "Armas à distância do herói (pistola, escopeta, fuzil e arco improvisado) com todos os efeitos de game feel das abas Tiro (TIR-01..10) e Arco (ARC-01..13): clarão, fumaça, traçante, cápsulas, munição no HUD, flechas, aljava, alvos de treino e miras.", "itens": [{"id": "arm_pistola", "nome": "Pistola", "categoria": "Arma de fogo", "mecanica": "Tiro (TIR-01, TIR-04, TIR-05, TIR-08)", "conceito": "Pistola semiautomática genérica achada numa delegacia saqueada do Recife Antigo, sem nenhuma marca real. O ferrolho de aço oxidado está cheio de arranhões claros e o punho de polímero marrom foi enrolado com fita isolante preta para não escorregar com o suor (e o sangue). Tem miras de ferro simples, serrilhado traseiro gasto, pontos de ferrugem perto da janela de ejeção e um parafuso faltando. Desenhada de perfil apontando para a direita, grande no quadro para o jogo girar o sprite em direção à mira. É a arma de fogo inicial: precisa, barulhenta (TIR-09, raio 6 tiles) e com pente de 12.", "partes": [{"parte": "Ferrolho", "descricao": "bloco de 74×12 px (x 22..96, y 14..26) aço escuro #3a3c44 com filete de luz #7a7e8a no topo, 6 serrilhas verticais atrás, janela de ejeção recortada (12×3 px), arranhões #8a8e98 e 3 pontos de ferrugem #8a4e2e; no quadro de recuo desliza 5 px para trás"}, {"parte": "Cano", "descricao": "ponta de 4×5 px #24262c saindo à frente do ferrolho, boca escura #101014 (é onde nasce o clarão)"}, {"parte": "Armação e guarda-mato", "descricao": "armação #2e3038 de 60×6 px sob o ferrolho, trilho com 3 ranhuras, guarda-mato vazado (anel 14×10 px) e gatilho #8a8e98"}, {"parte": "Punho", "descricao": "trapézio inclinado para trás 20×30 px marrom #4a3a30 com textura pontilhada, 3 voltas de fita isolante #1c1c22 com brilho #4a4a56 e uma ponta solta, parafuso #c9c3b0, base do pente #24262c"}, {"parte": "Miras e cão", "descricao": "massa de mira na frente e alça atrás (2-3 px), cão externo pequeno na traseira"}], "paleta": [{"nome": "Aço do ferrolho", "hex": "#3a3c44"}, {"nome": "Armação", "hex": "#2e3038"}, {"nome": "Arranhão", "hex": "#8a8e98"}, {"nome": "Punho", "hex": "#4a3a30"}, {"nome": "Fita isolante", "hex": "#1c1c22"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Clarão núcleo", "hex": "#ffffff"}, {"nome": "Clarão coroa", "hex": "#ff9a2a"}], "arquivo": "sprites/arm_pistola.png", "fw": 128, "fh": 64, "cols": 4, "quadros": ["normal", "recuo (para trás e cano para cima)", "disparo (clarão na boca)", "no chão (loot 3/4 com sombra)"], "anims": [{"nome": "tiro", "quadros": [2, 1, 0], "dur": [50, 60, 120], "loop": true}], "uso": "Pivô/empunhadura no centro do punho: (38, 40) no quadro de 128×64; a boca do cano fica em (101, 20) — é onde o jogo coloca arm_muzzle e nasce o traçante; a janela de ejeção (64, 15) solta a cápsula dourada. O jogo gira o sprite pelo pivô para a mira (espelha em Y quando mira para a esquerda). O recuo de TIR-04 é transformação em tempo real (o quadro 'recuo' é só a pose de pico); o quadro 'no chão' é o loot com base em y 54.", "w": 512, "h": 64}, {"id": "arm_escopeta", "nome": "Escopeta de repetição", "categoria": "Arma de fogo", "mecanica": "Tiro (TIR-01, TIR-03, TIR-04, TIR-05, TIR-09)", "conceito": "Escopeta de bombeamento de cano longo, tirada de uma fazenda do interior e trazida para a cidade num carro de feira. A coronha e a telha (fore-end) de madeira estão rachadas e lascadas, a coronha foi remendada com fita prata e a telha tem fita isolante enrolada onde a madeira partiu. O cano e o tubo de cartuchos são de aço mais claro, com riscos e ferrugem nas pontas, e uma massa de mira de latão na boca. É a arma mais pesada e barulhenta (raio 10 tiles): 6 cartuchos, 6 balins por tiro, recuo forte de 8 px.", "partes": [{"parte": "Coronha", "descricao": "madeira #8a5a30 de 34 px de comprido com veios #6a4220, rachadura escura, sola de borracha preta #1e1a18 com ranhuras, 2 voltas de fita prata #a8a8a4 com rugas"}, {"parte": "Caixa da culatra", "descricao": "aço #3a3c44 24×12 px com janela de ejeção, 2 pinos claros e arranhões; guarda-mato vazado e gatilho embaixo"}, {"parte": "Cano e tubo", "descricao": "cano #5a5e68 de 53×5 px com filete de luz #a8aeb8, tubo de cartuchos #44474f por baixo, braçadeira, massa de mira de latão #e8c060, ferrugem na boca"}, {"parte": "Telha (pump)", "descricao": "madeira 24×8 px com 4 ranhuras de pegada e fita isolante #1c1c22; no recuo ela está puxada 5 px para trás"}], "paleta": [{"nome": "Madeira", "hex": "#8a5a30"}, {"nome": "Veio escuro", "hex": "#6a4220"}, {"nome": "Cano", "hex": "#5a5e68"}, {"nome": "Tubo", "hex": "#44474f"}, {"nome": "Fita prata", "hex": "#a8a8a4"}, {"nome": "Fita isolante", "hex": "#1c1c22"}, {"nome": "Latão", "hex": "#e8c060"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}], "arquivo": "sprites/arm_escopeta.png", "fw": 128, "fh": 64, "cols": 4, "quadros": ["normal", "recuo (para trás, cano sobe, telha puxada)", "disparo (clarão 1,6× na boca)", "no chão (loot 3/4 com sombra)"], "anims": [{"nome": "tiro", "quadros": [2, 1, 0], "dur": [50, 120, 200], "loop": true}], "uso": "Pivô/empunhadura no punho atrás do gatilho: (40, 38); apoio da mão esquerda na telha (84, 34). Boca do cano em (115, 22) (clarão de escopeta de arm_muzzle e os balins de arm_projeteis); janela de ejeção (50, 25) solta a cápsula vermelha. Jogo gira pelo pivô e espelha em Y para a esquerda. Recuo e retorno são tweens em tempo real.", "w": 512, "h": 64}, {"id": "arm_fuzil", "nome": "Fuzil", "categoria": "Arma de fogo", "mecanica": "Tiro (TIR-01, TIR-02, TIR-04 mira sobe, TIR-05, TIR-08)", "conceito": "Fuzil automático velho de coronha de madeira, sem marca, achado num quartel abandonado e mantido vivo com gambiarras: luneta presa com fita isolante, carregador curvo de aço riscado e uma alça de corda no lugar da bandoleira. A madeira é escura e lascada, o metal tem desgaste brilhante nas arestas e ferrugem nas soldas. O quebra-chamas tem fendas que deixam o clarão em estrela. É a arma de cadência alta (30 balas, 0,09 s), barulhenta (raio 8) e cuja mira sobe a cada tiro.", "partes": [{"parte": "Coronha", "descricao": "madeira escura #7a4a24 com veios #5a3418, chapa de soleira #1e1a18 e entalhe de corda"}, {"parte": "Caixa e luneta", "descricao": "caixa #34363e com ferrolho (alavanca #8a8e98), luneta #22242a de 26 px presa com 2 voltas de fita isolante, lente azul #5ab0e8 brilhando"}, {"parte": "Carregador curvo", "descricao": "banana de aço #3a3c44 de 10×16 px com nervuras e arranhões, encaixado na frente do gatilho"}, {"parte": "Guarda-mão e cano", "descricao": "guarda-mão de madeira #7a4a24 com 3 furos de ventilação, cano #4a4e58 com filete claro, massa de mira e quebra-chamas com fendas"}], "paleta": [{"nome": "Madeira escura", "hex": "#7a4a24"}, {"nome": "Veio", "hex": "#5a3418"}, {"nome": "Caixa", "hex": "#34363e"}, {"nome": "Cano", "hex": "#4a4e58"}, {"nome": "Luneta", "hex": "#22242a"}, {"nome": "Lente", "hex": "#5ab0e8"}, {"nome": "Fita isolante", "hex": "#1c1c22"}, {"nome": "Corda", "hex": "#b59a62"}], "arquivo": "sprites/arm_fuzil.png", "fw": 128, "fh": 64, "cols": 4, "quadros": ["normal", "recuo (cano sobe 2-4 px)", "disparo (clarão em estrela)", "no chão (loot 3/4 com sombra)"], "anims": [{"nome": "rajada", "quadros": [2, 1, 2, 1, 0], "dur": [45, 45, 45, 45, 120], "loop": true}], "uso": "Pivô/empunhadura no punho: (45, 38); boca do quebra-chamas em (111, 27); janela de ejeção (54, 25). Gira pelo pivô; a subida da mira de TIR-04 é offset em tempo real somado ao recuo.", "w": 512, "h": 64}, {"id": "arm_muzzle", "nome": "Clarão e fumaça do disparo", "categoria": "Efeito", "mecanica": "Tiro (TIR-01 The shot)", "conceito": "Efeito do disparo que aparece por 50 ms na boca do cano, desenhado para ser composto em modo aditivo. Tem núcleo branco quente, uma coroa laranja-amarela com pontas em estrela e um brilho em volta. A versão da escopeta é 1,6× maior e mais larga, com mais pontas. Depois do clarão, 3 fiapos de fumaça cinza-lilás saem da boca e sobem, crescem e somem em ~0,8 s.", "partes": [{"parte": "Núcleo", "descricao": "elipse branca #ffffff 6×4 px (pistola) / 10×6 (escopeta) colada à boca, no lado esquerdo do quadro"}, {"parte": "Coroa", "descricao": "losango amarelo #ffd24a com miolo #fff6c0 e contorno laranja #e0601a, 2-4 espinhos laterais; comprimento 26 px pistola / 42 px escopeta"}, {"parte": "Brilho", "descricao": "halo radial laranja #ff9a2a em degraus, raio 14/22 px"}, {"parte": "Fumaça", "descricao": "3 fiapos (bolinhas) #c8c2d0 com contorno #5a5468, subindo de y 40 para y 10, crescendo de 3 para 7 px e ficando transparentes"}], "paleta": [{"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Miolo", "hex": "#fff6c0"}, {"nome": "Coroa", "hex": "#ffd24a"}, {"nome": "Borda laranja", "hex": "#e0601a"}, {"nome": "Brilho", "hex": "#ff9a2a"}, {"nome": "Fumaça", "hex": "#c8c2d0"}], "arquivo": "sprites/arm_muzzle.png", "fw": 64, "fh": 64, "cols": 9, "quadros": ["pistola 1 (acende)", "pistola 2 (cheio)", "pistola 3 (some)", "escopeta 1", "escopeta 2", "escopeta 3", "fumaça 1", "fumaça 2", "fumaça 3"], "anims": [{"nome": "pistola", "quadros": [0, 1, 2], "dur": [16, 20, 16], "loop": true}, {"nome": "escopeta", "quadros": [3, 4, 5], "dur": [16, 24, 20], "loop": true}, {"nome": "fumaça", "quadros": [6, 7, 8], "dur": [260, 260, 280], "loop": true}], "uso": "Âncora do clarão: (6, 32) — encostar na boca do cano e girar junto com a arma, desenhar com blend aditivo. A fumaça tem âncora (20, 44) e NÃO gira (sobe sempre para cima na tela), com alpha extra decrescente em tempo real.", "w": 576, "h": 64}, {"id": "arm_projeteis", "nome": "Traçante, balins e buraco de bala", "categoria": "Efeito", "mecanica": "Tiro (TIR-02 Bullet, TIR-03 The hit)", "conceito": "O projétil nunca é um ponto: é um traço esticado na direção do voo, com núcleo amarelo-claro quase branco e um halo laranja que afina para trás. Há 3 comprimentos (10, 18 e 26 px) para o jogo escolher conforme a velocidade. Os balins da escopeta são 6 traços curtos espalhados em leque. Quando o tiro pega numa parede fica um buraco escuro com bordas lascadas, rachaduras e uma nuvenzinha de pó de reboco (2 quadros).", "partes": [{"parte": "Traçante", "descricao": "núcleo #fffbe0 de 2 px de altura com ponta branca à direita, halo #ffb040 de 4 px atrás afinando e ficando transparente"}, {"parte": "Balins", "descricao": "6 traços de 5-8 px com cabeça #fff0c0 e cauda laranja, espalhados ±10 px"}, {"parte": "Buraco", "descricao": "furo #120c10 de 5 px, anel de reboco lascado #b8b0a0/#8e8a84, 5 rachaduras pretas de 4-9 px"}, {"parte": "Pó", "descricao": "nuvens #9c8a70 com contorno #3a3024 grandes no quadro 1, menores e mais baixas no quadro 2, e 4 lasquinhas"}], "paleta": [{"nome": "Núcleo", "hex": "#fffbe0"}, {"nome": "Halo", "hex": "#ffb040"}, {"nome": "Furo", "hex": "#120c10"}, {"nome": "Reboco", "hex": "#b8b0a0"}, {"nome": "Pó", "hex": "#9c8a70"}], "arquivo": "sprites/arm_projeteis.png", "fw": 64, "fh": 32, "cols": 6, "quadros": ["traçante curto (10 px)", "traçante médio (18 px)", "traçante longo (26 px)", "balins da escopeta", "buraco na parede + pó 1", "buraco na parede + pó 2"], "anims": [{"nome": "buraco", "quadros": [4, 5], "dur": [120, 400], "loop": false}], "uso": "Traçante e balins: âncora na ponta (cabeça) em (44, 16), apontando para +x; o jogo gira pelo vetor velocidade e escolhe o comprimento pela velocidade (aditivo). Buraco: decal na parede com âncora no furo (32, 16); fica 20 s e some com fade.", "w": 384, "h": 32}, {"id": "arm_capsulas", "nome": "Cápsulas ejetadas", "categoria": "Efeito", "mecanica": "Tiro (TIR-05 Particles + shell)", "conceito": "Cápsulas que saltam da janela de ejeção girando, quicam 3 vezes com um 'tlim' e ficam no chão. A cápsula de pistola/fuzil é de latão dourado com fundo mais escuro e um brilho; a da escopeta é maior, de plástico vermelho com a base de metal dourado. Cada uma tem 4 quadros de giro (0°, 45°, 90°, 135°) e um quadro deitada no chão com sombrinha roxa.", "partes": [{"parte": "Cápsula dourada", "descricao": "cilindro de latão #e3b23c 12×5 px, base #b8861a com aro, boca aberta escura, brilho #fff0b0"}, {"parte": "Cartucho vermelho", "descricao": "tubo #c0262d 11×7 px com nervuras #8a1a20, base de latão #e3b23c 4 px com aro, boca dobrada"}, {"parte": "Sombra", "descricao": "elipse roxa translúcida 12×3 px embaixo, só nos quadros de chão"}], "paleta": [{"nome": "Latão", "hex": "#e3b23c"}, {"nome": "Latão escuro", "hex": "#b8861a"}, {"nome": "Brilho", "hex": "#fff0b0"}, {"nome": "Plástico vermelho", "hex": "#c0262d"}, {"nome": "Nervura", "hex": "#8a1a20"}], "arquivo": "sprites/arm_capsulas.png", "fw": 32, "fh": 32, "cols": 10, "quadros": ["dourada 0°", "dourada 45°", "dourada 90°", "dourada 135°", "vermelha 0°", "vermelha 45°", "vermelha 90°", "vermelha 135°", "dourada no chão", "vermelha no chão"], "anims": [{"nome": "gira dourada", "quadros": [0, 1, 2, 3], "dur": [40, 40, 40, 40], "loop": true}, {"nome": "gira vermelha", "quadros": [4, 5, 6, 7], "dur": [50, 50, 50, 50], "loop": true}], "uso": "Âncora no centro (16, 16). O jogo move a cápsula com altura z separada e sombra (máx. 80 no chão, as mais antigas somem). No chão usa os quadros 8/9 com âncora no ponto de apoio (16, 18).", "w": 320, "h": 32}, {"id": "arm_municao", "nome": "Munição (HUD)", "categoria": "Ícone HUD", "mecanica": "Tiro (TIR-08 Munição)", "conceito": "Ícones do contador de munição no HUD, um por tipo de arma, para combinar com o número de balas ao lado. O pente da pistola é uma caixinha preta inclinada com as balas douradas aparecendo no topo; os cartuchos de escopeta são três tubos vermelhos em leque; o carregador do fuzil é um 'banana' curvo e riscado. O pente vazio é cinza e apagado (sem balas), para mostrar que precisa recarregar. A barra de recarga é um anel circular que enche em 4 quadros.", "partes": [{"parte": "Pente de pistola", "descricao": "caixa #2e3038 18×34 px inclinada 12°, janela de inspeção com furos, base #4a4e58, 2 balas douradas #e3b23c com ponta cobre #c27a3a no topo"}, {"parte": "Cartuchos", "descricao": "3 cartuchos #c0262d 10×26 px em leque com base de latão, nervuras e brilho"}, {"parte": "Carregador de fuzil", "descricao": "banana curva #3a3c44 de 20×40 px com 4 nervuras, arranhões e bala no topo"}, {"parte": "Pente vazio", "descricao": "o mesmo pente de pistola dessaturado #6b6a66, sem balas, com mola visível"}, {"parte": "Anel de recarga", "descricao": "trilho #2a2230 de raio 20 e 6 px de espessura, preenchimento creme #f4efe6 com borda #b9b0a0 nas frações 25/50/75/100%, ícone de bala no centro"}], "paleta": [{"nome": "Aço", "hex": "#2e3038"}, {"nome": "Latão", "hex": "#e3b23c"}, {"nome": "Cobre", "hex": "#c27a3a"}, {"nome": "Cartucho", "hex": "#c0262d"}, {"nome": "Vazio", "hex": "#6b6a66"}, {"nome": "Anel", "hex": "#f4efe6"}], "arquivo": "sprites/arm_municao.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["pente de pistola", "cartuchos de escopeta", "carregador de fuzil", "pente vazio", "recarga 25%", "recarga 50%", "recarga 75%", "recarga 100%"], "anims": [{"nome": "recarga", "quadros": [4, 5, 6, 7], "dur": [250, 250, 250, 250], "loop": true}], "uso": "Ícones HUD com âncora no centro (32, 32). Na recarga o jogo escolhe o quadro pela fração do tempo (ou desenha o arco ao vivo com estas cores); no fim, pisca 1 vez e volta ao ícone da arma.", "w": 512, "h": 64}, {"id": "arm_arco", "nome": "Arco improvisado", "categoria": "Arma à distância", "mecanica": "Arco (ARC-01 Draw it back, ARC-02, ARC-04, ARC-05)", "conceito": "Arco recurvo feito à mão no abrigo: lâminas de madeira coladas (claras e escuras, dá para ver o laminado), unidas com fita isolante e fita prata, pontas reforçadas com cordinha e corda trançada de náilon creme. A empunhadura é de couro marrom enrolado e costurado, com um apoio de flecha de borracha. Fica de pé, de perfil, com a corda à esquerda e o dorso para a direita. Puxar enverga as lâminas e recua a corda até 11 px com a flecha encaixada; com carga cheia a ponta da flecha brilha dourada; se segurar demais o arco treme com uma aura vermelha fraca; ao soltar, a corda vibra.", "partes": [{"parte": "Lâminas", "descricao": "2 braços de 50 px cada, 7 px de largura na base afinando para 3 px na ponta, madeira #a8743e com faixa clara #d0a060 e faixa escura #6a4220 (laminado), pontas recurvas para a frente"}, {"parte": "Fitas", "descricao": "2 faixas de fita isolante #1c1c22 e 1 de fita prata #a8a8a4 em cada braço, com bordinha clara"}, {"parte": "Empunhadura", "descricao": "couro #6b3f22 14×18 px enrolado com linhas diagonais #4a2a16 e costura creme, apoio de flecha #2a2228"}, {"parte": "Corda", "descricao": "linha 1 px #efe6cc com sombra #8a7a62, laços nas pontas, servimento central #c8323a; recua 0, 4, 7 e 11 px"}, {"parte": "Flecha encaixada", "descricao": "haste #b08850 da corda até 8 px além do arco, penas vermelha/creme na corda, ponta de aço #8a8e98 (dourada #f2c230 com brilho no perfeito)"}, {"parte": "Auras", "descricao": "perfeito: brilho dourado na ponta + faíscas; cansaço: halo vermelho #c8323a fraco em volta do arco e tremor de 1 px"}], "paleta": [{"nome": "Madeira", "hex": "#a8743e"}, {"nome": "Laminado claro", "hex": "#d0a060"}, {"nome": "Laminado escuro", "hex": "#6a4220"}, {"nome": "Couro", "hex": "#6b3f22"}, {"nome": "Corda", "hex": "#efe6cc"}, {"nome": "Fita isolante", "hex": "#1c1c22"}, {"nome": "Fita prata", "hex": "#a8a8a4"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}], "arquivo": "sprites/arm_arco.png", "fw": 128, "fh": 128, "cols": 9, "quadros": ["repouso", "puxado 33%", "puxado 66%", "puxado 100%", "carga cheia (ponta dourada)", "cansaço A (aura vermelha)", "cansaço B (tremor)", "corda vibrando A", "corda vibrando B"], "anims": [{"nome": "puxar", "quadros": [0, 1, 2, 3, 4], "dur": [120, 180, 220, 280, 350], "loop": false}, {"nome": "cansaço", "quadros": [5, 6], "dur": [60, 60], "loop": true}, {"nome": "soltar", "quadros": [7, 8, 7, 8, 0], "dur": [50, 60, 70, 80, 200], "loop": false}], "uso": "Pivô/empunhadura no centro do couro: (74, 64). A flecha sai para +x pelo apoio (76, 62). O jogo gira o sprite inteiro para a mira e escolhe o quadro pela carga (0-32% → 0, ...). O recuo de 4 px do ARC-05 e o tremor maior são transformações em tempo real; o anel de carga é arm_mira.", "w": 1152, "h": 128}, {"id": "arm_flecha", "nome": "Flecha", "categoria": "Projétil", "mecanica": "Arco (ARC-06 Arc + trail, ARC-08 Thunk, ARC-09 Let it quiver, ARC-10)", "conceito": "Flecha caseira de haste de madeira clara, ponta de aço afiada recortada de chapa, penas vermelho-lua e creme amarradas com linha. Voando, é desenhada horizontal apontando para a direita e o jogo gira conforme a velocidade. No tiro perfeito ganha um rastro dourado e a ponta brilha. Cravada no chão fica inclinada com um montinho de terra e vibra em 3 quadros; cravada em madeira entra num pedaço de tábua com lascas; quebrada vira dois pedaços que somem.", "partes": [{"parte": "Haste", "descricao": "48 px × 2 px #b08850 com luz #d4b07a em cima e 2 amarrações escuras"}, {"parte": "Ponta", "descricao": "triângulo de aço 8×6 px #8a8e98 com fio claro #d8dce4"}, {"parte": "Penas", "descricao": "2 penas 10×4 px vermelha #c8323a e creme #efe6cc, nock #2a2228 na ponta de trás"}, {"parte": "Rastro dourado", "descricao": "faixa #f2c230 → transparente de 20 px atrás + brilho #fff6c8 na ponta"}, {"parte": "Terra / madeira", "descricao": "montinho #6a5238 com pedrinhas; pedaço de tábua #9a6a3c com lascas claras e furo escuro"}], "paleta": [{"nome": "Haste", "hex": "#b08850"}, {"nome": "Aço", "hex": "#8a8e98"}, {"nome": "Pena vermelha", "hex": "#c8323a"}, {"nome": "Pena creme", "hex": "#efe6cc"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Terra", "hex": "#6a5238"}], "arquivo": "sprites/arm_flecha.png", "fw": 64, "fh": 32, "cols": 7, "quadros": ["voando", "voando com rastro dourado (perfeito)", "cravada no chão (vibra 1)", "cravada no chão (vibra 2)", "cravada no chão (vibra 3)", "cravada em madeira", "quebrada"], "anims": [{"nome": "let it quiver", "quadros": [2, 3, 4, 3, 2, 3, 2], "dur": [40, 40, 50, 60, 70, 90, 300], "loop": false}], "uso": "Voando: âncora no centro de massa (38, 16), aponta +x, gira pela velocidade, sombra no chão desenhada pelo jogo (ARC-06). Cravada: âncora no ponto de entrada no chão (42, 26); a vibração extra de ±0,18-0,43 rad é rotação ao vivo em volta desse ponto. Fica 40 s e volta para a aljava quando o herói passa por cima.", "w": 448, "h": 32}, {"id": "arm_aljava", "nome": "Aljava", "categoria": "Item / HUD", "mecanica": "Arco (ARC-10 Aljava)", "conceito": "Aljava feita de um cano de PVC encapado com couro costurado, alça de cinto de segurança e fivela de metal. Dela saem as penas vermelhas e creme das flechas. O primeiro quadro é o item do mundo/inventário; os outros são o contador do HUD com 10, 5 e 1 flecha (a quantidade de penas aparecendo diminui) e o número desenhado em pixel ao lado. Vazia, a aljava fica apagada com um '0' vermelho.", "partes": [{"parte": "Tubo", "descricao": "couro #8a5530 de 16×40 px inclinado 20°, costura creme pontilhada, boca com aro #6b3f22 e fundo de borracha"}, {"parte": "Alça e fivela", "descricao": "fita de cinto cinza-azulada #4a5866 com fivela #c9c3b0 e rebites"}, {"parte": "Flechas", "descricao": "hastes #b08850 e penas vermelha/creme saindo da boca: 5 no item, 5/3/1/0 no contador"}, {"parte": "Número", "descricao": "dígitos 3×5 ampliados 2× creme #fff4e0 com contorno escuro (vermelho #c8323a no 0)"}], "paleta": [{"nome": "Couro", "hex": "#8a5530"}, {"nome": "Couro escuro", "hex": "#6b3f22"}, {"nome": "Alça", "hex": "#4a5866"}, {"nome": "Fivela", "hex": "#c9c3b0"}, {"nome": "Pena", "hex": "#c8323a"}, {"nome": "Número", "hex": "#fff4e0"}], "arquivo": "sprites/arm_aljava.png", "fw": 64, "fh": 64, "cols": 5, "quadros": ["aljava (item)", "HUD 10 flechas", "HUD 5 flechas", "HUD 1 flecha", "HUD 0 (aljava vazia)"], "uso": "Âncora no centro (32, 32). O HUD escolhe o quadro pela faixa de flechas (10 → quadro 1, 5-9 → 2, 1-4 → 3, 0 → 4); o número exato pode ser redesenhado ao vivo por cima. Vazio: o botão dá clique seco e aparece o texto 'aljava vazia' do jogo.", "w": 320, "h": 64}, {"id": "arm_alvo", "nome": "Alvo de treino", "categoria": "Objeto de mapa", "mecanica": "Arco (ARC-07, ARC-08 'NA MOSCA!', ARC-09)", "conceito": "Alvo de treino montado no pátio do abrigo: um disco de tábuas pregadas e pintadas à mão com círculos vermelho, branco e preto, preso num cavalete de três pernas de caibro amarrado com corda. A tinta está descascada, há furos de flechas antigas e respingos, e uma tábua está rachada. Acertar o centro mostra 'NA MOSCA!' e o alvo balança junto com a flecha.", "partes": [{"parte": "Disco", "descricao": "elipse 68×72 px de tábuas verticais #9a6a3c com juntas escuras, anéis pintados vermelho #c8323a, branco #e8e0d0, preto #2a2228 e miolo vermelho, tinta descascada e 6 furos"}, {"parte": "Cavalete", "descricao": "3 pernas de caibro #7d5430 de 5 px, travessa, amarração de corda #b59a62, pregos #c9c3b0"}, {"parte": "Flecha na mosca", "descricao": "flecha cravada no miolo saindo para a esquerda-cima, penas vermelha/creme"}], "paleta": [{"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Caibro", "hex": "#7d5430"}, {"nome": "Vermelho", "hex": "#c8323a"}, {"nome": "Branco", "hex": "#e8e0d0"}, {"nome": "Preto", "hex": "#2a2228"}, {"nome": "Corda", "hex": "#b59a62"}], "arquivo": "sprites/arm_alvo.png", "fw": 128, "fh": 128, "cols": 4, "quadros": ["alvo", "flecha na mosca", "balançando A", "balançando B"], "anims": [{"nome": "balança", "quadros": [2, 3, 2, 3, 1], "dur": [70, 80, 90, 110, 200], "loop": false}], "uso": "Base apoiada em gy = 116, âncora (64, 116); centro do alvo (64, 50) é o hitbox 'na mosca' (raio 5); altura do alvo para ARC-07: 30-80 px. Balanço é quadro + rotação viva pequena.", "w": 512, "h": 128}, {"id": "arm_toco", "nome": "Toco de árvore", "categoria": "Objeto de mapa", "mecanica": "Arco (ARC-07, ARC-09, ARC-10 recolher flechas)", "conceito": "Toco de uma mangueira cortada para lenha ao lado do abrigo, usado como alvo improvisado. A casca é grossa, rachada e escura, com raízes saindo no chão, musgo e marcas de machado. O topo mostra os anéis do tronco em vista 3/4, com uma rachadura radial. Na versão com flechas, três flechas estão cravadas em ângulos diferentes, prontas para serem recolhidas.", "partes": [{"parte": "Tronco", "descricao": "cilindro 64×44 px casca #5a3a22 com sulcos verticais #3e2616, musgo #4a6139"}, {"parte": "Topo", "descricao": "elipse 64×20 px #c49a62 com 5 anéis #a07444, rachadura e miolo escuro, marca de machado"}, {"parte": "Raízes", "descricao": "4 raízes de 10-18 px entrando no chão, terra #6a5238"}, {"parte": "Flechas", "descricao": "3 flechas cravadas (topo e lateral) com penas vermelha/creme"}], "paleta": [{"nome": "Casca", "hex": "#5a3a22"}, {"nome": "Sulco", "hex": "#3e2616"}, {"nome": "Topo", "hex": "#c49a62"}, {"nome": "Anel", "hex": "#a07444"}, {"nome": "Musgo", "hex": "#4a6139"}], "arquivo": "sprites/arm_toco.png", "fw": 128, "fh": 128, "cols": 2, "quadros": ["toco sem flechas", "toco com flechas cravadas"], "uso": "Base em gy = 116, âncora (64, 116), altura do toco ~42 px (ARC-07). As flechas cravadas reais são instâncias de arm_flecha; o quadro 2 é para cenário/decoração.", "w": 256, "h": 128}, {"id": "arm_mira", "nome": "Miras e anel de carga", "categoria": "UI de mira", "mecanica": "Arco (ARC-02, ARC-03, ARC-04) e Tiro (TIR-04 bloom)", "conceito": "Elementos de mira desenhados por cima do mundo. O anel de carga flutua acima da cabeça do herói e enche no sentido horário com creme; na carga cheia vira dourado com faíscas (janela do tiro perfeito) e, cansado, vira vermelho tremido. No chão, um anel achatado marca onde a flecha vai cair, e a trajetória prevista é feita de pontinhos. Para as armas de fogo, uma mira em cruz que abre (bloom) a cada tiro.", "partes": [{"parte": "Anel de carga", "descricao": "trilho escuro #2a2230 raio 14 px espessura 5, preenchimento #f4efe6 com borda #b9b0a0 em 25/50/75/100%"}, {"parte": "Anel dourado / vermelho", "descricao": "dourado #f2c230 com brilho #fff6c8 e 4 faíscas; vermelho #c8323a com borda serrilhada e brilho #ff5a5a"}, {"parte": "Anel de queda", "descricao": "elipse 40×16 px tracejada creme com centro em cruz e sombra roxa"}, {"parte": "Ponto", "descricao": "bolinha 4 px #f4efe6 com contorno escuro"}, {"parte": "Mira em cruz", "descricao": "4 traços de 7 px #f4efe6 com contorno, ponto central; vão de 4 px (normal) e 13 px (aberta)"}], "paleta": [{"nome": "Trilho", "hex": "#2a2230"}, {"nome": "Creme", "hex": "#f4efe6"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Brilho vermelho", "hex": "#ff5a5a"}], "arquivo": "sprites/arm_mira.png", "fw": 64, "fh": 64, "cols": 10, "quadros": ["carga 25%", "carga 50%", "carga 75%", "carga 100%", "carga dourada (perfeito)", "carga vermelha (cansaço)", "anel de queda no chão", "ponto da linha pontilhada", "mira normal", "mira aberta (bloom)"], "anims": [{"nome": "carga", "quadros": [0, 1, 2, 3, 4], "dur": [200, 200, 200, 200, 350], "loop": false}], "uso": "Todos com âncora no centro (32, 32). Anel de carga: 20 px acima da cabeça do herói. Anel de queda: no chão (camada de chão, embaixo dos personagens). Ponto: repetido ao longo do arco previsto a cada ~10 px, com alpha caindo. Mira: segue cursor/dedo; o jogo interpola entre normal e aberta pelo bloom.", "w": 640, "h": 64}]}, {"grupo": "armas_corpo", "titulo": "Escudo, martelo e espada", "ordem": 6, "resumo": "Armas corpo a corpo do herói (escudo de tampa de tambor, marreta de obra e facão longo serrilhado) com todos os estados de combate, e os efeitos de golpe: faíscas de bloqueio/parry, shockwave da martelada, arcos de golpe, crítico e efeitos de morte.", "itens": [{"id": "cor_escudo", "nome": "Escudo de tampa de tambor", "categoria": "Arma / Defesa", "mecanica": "Defesa (DEF-01, DEF-03, DEF-05, DEF-09)", "conceito": "Tampa redonda de tambor de óleo de 200 L, arrancada de um posto da Avenida Rio Branco e transformada em escudo. A face de aço abaulado tem os dois anéis de reforço do tambor, o tampão rosqueado e uma lua vermelha pintada à mão que já descasca, mostrando o metal e a ferrugem por baixo. Um pedaço de placa de trânsito amarela (advertência) foi rebitado por cima de um furo, e na borda há oito rebites e respingos de sangue seco. Atrás, duas alças de couro cru presas com parafusos e uma correia com fivela. Lê no jogo como um disco cinza grande com a lua vermelha no centro, mesmo de longe.", "partes": [{"parte": "Disco (face)", "descricao": "Elipse de ~60×62 px de frente (erguido), ~22×60 de lado (abaixado), 64×30 deitado no chão. Aço #7d848c com degradê em degraus (luz em cima-esquerda), dois anéis de reforço concêntricos (r 0,78 e 0,5) em linha clara/escura, riscos claros e manchas de ferrugem #8a4e2e com textura."}, {"parte": "Borda/espessura", "descricao": "Aro de ~4 px #6b747a, mais claro em cima (a câmera vê o topo da borda); dobrado e amassado no estado rachado."}, {"parte": "Lua vermelha", "descricao": "Círculo pintado de raio ~0,5 do disco, #c8323a com brilho #ff5a5a no canto, descascando nas bordas (falhas mostram o aço) e escorridos de tinta para baixo."}, {"parte": "Remendo de placa", "descricao": "Losango de placa de trânsito amarela #e0b430 ~16 px no quadrante de baixo-esquerda, faixa preta de borda e pedaço de seta, preso com 4 rebites."}, {"parte": "Rebites e tampão", "descricao": "8 rebites de 2 px #c9ced4 com ponto escuro em volta da borda; tampão rosqueado de 7 px no quadrante de cima-direita."}, {"parte": "Alças de couro", "descricao": "Couro #8a5530/#6b3f22 com costura clara; aparecem na vista de lado (alça e correia com fivela #c9c3b0) e no chão (pontinha de correia saindo por baixo)."}, {"parte": "Estados", "descricao": "Parry: tinta mistura 25% com dourado #f2c230, contorno extra dourado e aura radial dourada pulsando com brilhinhos. Rachado: 3 rachaduras pretas ramificadas, lasca faltando na borda, amassado escuro, lua mais descascada. Caindo: inclinado ~60°, mais baixo."}], "paleta": [{"nome": "Aço do tambor", "hex": "#7d848c"}, {"nome": "Aço escuro", "hex": "#6b747a"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Lua vermelha", "hex": "#c8323a"}, {"nome": "Brilho lua", "hex": "#ff5a5a"}, {"nome": "Placa amarela", "hex": "#e0b430"}, {"nome": "Couro", "hex": "#8a5530"}, {"nome": "Couro escuro", "hex": "#6b3f22"}, {"nome": "Sangue seco", "hex": "#5a1a1a"}, {"nome": "Aura parry", "hex": "#f2c230"}], "arquivo": "sprites/cor_escudo.png", "fw": 128, "fh": 128, "cols": 8, "quadros": ["abaixado (de lado)", "erguido (frente)", "erguido overshoot/squash", "parry janela 1 (aura dourada)", "parry janela 2 (aura dourada)", "rachado (guarda quebrada)", "caindo", "no chão (loot)"], "anims": [{"nome": "snap it up", "quadros": [0, 2, 1], "dur": [30, 50, 200], "loop": false}, {"nome": "janela de parry", "quadros": [3, 4], "dur": [75, 75], "loop": true}, {"nome": "guarda quebrada", "quadros": [5, 6, 7], "dur": [140, 120, 600], "loop": false}], "uso": "Pivô na alça (centro do disco, ~64,60); o herói segura pela mão da frente. Arte em escala de item (~1,5× o herói): no boneco usar 0,6× ou a versão do heroi_equip. Overshoot do DEF-01 = quadro 2 por 1 tick; o resto do squash pode ser transformação em tempo real. Loot apoia em gy=112 com sombra. A aura de parry só aparece durante a janela de 0,15 s.", "w": 1024, "h": 128}, {"id": "cor_faiscas", "nome": "Faíscas de bloqueio e parry", "categoria": "FX / Defesa", "mecanica": "Defesa (DEF-03, DEF-05, DEF-07)", "conceito": "Efeitos que saem do escudo quando um golpe é defendido. No bloqueio comum, riscos de faísca laranja quente espirram para a direita (contrários ao golpe que vem da esquerda) e caem com gravidade, esfriando até brasa. No parry perfeito as faíscas são douradas e brancas, saem em todas as direções com um brilho em cruz, e um anel dourado se expande a partir do escudo. O inimigo atordoado ganha estrelinhas amarelas girando em órbita elíptica sobre a cabeça. Tudo é desenhado para modo aditivo, com núcleo quase branco.", "partes": [{"parte": "Faíscas laranja (3 q)", "descricao": "Origem em (14,32). Q1: clarão de 8 px + 8 riscos curtos de 4–8 px; Q2: riscos de 8–14 px curvando para baixo, cabeça #fff4c0, corpo #ff9a2a, cauda #c8501a; Q3: brasinhas de 1–2 px caindo, #c8501a."}, {"parte": "Faíscas douradas (3 q)", "descricao": "Origem no centro (32,32), 12 riscos em 360° #fff6c8/#f2c230/#b8861a, cruz de brilho de 9 px; esfriam para gotas douradas no Q3."}, {"parte": "Anel do parry (3 q)", "descricao": "Elipse (achatada 0,8) de raio 9 → 18 → 27 px, espessura 5 → 3 → 1 px, borda dourada #f2c230 com interior branco; no último quadro o anel fica pontilhado e transparente."}, {"parte": "Estrelas de stagger (4 q)", "descricao": "3 estrelas de 5 pontas (r 4 px) #f2c230 com contorno #3a2a08 em órbita rx 18 ry 6 em y=32; as que passam atrás ficam menores e mais escuras; trilha de pontinhos da órbita."}], "paleta": [{"nome": "Núcleo", "hex": "#fff4c0"}, {"nome": "Faísca laranja", "hex": "#ff9a2a"}, {"nome": "Brasa", "hex": "#c8501a"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Branco quente", "hex": "#fff6c8"}], "arquivo": "sprites/cor_faiscas.png", "fw": 64, "fh": 64, "cols": 13, "quadros": ["bloqueio 1", "bloqueio 2", "bloqueio 3", "parry faíscas 1", "parry faíscas 2", "parry faíscas 3", "anel parry 1", "anel parry 2", "anel parry 3", "stagger 1", "stagger 2", "stagger 3", "stagger 4"], "anims": [{"nome": "bloqueio", "quadros": [0, 1, 2], "dur": [50, 80, 110], "loop": false}, {"nome": "parry", "quadros": [3, 4, 5], "dur": [60, 90, 120], "loop": false}, {"nome": "anel", "quadros": [6, 7, 8], "dur": [60, 80, 100], "loop": false}, {"nome": "stagger", "quadros": [9, 10, 11, 12], "dur": [100, 100, 100, 100], "loop": true}], "uso": "Bloqueio: pivô em (14,32), espelhar/girar para a direção contrária ao golpe; desenhar em modo aditivo. Parry e anel: pivô no centro, sobre o escudo. Stagger: pivô (32,32) sobre a cabeça do zumbi por 1,4 s. A queda com gravidade das partículas reais pode ser simulada; o sprite é o visual de cada risco/estágio.", "w": 832, "h": 64}, {"id": "cor_martelo", "nome": "Marreta de obra", "categoria": "Arma / Martelo", "mecanica": "Martelo (HAM-01, HAM-02, HAM-03, HAM-07)", "conceito": "Marreta de 5 kg tirada de uma obra parada no Bairro do Recife: cabo comprido de madeira (eucalipto) escurecido de suor, enrolado com fita isolante preta e azul perto da mão e do olho, e cabeça de aço forjado lascada nas quinas. Uma das faces de batida está manchada de sangue seco e ferrugem, e a cunha de metal aparece no topo do olho. O peso se lê pelo tamanho desproporcional da cabeça. Carregada, a cabeça esquenta em branco-dourado e pulsa; na descida vira um borrão esticado; no recovery fica cravada no chão rachado.", "partes": [{"parte": "Cabo", "descricao": "84 px de comprimento × 5 px, madeira #a87444 com veios #7a4e2a e #c8945a, nó escuro, ponta arredondada (castão) de 7 px."}, {"parte": "Fita", "descricao": "Pega de 16 px de fita preta #26262c com voltas em diagonal #5a5a66; colar de fita azul #2f5a8c de 5 px junto ao olho."}, {"parte": "Cabeça", "descricao": "Bloco de aço 18 × 36 px perpendicular ao cabo, #6b747a com bisel claro #9aa0aa, faces de batida alargadas (+2 px), quinas lascadas, ferrugem #8a4e2e e sangue seco #5a1a1a na face da frente; cunha #c9ced4 no topo do olho; marca estampada de pontinhos."}, {"parte": "Carregada", "descricao": "Cabeça mistura 35–55% com #ffd36a/#fff6c8, aura dourada radial r 26–32 px e brilhinhos; dois quadros pulsando."}, {"parte": "Descida", "descricao": "Marreta esticada 1,2× ao longo do eixo, 3 fantasmas translúcidos nos ângulos anteriores e um leque de borrão branco-azulado entre eles."}, {"parte": "Cravada", "descricao": "Cabeça afundada no chão (cortada em y=106), cratera escura em elipse, rachaduras e torrões de terra/asfalto."}], "paleta": [{"nome": "Madeira", "hex": "#a87444"}, {"nome": "Veio", "hex": "#7a4e2a"}, {"nome": "Fita preta", "hex": "#26262c"}, {"nome": "Fita azul", "hex": "#2f5a8c"}, {"nome": "Aço", "hex": "#6b747a"}, {"nome": "Bisel", "hex": "#9aa0aa"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sangue seco", "hex": "#5a1a1a"}, {"nome": "Brilho carga", "hex": "#ffd36a"}], "arquivo": "sprites/cor_martelo.png", "fw": 128, "fh": 128, "cols": 7, "quadros": ["repouso", "windup (atrás da cabeça)", "carregada 1", "carregada 2", "descida (stretch + borrão)", "cravada no chão (recovery)", "no chão (loot)"], "anims": [{"nome": "carregando", "quadros": [2, 3], "dur": [110, 110], "loop": true}, {"nome": "martelada", "quadros": [0, 1, 4, 5], "dur": [120, 450, 70, 550], "loop": false}], "uso": "Pivô na pega (fim do cabo): repouso (66,14), windup/carregada (86,98), descida (36,104), cravada (28,40). O giro do windup com ease-out é feito em tempo real girando o quadro 0; os quadros 1–5 são poses-chave. O tremor do HAM-02 é deslocamento em tempo real. Loot em gy=112 com sombra.", "w": 896, "h": 128}, {"id": "cor_shockwave", "nome": "Shockwave da martelada", "categoria": "FX / Martelo", "mecanica": "Martelo (HAM-01, HAM-05, HAM-06)", "conceito": "Tudo que a martelada faz no chão, desenhado em elipse achatada para a câmera 3/4. Dois anéis de poeira e ar comprimido saem do ponto de impacto, o segundo menor e atrasado. Fica uma rachadura em estrela no asfalto/pedra portuguesa com o centro afundado, que esmaece com o tempo. Destroços (pedra portuguesa preta e branca, asfalto, concreto com vergalhão, tijolo) voam e quicam, e uma nuvem de poeira bege sobe. Antes do golpe, um anel pontilhado mostra a área (pequeno sem carga, grande com carga cheia).", "partes": [{"parte": "Anéis (4 q)", "descricao": "Centro (96,68), elipse ry = 0,45 rx. Anel externo rx 22 → 44 → 68 → 90, espessura 7 → 2 px; interno 60 ms atrasado rx 0 → 24 → 46 → 66. Branco quente #fff4e0 na frente, poeira #d8c8a8 atrás, pontinhos de poeira na borda; alpha cai até ~35%."}, {"parte": "Rachadura", "descricao": "Decal de ~120×50 px: centro afundado (elipse 20×9 escura #2a2228), 9 rachaduras ramificadas #1a1214 de 1–2 px com borda clara #8a7a68 do lado da luz, placas de chão levantadas. Versão esmaecida = mesma arte a 35% de opacidade."}, {"parte": "Destroços (6)", "descricao": "Seis pedacinhos de 6–12 px com contorno e sombra: pedra portuguesa branca #d8d2c2, pedra portuguesa preta #3a3640, asfalto #4a4650 com pedrisco, concreto #9a968e com vergalhão enferrujado, tijolo #a5432e, lasca de pedra cinza."}, {"parte": "Poeira (3 q)", "descricao": "Nuvens bege #b8a888/#9c8a70 em faixa sobre o chão; crescem de 40 para 150 px de largura, sobem 8 px e ficam transparentes."}, {"parte": "Anel pontilhado", "descricao": "Traços de 4 px #f4e6c0 com contorno escuro em elipse rx 48/92 (raio 48 → 92 px do HAM-02), preenchimento vermelho muito leve e 4 marcas nos pontos cardeais."}], "paleta": [{"nome": "Ar/núcleo", "hex": "#fff4e0"}, {"nome": "Poeira clara", "hex": "#d8c8a8"}, {"nome": "Poeira", "hex": "#9c8a70"}, {"nome": "Rachadura", "hex": "#1a1214"}, {"nome": "Borda da rachadura", "hex": "#8a7a68"}, {"nome": "Afundado", "hex": "#2a2228"}, {"nome": "Pedra portuguesa", "hex": "#d8d2c2"}, {"nome": "Asfalto", "hex": "#4a4650"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Telegrafia", "hex": "#f4e6c0"}], "arquivo": "sprites/cor_shockwave.png", "fw": 192, "fh": 128, "cols": 12, "quadros": ["anéis 1", "anéis 2", "anéis 3", "anéis 4", "rachadura fresca", "rachadura esmaecida 35%", "destroços (6 variações)", "poeira 1", "poeira 2", "poeira 3", "anel pontilhado pequeno", "anel pontilhado grande"], "anims": [{"nome": "shockwave", "quadros": [0, 1, 2, 3], "dur": [60, 80, 110, 150], "loop": false}, {"nome": "poeira", "quadros": [7, 8, 9], "dur": [140, 220, 300], "loop": false}], "uso": "Tudo no chão, abaixo dos personagens, pivô no centro (96,68). Os anéis podem ser escalados em tempo real para o raio da carga (48–92 px). Rachadura fica 20 s: alpha 100% → 35% (quadro 5 é a referência). Destroços: recortar cada pedaço (6 caixas de 32 px em linha) e simular quique com sombra. Anel pontilhado gira devagar em tempo real durante o windup.", "w": 2304, "h": 128}, {"id": "cor_espada", "nome": "Facão longo serrilhado", "categoria": "Arma / Ataque", "mecanica": "Ataque e Crítico (ATK-01, CRT-02; Getsuga)", "conceito": "A arma principal do herói: um facão de cana comprido, tirado de um engenho da Zona da Mata, com as costas da lâmina serrilhadas à lima para virar serra. A lâmina é aço carbono gasto, com fio brilhante, manchas de ferrugem e sangue seco, e alarga perto da ponta cortada em ângulo, como o facão do herói. A guarda é improvisada com uma chapa dobrada parafusada e arame enrolado, e o cabo de madeira escura tem pinos de latão e fita. No crítico ganha contorno e aura dourada; carregando o Getsuga fica envolta em chamas vermelho-pretas; ao afiar, um brilho branco corre pela lâmina.", "partes": [{"parte": "Cabo", "descricao": "26 × 7 px, madeira escura #24201e com 3 pinos de latão #d8b04a, fita #5a3a22 em voltas e castão de metal #8a8e98."}, {"parte": "Guarda", "descricao": "Chapa dobrada #8a8e98 de 4 × 16 px com 2 parafusos #c9ced4, arame de cobre #b87333 enrolado (4 voltas)."}, {"parte": "Lâmina", "descricao": "~78 px, largura 8 px na base → 13 px perto da ponta, #b8bec8; fio #eef2f8 de 1–2 px embaixo, lombo #5a606c em cima com 9 dentes de 2–3 px; ponta cortada em ângulo; ferrugem #8a4a24, sangue #6a1a1a e 3 dentes (mossas) no fio."}, {"parte": "Crítico", "descricao": "Lâmina mistura 30% com #f2c230, contorno extra dourado e aura radial dourada; brilhinhos."}, {"parte": "Getsuga", "descricao": "Lâmina escurecida (60% com #2a1018) e fio vermelho #ff5a5a; chamas pretas #1a0a10 com borda #c8323a subindo da lâmina (2 quadros que tremulam)."}, {"parte": "Sharpen", "descricao": "Faixa branca diagonal de 5 px que corre da base (u≈25%) à ponta (u≈90%) em 3 quadros, com estrela de brilho de 7 px."}], "paleta": [{"nome": "Lâmina", "hex": "#b8bec8"}, {"nome": "Fio", "hex": "#eef2f8"}, {"nome": "Lombo", "hex": "#5a606c"}, {"nome": "Cabo", "hex": "#24201e"}, {"nome": "Latão", "hex": "#d8b04a"}, {"nome": "Guarda", "hex": "#8a8e98"}, {"nome": "Arame de cobre", "hex": "#b87333"}, {"nome": "Ferrugem", "hex": "#8a4a24"}, {"nome": "Dourado crítico", "hex": "#f2c230"}, {"nome": "Getsuga vermelho", "hex": "#c8323a"}, {"nome": "Getsuga preto", "hex": "#1a0a10"}], "arquivo": "sprites/cor_espada.png", "fw": 128, "fh": 64, "cols": 8, "quadros": ["normal", "crítico (brilho dourado)", "Getsuga carregando 1", "Getsuga carregando 2", "afiar 1", "afiar 2", "afiar 3", "no chão (loot)"], "anims": [{"nome": "getsuga", "quadros": [2, 3], "dur": [90, 90], "loop": true}, {"nome": "afiar", "quadros": [4, 5, 6, 0], "dur": [70, 70, 70, 300], "loop": true}], "uso": "Perfil horizontal, ponta para a direita; pivô na pega (16,33). O jogo gira o quadro para o ângulo do golpe. Crítico dura 0,4 s (CRT-02). Getsuga: loop enquanto carrega. Loot: apoiado em gy=56 com sombra, no quadro 128×64.", "w": 1024, "h": 64}, {"id": "cor_arco_golpe", "nome": "Arco do golpe", "categoria": "FX / Ataque", "mecanica": "Ataque e Crítico (ATK-01, CRT-02, giro KIL)", "conceito": "O rastro do facão no ar, em forma de lua crescente afinando na cauda, cobrindo ~120° na frente do herói e achatado para a câmera 3/4. O normal é branco-azulado com núcleo branco no fio do arco e riscos de velocidade por dentro; no crítico vira dourado com brilhinhos. O giro (Q) é um anel completo de 360° que se fecha e se desfaz. Cada sequência tem 3 quadros: o arco nascendo, cheio e se desfazendo em fiapos.", "partes": [{"parte": "Crescente", "descricao": "Centro (64,64), raio externo 46 px, achatado 0,8 em y; espessura máxima 14 px na frente do golpe, afinando até 1 px na cauda; cobre −60° a +60° (frente à direita)."}, {"parte": "Faixas de cor", "descricao": "Normal: borda externa #ffffff, meio #e8ecf4, interno #a8b4cc translúcido. Crítico: #fff6c8, #f2c230, #b8861a e brilhinhos. Contorno externo fino escurecido para ler no chão claro."}, {"parte": "Riscos", "descricao": "3–4 riscos concêntricos de 1 px em cor mais clara dentro do crescente; no quadro 3 o arco se quebra em fiapos e fica com ~45% de opacidade."}, {"parte": "Giro 360°", "descricao": "Q1: 220° do anel com cabeça grossa; Q2: anel completo raio 48; Q3: anel fino e quebrado, translúcido."}], "paleta": [{"nome": "Branco", "hex": "#ffffff"}, {"nome": "Branco-azulado", "hex": "#e8ecf4"}, {"nome": "Azul fumaça", "hex": "#a8b4cc"}, {"nome": "Ouro claro", "hex": "#fff6c8"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro escuro", "hex": "#b8861a"}], "arquivo": "sprites/cor_arco_golpe.png", "fw": 128, "fh": 128, "cols": 9, "quadros": ["normal 1", "normal 2", "normal 3", "crítico 1", "crítico 2", "crítico 3", "giro 360 1", "giro 360 2", "giro 360 3"], "anims": [{"nome": "golpe", "quadros": [0, 1, 2], "dur": [50, 70, 60], "loop": false}, {"nome": "golpe crítico", "quadros": [3, 4, 5], "dur": [50, 70, 60], "loop": false}, {"nome": "giro", "quadros": [6, 7, 8], "dur": [60, 90, 80], "loop": false}], "uso": "Pivô no centro (64,64) = posição do herói; o arco aponta para a direita e é girado para a direção do golpe (0,18 s). Desenhar sobre os personagens, modo normal ou aditivo. Alcance real do ATK-01 é ~24 px: escalar ~0,6× em jogo.", "w": 1152, "h": 128}, {"id": "cor_kill", "nome": "Efeitos de morte", "categoria": "FX / Kill", "mecanica": "Kill (KIL-01, KIL-03, KIL-05, KIL-09; ATK-05)", "conceito": "Tudo o que sobra quando um zumbi morre. No impacto, uma faísca branca em estrela com contorno vermelho; em seguida respingos de sangue escuro voam na direção do golpe com rastro e caem pingando. No pop, o corpo estoura numa lufada branca com anel e sobra uma chuva de pedaços com contorno (carne verde do errante, pano da camisa azul, osso, dente). No chão fica uma poça que cresce com respingos para o lado do golpe, que depois seca e escurece; às vezes com um osso. Na opção de violência reduzida tudo vira fumaça cinza e moedinhas, e a marca vira só uma sombra.", "partes": [{"parte": "Faísca de impacto", "descricao": "Estrela de 16 pontas r 22 px #fff4d0 com núcleo #ffffff e contorno #c9343a, mais 6 riscos brancos de 6–10 px."}, {"parte": "Respingos (3 q)", "descricao": "Gotas de 2–6 px #c8202a/#8a1420 com brilho #ff6a6a e contorno #2a0a10, saindo de (34,64) para a direita; Q2 com rastros alongados, Q3 gotas caindo e pingos."}, {"parte": "Lufada de pop (3 q)", "descricao": "Q1 clarão branco r 14 e anel r 18; Q2 6 nuvens brancas #f4efe6/#cfc8d8 r 8–12 e anel r 32 fino; Q3 nuvens se desfazendo e anel pontilhado r 44."}, {"parte": "Pedaços (6)", "descricao": "Em grade 3×2: carne verde #7fa05a, carne vermelha #a8323a, pano azul #5a7aa0 rasgado, osso #e8dcc0, tufo de cabelo #4a3a2a com pele, dente #f0e8d0 — cada um 10–16 px com contorno."}, {"parte": "Poça", "descricao": "Elipse no chão em y=86: pequena rx 14 → cheia rx 32 com respingos e gotas para a direita; #8a1420 com topo #b01c28 e reflexo #e04a50. Seca: #3e1216/#4a1418 fosca com borda craquelada. Com osso: osso #e8dcc0 deitado na poça."}, {"parte": "Violência reduzida", "descricao": "Nuvem de fumaça cinza #8a8494 com 5 moedinhas douradas #f2c230 de 5 px voando; marca no chão = sombra roxa com 3 moedas."}], "paleta": [{"nome": "Sangue", "hex": "#c8202a"}, {"nome": "Sangue escuro", "hex": "#8a1420"}, {"nome": "Brilho sangue", "hex": "#ff6a6a"}, {"nome": "Sangue seco", "hex": "#3e1216"}, {"nome": "Faísca", "hex": "#fff4d0"}, {"nome": "Lufada", "hex": "#f4efe6"}, {"nome": "Carne de zumbi", "hex": "#7fa05a"}, {"nome": "Osso", "hex": "#e8dcc0"}, {"nome": "Fumaça", "hex": "#8a8494"}, {"nome": "Moeda", "hex": "#f2c230"}], "arquivo": "sprites/cor_kill.png", "fw": 128, "fh": 128, "cols": 14, "quadros": ["faísca de impacto", "respingos 1", "respingos 2", "respingos 3", "pop 1 (clarão + anel)", "pop 2 (lufada)", "pop 3 (se desfaz)", "pedaços (6)", "poça crescendo 1", "poça crescendo 2", "poça seca", "poça com osso", "violência reduzida: fumaça + moedas", "violência reduzida: marca (sombra)"], "anims": [{"nome": "respingos", "quadros": [0, 1, 2, 3], "dur": [60, 70, 90, 120], "loop": false}, {"nome": "pop", "quadros": [4, 5, 6], "dur": [60, 90, 130], "loop": false}, {"nome": "poça", "quadros": [8, 9], "dur": [75, 75], "loop": false}], "uso": "Pivô no centro (64,64); respingos e poça apontam para a direita = direção do golpe (espelhar/girar). Pedaços: recortar cada um (caixas de ~40 px) e simular quique por 14 instâncias. Poça no chão (camada de decal), cresce em 0,15 s, seca em 20 s (cross-fade quadro 9 → 10). KIL-09 troca respingos/pedaços/poça pelos quadros 12–13.", "w": 1792, "h": 128}, {"id": "cor_impacto_numero", "nome": "Estouro do crítico e ✖ de kill", "categoria": "FX / Crítico", "mecanica": "Crítico (CRT-02, CRT-06) e Tiro (TIR-07)", "conceito": "Peças de HUD do mundo que acompanham o número de dano. A estrela de impacto do crítico é um clarão dourado de 8 pontas com núcleo branco que pisca no ponto do golpe. Atrás do número grande e do 'CRÍTICO!' vai um estouro de quadrinho com bordas em ponta, em degraus de cor do amarelo no centro ao laranja na borda, com contorno escuro grosso. O '✖' vermelho de kill do tiro é um X grosso com contorno escuro e brilho, que estoura e some.", "partes": [{"parte": "Estrela do crítico (2 q)", "descricao": "8 pontas r 26/12 px, faixas #ffffff → #fff6c8 → #f2c230 → contorno #b8861a/#3a2a08; Q2 girada 22° e menor (r 20) com brilhinhos."}, {"parte": "Estouro (2 q)", "descricao": "Explosão de quadrinho de 14 pontas irregulares, ~44×34 px no normal e ~62×48 px no pico do pop (Q2, ~140%, preenche o quadro); degraus #fff27a, #ffd23a, #f6a02a, #e0601a; contorno de 3 px #2a1208; brilho laranja suave em volta."}, {"parte": "✖ de kill (2 q)", "descricao": "X de 30 px com hastes de 8 px, #e0303a com brilho #ff7a7a em cima e sombra #8a1420, contorno 2 px #1a0a0e; Q2 maior com flash branco por dentro."}], "paleta": [{"nome": "Amarelo", "hex": "#fff27a"}, {"nome": "Amarelo ouro", "hex": "#ffd23a"}, {"nome": "Laranja", "hex": "#f6a02a"}, {"nome": "Laranja escuro", "hex": "#e0601a"}, {"nome": "Contorno", "hex": "#2a1208"}, {"nome": "Vermelho kill", "hex": "#e0303a"}, {"nome": "Dourado", "hex": "#f2c230"}], "arquivo": "sprites/cor_impacto_numero.png", "fw": 64, "fh": 64, "cols": 6, "quadros": ["estrela crítico 1", "estrela crítico 2", "estouro do CRÍTICO! (normal)", "estouro do CRÍTICO! (pico do pop ~140%)", "✖ kill", "✖ kill (pop/flash)"], "anims": [{"nome": "estrela", "quadros": [0, 1], "dur": [60, 80], "loop": false}, {"nome": "pop do crítico", "quadros": [3, 2], "dur": [120, 880], "loop": false}, {"nome": "kill de tiro", "quadros": [5, 4], "dur": [80, 500], "loop": false}], "uso": "Pivô no centro (32,32). O número de dano é texto do jogo desenhado por cima do estouro; o pop 0 → 160% → 100% e a inclinação de ±8° são transformações em tempo real (quadro 3 serve de pico). Camada de HUD do mundo, acima de tudo.", "w": 384, "h": 64}]}, {"grupo": "especiais_feixe", "titulo": "Laser e Kamehameha", "ordem": 7, "resumo": "Armas e golpes de feixe de fim de jogo: o rifle de laser improvisado com peças de micro-ondas (LSR) e a onda de energia de ki carregada entre as mãos (KMH). Os feixes são montados no jogo com peças: início (boca), meio repetível na horizontal (tileável) e ponta, sempre em camadas nítidas de pixel art (halo, corpo, núcleo branco), nunca degradê liso.", "itens": [{"id": "lsr_arma", "nome": "Rifle de laser improvisado", "categoria": "Especial / Arma", "mecanica": "Laser (LSR-01, LSR-06, LSR-07, LSR-08)", "conceito": "Arma rara de fim de jogo montada por algum técnico sobrevivente numa oficina do Recife Antigo: a carcaça é a caixa de um micro-ondas velho (esmalte bege encardido, painel de teclas com visor verde ainda aceso), o magnetron virou o coração do disparo e o cano é um tubo de metal com bobinas de fio de cobre enroladas à mão e aletas de dissipador de computador. Em cima vai presa com cintas a célula de energia de vidro, que brilha ciano quando carregada; dois cabos (vermelho e preto) saem dela até as bobinas, e embaixo do cano fica um banco de capacitores azuis. A coronha é um pedaço de madeira enrolado com fita prata, o punho é de plástico preto com ranhuras. Ferrugem, arranhões, rebites e um adesivo de alerta amarelo deixam claro que é gambiarra — perigosa e poderosa. Lê no jogo pelo brilho ciano na célula e na lente da boca; ao carregar, a boca acende e puxa partículas; depois do tiro, aletas e cano ficam vermelhos e soltam vapor.", "partes": [{"parte": "Coronha", "descricao": "Madeira de estaca (#8a6a42) de ~26×16 px à esquerda, com textura de veio, duas voltas de fita prata (#9a9a92) e chapa de borracha preta (#2e2a2e) na ponta."}, {"parte": "Carcaça de micro-ondas", "descricao": "Caixa de ~40×20 px em esmalte bege sujo (#d8d2c2) com fendas de ventilação escuras, manchas de ferrugem (#8a4e2e), 4 rebites (#c9ced4), adesivo triangular amarelo (#f2c230) e painel frontal escuro (#3a3a40) com teclas 2×3 e visor verde (#6fdc7a)."}, {"parte": "Célula de energia", "descricao": "Cilindro de vidro deitado de ~20×8 px em cima da carcaça, tampas de metal (#7d848c), duas cintas escuras; o plasma ciano (#2fd2ff) tem faixa branca no meio. Apaga quando vazia, brilha forte em carga cheia."}, {"parte": "Cabos", "descricao": "Cabo vermelho (#c8323a) e preto (#2a2228) de 2 px fazendo curva da célula até as bobinas."}, {"parte": "Bobinas de cobre", "descricao": "Bloco de ~20×14 px em volta do cano, fio de cobre (#b86a32) em listras verticais de 1 px com brilho (#e8a060) e sombra (#7a3e1a). Na superaquecida ficam vermelho-vivo."}, {"parte": "Aletas", "descricao": "Seis placas finas de alumínio (#9aa2a8), 2 px de largura e 18 px de altura, com 1 px de vão. Superaquecidas: laranja (#ff8a2a) a vermelho (#e83a2a) com brilho."}, {"parte": "Boca / emissor", "descricao": "Anel escuro (#3a3a40) de ~8×12 px com lente circular de raio 3 (#1f6f8f apagada; ciano/branca carregando). É o pivô do feixe (lsr_feixe início)."}, {"parte": "Capacitores e punho", "descricao": "Dois cilindros azuis (#3f6a8c) com listra clara sob o cano; punho de plástico preto (#3a3438) com ranhuras e guarda-mato com gatilho."}, {"parte": "Efeitos", "descricao": "Carregando: bandas ciano em volta da lente (raio 4→7→10) e 8-12 partículas com rastro sendo sugadas. Cheia: esfera de 11-13 px pulsando com 4 raios em cruz. Superaquecida: halo vermelho nas aletas e baforadas de vapor cinza-claro subindo. Chão: deitada inclinada, sombra roxa e brilho azul de raridade rara (#4a8fe0)."}], "paleta": [{"nome": "Esmalte de micro-ondas", "hex": "#d8d2c2"}, {"nome": "Painel escuro", "hex": "#3a3a40"}, {"nome": "Madeira da coronha", "hex": "#8a6a42"}, {"nome": "Fita prata", "hex": "#9a9a92"}, {"nome": "Cobre", "hex": "#b86a32"}, {"nome": "Alumínio das aletas", "hex": "#9aa2a8"}, {"nome": "Metal do cano", "hex": "#6b747a"}, {"nome": "Capacitor azul", "hex": "#3f6a8c"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Ciano energia", "hex": "#2fd2ff"}, {"nome": "Halo azul", "hex": "#2163d0"}, {"nome": "Superaquecido", "hex": "#e83a2a"}, {"nome": "Raro", "hex": "#4a8fe0"}], "arquivo": "sprites/lsr_arma.png", "fw": 128, "fh": 64, "cols": 9, "quadros": ["normal", "carregando 1", "carregando 2", "carregando 3", "carga cheia A", "carga cheia B", "superaquecida 1", "superaquecida 2", "no chão (loot)"], "anims": [{"nome": "carregando", "quadros": [1, 2, 3], "dur": [140, 140, 140], "loop": true}, {"nome": "carga cheia", "quadros": [4, 5], "dur": [150, 150], "loop": true}, {"nome": "superaquecida", "quadros": [6, 7], "dur": [180, 180], "loop": true}], "uso": "Perfil apontando para a direita; o jogo gira pelo ângulo da mira (espelha na vertical quando mira para a esquerda). Pivô da mão no punho (~40,44); boca/origem do feixe em (113,31). Carregando: escolher o quadro 1→3 pela carga (0,3–1,2 s) e tremer o sprite até 1,2 px em tempo real; quadros 4-5 em loop na carga cheia. Após o feixe toca 6-7 durante o resfriamento (~1,1 s). O quadro 8 é o item no chão (âncora na base, y≈58), com bob vertical de 1 px em tempo real.", "w": 1152, "h": 64}, {"id": "lsr_feixe", "nome": "Feixe de laser (peças)", "categoria": "Especial / FX", "mecanica": "Laser (LSR-02, LSR-03, LSR-04, LSR-07, LSR-09)", "conceito": "O feixe grosso do rifle: um raio reto de luz ciano que atravessa todos os zumbis e para na parede. É desenhado em camadas nítidas: halo azul em três degraus (2,2× a largura do corpo), corpo ciano em dois tons e núcleo branco (0,4×), com borda pontilhada de 1 px entre camadas no lugar de degradê. Dentro do corpo correm riscos claros horizontais e no halo flutuam pontinhos de energia, que mudam de quadro para quadro e dão a sensação de fluxo. A boca tem uma estrela de luz com quatro raios finos; a ponta termina arredondada num clarão de impacto que espirra faíscas para trás. O fade out afina o feixe até virar um fio e sumir.", "partes": [{"parte": "Halo", "descricao": "Três degraus de azul translúcido: #1a3c9c (alfa 90) até 2,2× da meia-largura, #2163d0 (alfa 140) até 1,85×, #2b8ff0 (alfa 190) até 1,45×. Meia-largura do corpo = 7 px (feixe ~31 px de altura com halo)."}, {"parte": "Corpo", "descricao": "Ciano opaco #2fd2ff até 1×, ciano claro #7ff4ff até 0,72×, com riscos horizontais #b8faff de 6-13 px que se deslocam a cada quadro (padrão de período 32 px, tileável)."}, {"parte": "Núcleo", "descricao": "#e6feff até 0,4× e branco puro #ffffff até 0,22× (≈3 px)."}, {"parte": "Início (boca)", "descricao": "Estrela de 4 pontas sobre a origem em x=24,y=32: bandas com o mesmo esquema de cores, raio de corpo 10 px, raios finos brancos/ciano de 6-14 px em cruz e diagonal, e brilho quantizado em volta."}, {"parte": "Ponta / impacto", "descricao": "O feixe termina em x≈92 com tampa arredondada e um clarão circular (1,5→1,9→1,6× da meia-largura) em x≈96, mais 8-10 faíscas que espirram para trás e para os lados e um anel fino nos quadros 2-3."}, {"parte": "Fade out", "descricao": "O meio afinando: 50%, 22% e um fio de 1 px branco com 1 px ciano em volta; o halo perde alfa a cada passo."}], "paleta": [{"nome": "Halo externo", "hex": "#1a3c9c"}, {"nome": "Halo médio", "hex": "#2163d0"}, {"nome": "Halo interno", "hex": "#2b8ff0"}, {"nome": "Corpo ciano", "hex": "#2fd2ff"}, {"nome": "Corpo claro", "hex": "#7ff4ff"}, {"nome": "Risco", "hex": "#b8faff"}, {"nome": "Núcleo", "hex": "#e6feff"}, {"nome": "Branco", "hex": "#ffffff"}], "arquivo": "sprites/lsr_feixe.png", "fw": 128, "fh": 64, "cols": 10, "quadros": ["início (boca)", "meio pulso 88%", "meio pulso 100%", "meio pulso 112%", "ponta/impacto 1", "ponta/impacto 2", "ponta/impacto 3", "fade out 1 (50%)", "fade out 2 (22%)", "fade out 3 (fio)"], "anims": [{"nome": "meio pulsando", "quadros": [1, 2, 3, 2], "dur": [60, 60, 60, 60], "loop": true}, {"nome": "impacto", "quadros": [4, 5, 6], "dur": [70, 70, 70], "loop": true}, {"nome": "fade out", "quadros": [7, 8, 9], "dur": [110, 120, 120], "loop": false}], "uso": "Montagem: eixo do feixe em y=32 em todas as peças. Desenhar o INÍCIO com a origem (24,32) na boca da arma (lsr_arma, 113,31), repetir o MEIO na horizontal quantas vezes for preciso (é tileável: a coluna 127 casa com a coluna 0 e com o início/ponta) e fechar com a PONTA, cujo clarão (96,32) fica no ponto onde o feixe bate na parede; cortar o último meio se sobrar. Tudo é girado junto pelo ângulo da mira, blend aditivo (ou normal, as camadas já são translúcidas). A escala da carga (×0,6→×1,2) e o overshoot de abertura (140% em 60 ms) são escala vertical em tempo real; a pulsação ±12% vem dos quadros 1-3. No fade out (0,35 s) trocar o meio pelos quadros 7→9. 'Reduzir flashes': usar só o meio 88% e alfa 70% no núcleo.", "w": 1280, "h": 64}, {"id": "lsr_marca", "nome": "Marca queimada do laser", "categoria": "Especial / Chão", "mecanica": "Laser (LSR-05)", "conceito": "Por onde o feixe passa o calçamento fica marcado: um risco alongado de asfalto derretido que nasce em brasa laranja e esfria para vermelho-escuro, depois vira fuligem preta com cinza clara nas bordas e, ao longo de 40 s, esmaece até 35%. A borda é irregular, com respingos de fuligem, para não parecer uma elipse perfeita. No ponto final do feixe fica uma marca maior, quase redonda, com respingos radiais e rachaduras em brasa. São decalques de chão, sem contorno preto forte, para parecerem parte do piso.", "partes": [{"parte": "Fuligem externa", "descricao": "Mancha irregular #2a2228 de ~44×14 px (alfa 210) com pontilhado de textura e respingos soltos; na marca grande ~52×28 px com 10 pontas radiais."}, {"parte": "Queimado interno", "descricao": "Miolo #1a1418 de ~32×8 px, com pontos de cinza #5a5258 e #8a8288 nos estados frios."}, {"parte": "Brasa", "descricao": "Bandas #8f2a14 → #c8401a → #ff8a2a → #ffd36a no centro (~28×6 px) e faíscas soltas; esfriando: só #7a2a1a com pontinhos laranja. Marca grande: centro em brasa e rachaduras laranja que saem dele."}], "paleta": [{"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Queimado", "hex": "#1a1418"}, {"nome": "Cinza", "hex": "#5a5258"}, {"nome": "Cinza clara", "hex": "#8a8288"}, {"nome": "Brasa escura", "hex": "#8f2a14"}, {"nome": "Brasa", "hex": "#c8401a"}, {"nome": "Laranja", "hex": "#ff8a2a"}, {"nome": "Amarelo quente", "hex": "#ffd36a"}], "arquivo": "sprites/lsr_marca.png", "fw": 64, "fh": 64, "cols": 6, "quadros": ["marca em brasa", "marca esfriando", "marca fuligem", "marca esmaecida 35%", "marca final grande em brasa", "marca final grande fuligem"], "anims": [{"nome": "esfriar", "quadros": [0, 1, 2, 3], "dur": [300, 500, 900, 900], "loop": false}, {"nome": "esfriar grande", "quadros": [4, 5], "dur": [600, 900], "loop": false}], "uso": "Decalque no chão, camada de chão (abaixo dos zumbis), centro (32,32). As marcas pequenas são carimbadas ao longo do feixe a cada ~24 px e giradas pelo ângulo do feixe; a grande vai no ponto final. Brasa→fuligem em 1,2 s (cross-fade entre quadros 0→1→2) e depois o alfa cai em tempo real até 35% em 40 s (o quadro 3 mostra o resultado final).", "w": 384, "h": 64}, {"id": "lsr_celula", "nome": "Célula de energia e efeitos de acerto", "categoria": "Especial / Item e FX", "mecanica": "Laser (LSR-04, LSR-05, LSR-08)", "conceito": "A munição do laser: uma célula cilíndrica de vidro grosso com tampas de metal aparafusadas, tirada de gerador do abrigo ou achada como loot raro. Por dentro, plasma ciano em bandas com um fio branco no meio e uma bobina de cobre enrolada em espiral por fora do vidro; na base, uma faixa de alerta amarela e preta, e em cima dois terminais (vermelho e preto). Vazia, o vidro fica cinza-azulado escuro, com uma trinca e um resto de brilho apagado no fundo. A mesma tira traz as faíscas que saltam do zumbi atingido pelo feixe e a fumaça preta que sai do zumbi carbonizado.", "partes": [{"parte": "Tampas", "descricao": "Metal #7d848c com topo elíptico (rx 11, ry 4), parafusos #c9ced4, terminais 3×4 px vermelho #c8323a e preto #2a2228 no topo."}, {"parte": "Vidro e plasma", "descricao": "Tubo de ~16×22 px; cheio: bandas #2b8ff0 → #2fd2ff → #7ff4ff com fio branco vertical e bolhas; vazio: #2a3a44 com reflexo #6a8a9a e trinca branca."}, {"parte": "Bobina e faixa", "descricao": "Espiral de fio de cobre #b86a32 em diagonal sobre o vidro; faixa de alerta com listras #f2c230/#1c1822 na tampa de baixo."}, {"parte": "Faíscas", "descricao": "Explosão de 10-12 faíscas ciano com cabeça branca: quadro 1 curtas e um clarão, 2 longas, 3 pontos caindo e apagando."}, {"parte": "Fumaça de carbonizado", "descricao": "Baforadas #3a3438/#5a5258 com contorno escuro subindo e crescendo (raio 5→9), com 2-4 brasas laranja."}], "paleta": [{"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Plasma", "hex": "#2fd2ff"}, {"nome": "Plasma claro", "hex": "#7ff4ff"}, {"nome": "Vidro vazio", "hex": "#2a3a44"}, {"nome": "Cobre", "hex": "#b86a32"}, {"nome": "Alerta", "hex": "#f2c230"}, {"nome": "Fumaça", "hex": "#3a3438"}, {"nome": "Brasa", "hex": "#ff8a2a"}], "arquivo": "sprites/lsr_celula.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["célula cheia", "célula vazia", "faíscas 1", "faíscas 2", "faíscas 3", "fumaça carbonizado 1", "fumaça carbonizado 2", "fumaça carbonizado 3"], "anims": [{"nome": "faíscas", "quadros": [2, 3, 4], "dur": [50, 60, 80], "loop": true}, {"nome": "fumaça", "quadros": [5, 6, 7], "dur": [170, 170, 170], "loop": true}], "uso": "Quadros 0-1: ícone de HUD/inventário e item no chão (base em y≈54, sombra própria; bob de 1 px em tempo real); a barra de células usa cheia/vazia. Faíscas: centradas (32,32) no ponto em que o feixe toca o zumbi, aditivas, em loop enquanto ele estiver no feixe (giradas aleatoriamente a cada ciclo). Fumaça: âncora na base (32,52) sobre o cadáver carbonizado (tintura escura do zumbi é em tempo real), em loop por alguns segundos.", "w": 512, "h": 64}, {"id": "kmh_esfera", "nome": "Esfera de ki entre as mãos", "categoria": "Especial / FX", "mecanica": "Kamehameha (KMH-01, KMH-06, KMH-09)", "conceito": "A bola de energia que o herói junta entre as mãos antes de soltar a onda. Cresce em cinco tamanhos (raio do corpo 3, 7, 11, 15 e 18 px), sempre em camadas nítidas: aura azul translúcida, corpo azul-claro, miolo ciano e núcleo branco deslocado para cima-esquerda, com arcos claros girando por dentro e partículas sendo sugadas com rastro. Na carga cheia pulsa entre dois tamanhos com um anel fino em volta. Na sobrecarga perde a forma redonda: vira branco-dourada, a borda treme, e raios em zigue-zague e faíscas escapam dela, avisando que vai estourar.", "partes": [{"parte": "Aura", "descricao": "#2c48d0 (alfa 110) até 1,45× do raio e #3a6ae8 (alfa 170) até 1,2×."}, {"parte": "Corpo e miolo", "descricao": "Corpo azul-claro #8cc4ff até 1×, miolo ciano #5ff2ff até 0,72×, #a8fbff até 0,5×."}, {"parte": "Núcleo", "descricao": "Branco #ffffff até 0,3×, deslocado 15% para cima-esquerda (luz da lua), com brilho em cruz pequena nos tamanhos maiores."}, {"parte": "Arcos internos", "descricao": "2 arcos de 1 px #e6feff girando 40° por quadro dentro do corpo (a partir do raio 7)."}, {"parte": "Partículas", "descricao": "6-10 pontinhos ciano com cabeça branca e rastro de 2-4 px apontando para fora, cada vez mais perto do centro."}, {"parte": "Sobrecarga", "descricao": "Paleta dourada (#b8601a, #f2c230, #ffe68a, #fffbe0, branco), borda irregular que muda a cada quadro, 3-4 raios zigue-zague #fff6c8 de 8-12 px e faíscas soltas."}], "paleta": [{"nome": "Aura azul", "hex": "#2c48d0"}, {"nome": "Aura clara", "hex": "#3a6ae8"}, {"nome": "Corpo azul-claro", "hex": "#8cc4ff"}, {"nome": "Miolo ciano", "hex": "#5ff2ff"}, {"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Ouro escuro", "hex": "#b8601a"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro claro", "hex": "#ffe68a"}], "arquivo": "sprites/kmh_esfera.png", "fw": 64, "fh": 64, "cols": 10, "quadros": ["raio 3", "raio 7", "raio 11", "raio 15", "raio 18", "carga cheia A", "carga cheia B", "sobrecarga 1", "sobrecarga 2", "sobrecarga 3"], "anims": [{"nome": "carregando", "quadros": [0, 1, 2, 3, 4], "dur": [140, 140, 140, 140, 140], "loop": false}, {"nome": "carga cheia", "quadros": [5, 6], "dur": [140, 140], "loop": true}, {"nome": "sobrecarga", "quadros": [7, 8, 9], "dur": [60, 60, 60], "loop": true}], "uso": "Centro (32,32) posicionado entre as mãos do herói, camada acima do herói, blend aditivo. O tamanho é escolhido pela carga (0,4–1,5 s → quadros 0-4); depois loop 5-6; após 1,5 s, loop 7-9 com tremor de tela. 'Reduzir flashes': manter o quadro 4 parado no lugar da pulsação.", "w": 640, "h": 64}, {"id": "kmh_carga_chao", "nome": "Chão durante a carga do ki", "categoria": "Especial / Chão", "mecanica": "Kamehameha (KMH-01)", "conceito": "Enquanto o herói carrega, o chão em volta dos pés reage: um anel de poeira e pedrinhas se expande para fora em elipse (visto em 3/4) e o piso ganha um brilho elíptico azul em degraus, refletindo a esfera. Com a carga alta o calçamento racha em linhas que saem do centro e se ramificam, brilhando azul por dentro; depois do disparo as rachaduras ficam frias, escuras, com lascas claras nas bordas. É o que vende o peso do golpe antes da onda sair.", "partes": [{"parte": "Brilho do piso", "descricao": "Elipse centrada em (64,44), rx 18→34 conforme o quadro, ry 0,38×rx, em 3 degraus: #2c48d0 (alfa 70), #5fb4ff (alfa 110), #bff8ff (alfa 150)."}, {"parte": "Anel de poeira", "descricao": "Anel elíptico rx 20/36/52 com tufos de poeira #9c8a70/#c8b898 com contorno escuro, falhas e pedrinhas #77736e subindo; vai ficando mais fino e ralo ao crescer."}, {"parte": "Rachaduras", "descricao": "8 rachaduras ramificadas de 18-50 px saindo do centro, linha #120c10 de 1-2 px com lascas #8e8a84; versão brilhando com fio #5ff2ff/#ffffff por dentro e halo azul."}], "paleta": [{"nome": "Brilho azul", "hex": "#2c48d0"}, {"nome": "Brilho claro", "hex": "#5fb4ff"}, {"nome": "Poeira", "hex": "#9c8a70"}, {"nome": "Poeira clara", "hex": "#c8b898"}, {"nome": "Pedrinha", "hex": "#77736e"}, {"nome": "Rachadura", "hex": "#120c10"}, {"nome": "Lasca", "hex": "#8e8a84"}, {"nome": "Ciano", "hex": "#5ff2ff"}], "arquivo": "sprites/kmh_carga_chao.png", "fw": 128, "fh": 64, "cols": 5, "quadros": ["carga 1 (anel pequeno)", "carga 2", "carga 3 (anel grande)", "rachaduras brilhando", "rachaduras frias"], "anims": [{"nome": "carga", "quadros": [0, 1, 2], "dur": [130, 130, 130], "loop": true}], "uso": "Centro (64,44) nos pés do herói, camada de chão (abaixo do herói). O anel (0-2) toca em loop durante a carga; as rachaduras (3) aparecem a partir de ~70% da carga por baixo do anel e passam para o quadro 4 no disparo, esmaecendo em ~3 s em tempo real.", "w": 640, "h": 64}, {"id": "kmh_onda", "nome": "Onda de ki (peças)", "categoria": "Especial / FX", "mecanica": "Kamehameha (KMH-02, KMH-05, KMH-06, KMH-09)", "conceito": "A onda de energia que sai das mãos: mais grossa e viva que o laser, em quatro camadas nítidas — aura azul em três degraus (2,6×), corpo azul-claro (1,6×), miolo ciano (1×) e núcleo branco (0,45×). Duas espirais de luz giram em volta do feixe, passando por trás (azul, apagadas) e pela frente (brancas), e raios finos em zigue-zague estalam na aura. A boca é uma explosão em pétalas onde ficam as mãos; a cabeça é um bulbo arredondado maior que o corpo, empurrando arcos de choque à frente e espirrando faíscas para trás. A versão de sobrecarga é dourada, 20% mais grossa, com raios brancos mais frequentes.", "partes": [{"parte": "Aura", "descricao": "#2230a8 (alfa 80) até 2,6×, #2c48d0 (alfa 120) até 2,25×, #3a6ae8 (alfa 165) até 1,9× da meia-largura do miolo (8 px) — onda com ~42 px de altura."}, {"parte": "Corpo azul-claro", "descricao": "#6aa8ff até 1,6× e #8cc4ff até 1,3×, com riscos claros correndo."}, {"parte": "Miolo e núcleo", "descricao": "Ciano #5ff2ff até 1×, #a8fbff até 0,75×, branco até 0,45×."}, {"parte": "Espirais", "descricao": "Duas hélices de período 64 px e amplitude 1,75×: metade de trás #7ab8ff 1 px (fica sob o núcleo), metade da frente branca 2 px com borda #bff8ff; giram 1/3 de volta por quadro."}, {"parte": "Raios zigue-zague", "descricao": "Trechos de 20-40 px de raio de 1 px #dff8ff/branco na aura de cima e de baixo, diferentes a cada quadro, tileáveis."}, {"parte": "Início (mãos)", "descricao": "Explosão em 6 pétalas centrada em (30,48), raio de aura ~26 px, com núcleo branco grande, raios curtos e brilho em degraus."}, {"parte": "Cabeça", "descricao": "Bulbo 1,6-1,8× mais largo centrado em x≈84, 2-3 arcos de choque brancos à frente e 8 faíscas jogadas para trás."}, {"parte": "Sobrecarga", "descricao": "Paleta #8a3a10/#b8601a/#e0901f/#f2c230/#ffd95a/#fff0a0/#fffbe0/branco, meia-largura 9,6 px, espirais branco-douradas, mais raios."}], "paleta": [{"nome": "Aura externa", "hex": "#2230a8"}, {"nome": "Aura", "hex": "#2c48d0"}, {"nome": "Aura clara", "hex": "#3a6ae8"}, {"nome": "Corpo azul-claro", "hex": "#6aa8ff"}, {"nome": "Corpo claro", "hex": "#8cc4ff"}, {"nome": "Miolo ciano", "hex": "#5ff2ff"}, {"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Ouro", "hex": "#f2c230"}, {"nome": "Ouro claro", "hex": "#ffd95a"}], "arquivo": "sprites/kmh_onda.png", "fw": 128, "fh": 96, "cols": 10, "quadros": ["início (mãos)", "meio 1", "meio 2", "meio 3", "cabeça 1", "cabeça 2", "cabeça 3", "meio sobrecarga 1", "meio sobrecarga 2", "meio sobrecarga 3"], "anims": [{"nome": "meio girando", "quadros": [1, 2, 3], "dur": [70, 70, 70], "loop": true}, {"nome": "cabeça", "quadros": [4, 5, 6], "dur": [70, 70, 70], "loop": true}, {"nome": "meio sobrecarga", "quadros": [7, 8, 9], "dur": [60, 60, 60], "loop": true}], "uso": "Eixo em y=48 em todas as peças. INÍCIO com o centro da explosão (30,48) entre as mãos do herói (no lugar da kmh_esfera); MEIO repetido na horizontal (tileável, coluna 127 casa com 0) até a cabeça; CABEÇA com o bulbo (84,48) na posição atual da ponta, que viaja a ~1100 px/s — enquanto viaja, o comprimento do meio cresce. Tudo girado pelo ângulo da mira, blend aditivo. Pulsação ±10%, overshoot de abertura e escala de carga/sobrecarga (até ×1,7) são escala vertical em tempo real. O fantasma (KMH-05) é o último quadro do meio com alfa caindo em 1,3 s. Sobrecarga: trocar o meio pelos quadros 7-9 (início/cabeça tingidos de dourado em tempo real). 'Reduzir flashes': linha ciano simples ou meio 2 parado.", "w": 1280, "h": 96}, {"id": "kmh_cupula", "nome": "Cúpula de energia do impacto", "categoria": "Especial / FX", "mecanica": "Kamehameha (KMH-04, KMH-09)", "conceito": "Quando a onda bate, abre uma meia esfera de energia translúcida sobre o ponto de impacto, vista em 3/4: borda (fresnel) clara e opaca, miolo azul translúcido onde dá para ver a base de trás, um reflexo branco em crescente no alto à esquerda (luz da lua) e linhas de latitude tracejadas girando na superfície. No chão, um anel de choque branco-ciano corre para fora levantando tufos de poeira, e o piso embaixo brilha em degraus. Cresce em três quadros com overshoot, pulsa em dois e colapsa em dois — o último é uma implosão num ponto branco com riscos sendo puxados para dentro.", "partes": [{"parte": "Cúpula", "descricao": "Silhueta: semicírculo de raio R (altura 0,92R) sobre elipse de base (0,36R). R = 68 px no tamanho 100%. Halo #2440c8 (alfa 80) até 1,12, #3a6ae8 (alfa 130) até 1,06, miolo #3a7ae8 (alfa 100), banda #4a90f0 (alfa 140) em 0,7-0,86, borda #5fd0ff (alfa 210) em 0,86-1 e fio #c8faff em 0,93-0,99."}, {"parte": "Base de trás e latitudes", "descricao": "Elipse da base visível através da cúpula em #8ff0ff (alfa 140); 2 latitudes (altura 0,35 e 0,7) tracejadas, frente mais clara que trás, girando a cada quadro."}, {"parte": "Reflexo", "descricao": "Crescente branco/#e6feff no quadrante de cima-esquerda, entre 0,62 e 0,8 do raio."}, {"parte": "Anel de choque", "descricao": "Elipse no chão (raio 1,1-1,35R, máx. 92 px) de 3 px: branco no meio, #8ff0ff e #3a6ae8 por fora, com 10-14 tufos de poeira #9c8a70 e pedrinhas."}, {"parte": "Brilho do chão", "descricao": "Elipse em 3 degraus sob a cúpula (#2c48d0, #5fb4ff, #bff8ff)."}, {"parte": "Colapso", "descricao": "Quadro 6: cúpula 55% e mais apagada, faíscas saindo; quadro 7: ponto branco de raio ~10 com 12 riscos puxados para dentro."}], "paleta": [{"nome": "Halo", "hex": "#2440c8"}, {"nome": "Miolo", "hex": "#3a7ae8"}, {"nome": "Banda", "hex": "#4a90f0"}, {"nome": "Borda", "hex": "#5fd0ff"}, {"nome": "Fio da borda", "hex": "#c8faff"}, {"nome": "Branco", "hex": "#ffffff"}, {"nome": "Poeira", "hex": "#9c8a70"}], "arquivo": "sprites/kmh_cupula.png", "fw": 192, "fh": 192, "cols": 7, "quadros": ["crescendo 1 (40%, clarão)", "crescendo 2 (80%)", "crescendo 3 (overshoot 115%)", "pulsando A (100%)", "pulsando B (106%)", "colapsando 1 (55%)", "colapsando 2 (implosão)"], "anims": [{"nome": "abrir", "quadros": [0, 1, 2, 3], "dur": [60, 70, 90, 120], "loop": false}, {"nome": "pulsar", "quadros": [3, 4], "dur": [150, 150], "loop": true}, {"nome": "colapsar", "quadros": [5, 6], "dur": [250, 300], "loop": false}], "uso": "Âncora no centro da base (96,140) = ponto de impacto no chão. Camada acima dos zumbis, blend aditivo. O raio de jogo (40-100 px, +40% na sobrecarga) é escala uniforme em tempo real sobre o quadro (100% = R 68). Abrir em 0,25 s (0-3), pulsar enquanto a onda dura (3-4), colapsar em 0,6 s (5-6). 'Reduzir flashes': pular o quadro 0 e não pulsar.", "w": 1344, "h": 192}, {"id": "kmh_cratera", "nome": "Cratera, trilha queimada e cinzas", "categoria": "Especial / Chão", "mecanica": "Kamehameha (KMH-05)", "conceito": "O rastro que a onda deixa: uma trilha de chão queimado vindo da esquerda até uma cratera elíptica no ponto de impacto, com borda levantada de pedaços de paralelepípedo e asfalto, paredes internas escuras e rachaduras saindo para fora. Ela nasce incandescente azul-branca (o ki ainda vivo no fundo), passa para laranja de pedra quente, vira fuligem e esmaece até 35% ao longo de um minuto. Brasas azuis flutuam por cima por alguns segundos, e os zumbis mortos pela onda viram um montinho de cinza com pontos azuis brilhando e fiapos subindo.", "partes": [{"parte": "Fuligem e trilha", "descricao": "Mancha irregular #2a2228 de ~90×40 px em volta da cratera e faixa de ~14 px de altura vindo da borda esquerda (x 0→50), com textura e respingos; no centro da trilha um risco que brilha conforme o estado."}, {"parte": "Cratera", "descricao": "Elipse centrada em (78,56), rx 30, ry 13, fundo #0f0c10, parede de trás visível #3a3236 em crescente, borda com 18-22 lascas de pedra #8e8a84/#77736e e asfalto #3a3638 com contorno."}, {"parte": "Rachaduras", "descricao": "10 rachaduras ramificadas #120c10 de 10-30 px saindo da borda; nos estados quentes, com fio de luz da cor do estado."}, {"parte": "Incandescência", "descricao": "Azul-branca: #2440c8 → #3fa0ff → #9ff4ff → branco em elipses no fundo; laranja: #8f2a14 → #c8401a → #ff8a2a → #ffd36a; brilho quantizado por cima."}, {"parte": "Brasas azuis", "descricao": "14 pontinhos com núcleo branco, cruz ciano e cantos azuis, subindo ~6 px por quadro com leve balanço (camada separada, fundo transparente)."}, {"parte": "Cinzas de zumbi", "descricao": "Montinho #5a5258 de ~44×16 px com topo #8a8288, pedaços de osso carbonizado #2a2228, 8-10 pontos azuis brilhando e 2 fiapos de fumaça; 2 quadros cintilando."}], "paleta": [{"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Fundo", "hex": "#0f0c10"}, {"nome": "Parede", "hex": "#3a3236"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra escura", "hex": "#77736e"}, {"nome": "Asfalto", "hex": "#3a3638"}, {"nome": "Azul quente", "hex": "#3fa0ff"}, {"nome": "Ciano quente", "hex": "#9ff4ff"}, {"nome": "Laranja", "hex": "#ff8a2a"}, {"nome": "Amarelo", "hex": "#ffd36a"}, {"nome": "Cinza", "hex": "#5a5258"}], "arquivo": "sprites/kmh_cratera.png", "fw": 128, "fh": 96, "cols": 9, "quadros": ["incandescente azul-branco", "laranja", "fuligem", "esmaecida 35%", "brasas azuis 1", "brasas azuis 2", "brasas azuis 3", "cinzas brilhantes 1", "cinzas brilhantes 2"], "anims": [{"nome": "esfriar", "quadros": [0, 1, 2, 3], "dur": [600, 900, 1000, 1000], "loop": false}, {"nome": "brasas", "quadros": [4, 5, 6], "dur": [180, 180, 180], "loop": true}, {"nome": "cinzas", "quadros": [7, 8], "dur": [260, 260], "loop": true}], "uso": "Decalque de chão, centro da cratera (78,56) no ponto de impacto, girado pelo ângulo da onda (a trilha aponta para o herói). A trilha da esquerda pode ser estendida repetindo a coluna 0-40 esticada. Incandescente→laranja→fuligem em ~2,5 s (cross-fade 0→1→2), depois alfa cai em tempo real até 35% em 60 s. Brasas (4-6): camada acima, espalhadas ao longo do trajeto por 2-3 s. Cinzas (7-8): no lugar do zumbi morto, base em (64,74).", "w": 1152, "h": 96}]}, {"grupo": "especiais_golpe", "titulo": "Rasengan, Getsuga e Chidori", "ordem": 8, "resumo": "Efeitos dos três golpes especiais de carregar e soltar do herói: a esfera giratória de corpo a corpo (ciano), o corte que dispara uma lua crescente (preto e vermelho-lua) e a estocada elétrica (branco-azulado). Todos em camadas nítidas de pixel art (halo, corpo, núcleo branco), sem degradê liso.", "itens": [{"id": "rsg_esfera", "nome": "Esfera giratória (carga e cheia)", "categoria": "Especial: Rasengan", "mecanica": "Rasengan (RSG-01 Gather, RSG-02 Rings)", "conceito": "Bola de energia ciano que o herói junta na palma aberta enquanto segura a tela. Nasce como um ponto de 3 px e cresce até 13 px de diâmetro; por dentro giram três braços de espiral branca, como um redemoinho de vento preso numa bolha. Em volta, três anéis finos em eixos diferentes viram em 3D (a metade de trás passa por trás da esfera e fica mais escura, a da frente passa por cima e brilha). Enquanto carrega, partículas ciano chegam em espiral de fora e são sugadas para o centro. Lê no jogo como um farol azul na mão do herói no meio da noite vermelha.", "partes": [{"parte": "Halo", "descricao": "brilho ciano em degraus (glow quantizado), raio ~2,4× o raio da esfera, alpha até 150"}, {"parte": "Corpo", "descricao": "disco de 3 a 13 px de diâmetro em 5 faixas concêntricas deslocadas para cima-esquerda: azul profundo #1a6fd8 na borda, #2f9cff, #6fd0ff, #c4f2ff e núcleo branco; contorno de 1 px #0c2c66"}, {"parte": "Espirais internas", "descricao": "3 braços brancos (#ffffff/#dff8ff) e 3 contra-braços azul-escuros girando 30° por quadro, recortados dentro do corpo"}, {"parte": "Anéis", "descricao": "3 anéis de raio ~1,6× a esfera, 1 px, inclinações 15°/75°/135°, cada um girando no próprio eixo (achata e abre); metade de trás #2a8fe0 escura, metade da frente #d8fbff com pontos brancos"}, {"parte": "Partículas", "descricao": "riscos de 2-5 px com cabeça branca e cauda #3fb8ff, em espiral entrando para o centro (quadros 9-10)"}], "paleta": [{"nome": "Azul profundo", "hex": "#1a6fd8"}, {"nome": "Azul", "hex": "#2f9cff"}, {"nome": "Ciano", "hex": "#6fd0ff"}, {"nome": "Ciano claro", "hex": "#c4f2ff"}, {"nome": "Halo", "hex": "#3fb8ff"}, {"nome": "Contorno", "hex": "#0c2c66"}, {"nome": "Núcleo", "hex": "#ffffff"}], "arquivo": "sprites/rsg_esfera.png", "fw": 64, "fh": 64, "cols": 10, "quadros": ["crescendo 3 px", "crescendo 6 px", "crescendo 9 px", "crescendo 13 px (cheia)", "rotação 1", "rotação 2", "rotação 3", "rotação 4", "partículas sugadas 1", "partículas sugadas 2"], "anims": [{"nome": "carga", "quadros": [0, 1, 2, 3], "dur": [200, 200, 200, 200], "loop": false}, {"nome": "girando", "quadros": [4, 5, 6, 7], "dur": [60, 60, 60, 60], "loop": true}, {"nome": "partículas", "quadros": [8, 9], "dur": [90, 90], "loop": true}], "uso": "Pivô no centro do quadro (32,32) preso à palma do herói, camada de efeitos acima do herói. O quadro de crescimento é escolhido pela carga (0,3-1,2 s); as partículas sobrepõem a esfera durante a carga. Rotação extra e escala fina são em tempo real. Desligado (RSG-02): usar só o corpo sem anéis (quadro 0-3 escalado).", "w": 640, "h": 64}, {"id": "rsg_gigante", "nome": "Esfera gigante", "categoria": "Especial: Rasengan", "mecanica": "Rasengan (RSG-07 Giant orb, RSG-02)", "conceito": "Quando a carga passa de 2,4 s a esfera incha até 33 px de diâmetro e vira uma bola de vento comprimido maior que a cabeça do herói. As espirais internas ficam grossas (2 px) e visíveis, com contra-faixas azul-escuras dando volume, e os três anéis viram faixas largas que giram em 3D em volta. Faíscas brancas e ciano escapam da superfície e um halo forte em degraus ilumina o chão em volta. É o mesmo desenho da esfera normal, só que com mais detalhe e peso.", "partes": [{"parte": "Halo", "descricao": "glow ciano raio ~50 px em degraus + anel externo de pontos claros"}, {"parte": "Corpo", "descricao": "disco de 33 px em 6 faixas (#1a6fd8 → branco) deslocadas para cima-esquerda, contorno #0c2c66, brilho especular branco 3×2 em cima-esquerda e reflexo ciano embaixo-direita"}, {"parte": "Espirais", "descricao": "3 braços brancos de 2 px afinando para fora, 3 contra-braços #1a5fc8, giram 22° por quadro"}, {"parte": "Anéis", "descricao": "3 anéis de raio ~27 px, 2 px de espessura, metade de trás escura atrás do corpo, metade da frente clara com núcleo branco"}, {"parte": "Faíscas", "descricao": "6-8 cruzes e riscos brancos/ciano de 3-7 px ao redor, mudam a cada quadro"}], "paleta": [{"nome": "Azul profundo", "hex": "#1a6fd8"}, {"nome": "Ciano", "hex": "#6fd0ff"}, {"nome": "Ciano claro", "hex": "#c4f2ff"}, {"nome": "Anel de trás", "hex": "#2a8fe0"}, {"nome": "Anel da frente", "hex": "#d8fbff"}, {"nome": "Contorno", "hex": "#0c2c66"}], "arquivo": "sprites/rsg_gigante.png", "fw": 128, "fh": 128, "cols": 4, "quadros": ["rotação 1", "rotação 2", "rotação 3", "rotação 4"], "anims": [{"nome": "girando", "quadros": [0, 1, 2, 3], "dur": [70, 70, 70, 70], "loop": true}], "uso": "Pivô (64,64) na mão/à frente do herói; aparece com 'ding' e tremor (tempo real). Pode crescer do quadro cheio de rsg_esfera com escala em tempo real antes de trocar para este sprite.", "w": 512, "h": 128}, {"id": "rsg_rush", "nome": "Imagem residual e poeira do avanço", "categoria": "Especial: Rasengan", "mecanica": "Rasengan (RSG-03 Rush, RSG-09)", "conceito": "Durante o avanço o herói deixa para trás cópias de si mesmo em ciano translúcido, a cada 25 ms, que somem rapidamente. A silhueta é genérica (corredor inclinado para frente, braço esticado segurando a esfera, pernas em passada), para servir com qualquer roupa. Tem linhas horizontais de varredura (uma linha sim, uma mais fraca) e borda clara, como um rastro de velocidade. Nos pés levanta poeira marrom-acinzentada do asfalto do Marco Zero.", "partes": [{"parte": "Silhueta", "descricao": "corredor de ~54 px de altura virado para a direita, corpo inclinado 15°, preenchimento #4ad8ff alpha 110 com linhas alternadas alpha 60, borda 1 px #bff4ff alpha 200, núcleo branco na mão da frente"}, {"parte": "Riscos de velocidade", "descricao": "3-5 riscos horizontais ciano de 6-14 px atrás da silhueta"}, {"parte": "Poeira", "descricao": "nuvens de 4-9 px #9c8a70 com contorno #3a3024, sombreadas, + pedrinhas de 1 px; quadro 2 mais aberta e baixa"}], "paleta": [{"nome": "Ciano residual", "hex": "#4ad8ff"}, {"nome": "Borda", "hex": "#bff4ff"}, {"nome": "Poeira", "hex": "#9c8a70"}, {"nome": "Poeira escura", "hex": "#6e6250"}], "arquivo": "sprites/rsg_rush.png", "fw": 64, "fh": 64, "cols": 4, "quadros": ["imagem residual 1", "imagem residual 2", "poeira dos pés 1", "poeira dos pés 2"], "anims": [{"nome": "residual", "quadros": [0, 1], "dur": [50, 50], "loop": true}, {"nome": "poeira", "quadros": [2, 3], "dur": [90, 120], "loop": false}], "uso": "Imagem residual: pivô nos pés (32,60), espelhar em tempo real conforme a direção, alpha cai a 0 em ~150 ms (tempo real). Com 'reduzir flashes' não desenhar. Poeira: pivô (32,58) nos pés, camada do chão.", "w": 256, "h": 64}, {"id": "rsg_grind", "nome": "Faíscas da trituração e explosão final", "categoria": "Especial: Rasengan", "mecanica": "Rasengan (RSG-04 Grind, RSG-06 Explosão final)", "conceito": "Quando a esfera encosta num zumbi ela tritura como um esmeril: um leque de faíscas brancas, ciano e algumas laranja (atrito com o corpo e as roupas) espirra para a frente a partir do ponto de contato, com uma estrela de impacto no centro. No fim a esfera estoura: um flash branco, uma bola de vento ciano que se abre, um anel de choque achatado em perspectiva que corre pelo chão até ~42 px e se quebra em fragmentos, poeira e fiapos de fumaça.", "partes": [{"parte": "Leque de faíscas", "descricao": "14-20 riscos de 3-14 px num leque de ~110° para a direita, cabeça branca, corpo #8fe8ff, cauda #2f9cff; 20% laranja #ffb347; estrela de impacto branca de 7 px com borda ciano em (40,64)"}, {"parte": "Flash", "descricao": "quadro 4: disco branco r=14 com halo ciano r=30 em degraus"}, {"parte": "Bola de vento", "descricao": "quadro 5: disco em faixas #2f9cff → branco r=26 com 4 braços de espiral abrindo"}, {"parte": "Anel de choque", "descricao": "elipse (ry = 0,55 rx) com 3 camadas: halo #3fb8ff alpha 90, corpo #8fe8ff, fio branco; rx 34 → 46 → 58; no último quadro quebrado em arcos"}, {"parte": "Detritos", "descricao": "pedrinhas cinza #6b6a66 e poeira #9c8a70 voando nos quadros 6-7, fumaça #5a5868"}], "paleta": [{"nome": "Faísca", "hex": "#8fe8ff"}, {"nome": "Faísca quente", "hex": "#ffb347"}, {"nome": "Azul", "hex": "#2f9cff"}, {"nome": "Halo", "hex": "#3fb8ff"}, {"nome": "Pedra", "hex": "#6b6a66"}, {"nome": "Fumaça", "hex": "#5a5868"}], "arquivo": "sprites/rsg_grind.png", "fw": 128, "fh": 128, "cols": 7, "quadros": ["faíscas 1", "faíscas 2", "faíscas 3", "explosão flash", "explosão bola", "explosão anel", "explosão anel quebrado"], "anims": [{"nome": "triturando", "quadros": [0, 1, 2], "dur": [70, 70, 70], "loop": true}, {"nome": "explosão", "quadros": [3, 4, 5, 6], "dur": [50, 80, 100, 140], "loop": false}], "uso": "Faíscas: pivô no ponto de contato (40,64), girar na direção do avanço em tempo real. Explosão: pivô no centro (64,64) no ponto final; para a gigante escalar 2,2× em tempo real (raio 95). 'Reduzir flashes' pula o quadro 3.", "w": 896, "h": 128}, {"id": "rsg_cicatriz", "nome": "Marca em espiral e cratera", "categoria": "Especial: Rasengan", "mecanica": "Rasengan (RSG-05 Scar)", "conceito": "O vento comprimido raspa o asfalto e deixa uma marca de redemoinho no chão por onde a esfera passou, e no ponto final a trituração cava uma cratera rasa com sulcos em espiral, borda de cascalho e rachaduras. Logo que nasce, os sulcos brilham ciano; em 1,5 s viram fuligem preta-acinzentada e com o tempo esmaecem até 30%. Vista de cima em 3/4, as espirais são achatadas (elipses).", "partes": [{"parte": "Marca de avanço", "descricao": "espiral de 2,5 voltas ~70×38 px, sulco de 1-3 px #1c1a22 com borda clara de asfalto raspado #6a6672, e mancha de fuligem #2a2228 alpha 120 por baixo; brilhando: sulco ciano #6fd0ff com núcleo branco e halo #3fb8ff"}, {"parte": "Cratera", "descricao": "elipse ~84×46 px: fundo #26222c, parede de cima escura e de baixo-direita mais clara (luz da lua), 3 sulcos em espiral, borda de cascalho com 14-20 pedrinhas #5a5662/#77736e sombreadas, 6 rachaduras pretas radiais de 6-14 px"}, {"parte": "Estados", "descricao": "brilhando (azul), fuligem (frio), esmaecida (fuligem com alpha 30%)"}], "paleta": [{"nome": "Sulco", "hex": "#1c1a22"}, {"nome": "Asfalto raspado", "hex": "#6a6672"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Cascalho", "hex": "#5a5662"}, {"nome": "Brilho ciano", "hex": "#6fd0ff"}], "arquivo": "sprites/rsg_cicatriz.png", "fw": 128, "fh": 96, "cols": 6, "quadros": ["marca brilhando", "marca fuligem", "marca esmaecida 30%", "cratera brilhando", "cratera fuligem", "cratera esmaecida 30%"], "uso": "Decalque de chão (camada abaixo de tudo), pivô no centro (64,48). Marca carimbada a cada ~40 px do avanço, girada na direção (tempo real). Brilho → fuligem em 1,5 s (cross-fade em tempo real entre quadros 0→1 / 3→4), depois alpha até 30% em 60 s (quadros 2/5 de referência).", "w": 768, "h": 96}, {"id": "gts_aura", "nome": "Aura de carga do corte", "categoria": "Especial: Getsuga", "mecanica": "Getsuga (GTS-01 Charge, GTS-02)", "conceito": "Enquanto o herói segura, uma aura em labaredas vermelha e preta sobe do chão e envolve o corpo, com uma língua comprida subindo pela lâmina erguida atrás do ombro. A camada de fora é quase preta (fumaça de sangue), a do meio vermelho-lua e a borda de dentro vermelho claro, como fogo frio. Partículas escuras com borda vermelha chegam de fora e são sugadas, e faíscas vermelhas com cabeça branca sobem. Pulsa em 3 tempos (encolhe, normal, estoura).", "partes": [{"parte": "Labareda do corpo", "descricao": "silhueta ~56×88 px com 6-7 línguas pontudas no topo, base elíptica no chão (gy 112); fora #1a0a12 alpha 200, faixa #c8323a 3 px, borda interna #ff5a5a 1 px, miolo vazio com véu #c8323a alpha 50"}, {"parte": "Língua da lâmina", "descricao": "chama diagonal de ~10×46 px saindo do ombro direito para cima-esquerda, mesmas camadas"}, {"parte": "Partículas escuras", "descricao": "8-10 quadradinhos 2×2 #120a10 com 1 px #c8323a, a 30-55 px do centro, indo para dentro"}, {"parte": "Faíscas", "descricao": "6-8 riscos verticais de 2-4 px #ff5a5a com cabeça branca subindo"}], "paleta": [{"nome": "Fumaça de sangue", "hex": "#1a0a12"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Vermelho claro", "hex": "#ff5a5a"}, {"nome": "Vinho", "hex": "#7a1020"}, {"nome": "Núcleo", "hex": "#ffe8e0"}], "arquivo": "sprites/gts_aura.png", "fw": 128, "fh": 128, "cols": 3, "quadros": ["pulso 1 (encolhida)", "pulso 2", "pulso 3 (estourando)"], "anims": [{"nome": "carga", "quadros": [0, 1, 2, 1], "dur": [90, 90, 90, 90], "loop": true}], "uso": "Pivô nos pés (64,112), mesma âncora do herói; a parte de fora vai atrás do herói e o véu é leve, então pode ir na camada de efeitos acima também. Escala com a carga em tempo real; vibração da tela é do jogo.", "w": 384, "h": 128}, {"id": "gts_lua", "nome": "Lua crescente (onda do corte)", "categoria": "Especial: Getsuga", "mecanica": "Getsuga (GTS-04 Onda, GTS-02 Sharpen)", "conceito": "A onda do corte é uma lua crescente de energia preta voando para a direita, com o lado convexo na frente. A borda tem uma faixa vermelho-lua e, por dentro dela, um fio branco finíssimo que dá o gume; o miolo é preto com veios vinho correndo. Atrás deixa um rastro vermelho em faixas horizontais que somem em degraus, com fiapos pretos. Sem o afiar ela sai gorda e de pontas rombudas; afiada (sharpen) fica fina e de pontas compridas como foice.", "partes": [{"parte": "Crescente", "descricao": "círculo r=40 menos círculo deslocado; normal: espessura ~20 px no meio; afinada: ~11 px com pontas alongadas. Miolo #120a10 com veios #4a0e1a"}, {"parte": "Borda", "descricao": "faixa #c8323a 2-3 px no lado convexo, fio branco #fff0ea 1 px por dentro dela, contorno #3a0610; borda côncava fina #7a1020"}, {"parte": "Halo", "descricao": "2 degraus: #ff3a40 alpha 110 (2 px), #7a1020 alpha 60 (4 px)"}, {"parte": "Rastro", "descricao": "8-12 faixas horizontais de 1-3 px saindo das costas para a esquerda, 20-60 px, #ff3a40 em 3 degraus de alpha; fiapos #1a0a12; faíscas vermelhas"}], "paleta": [{"nome": "Preto da lua", "hex": "#120a10"}, {"nome": "Veio", "hex": "#4a0e1a"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Rastro", "hex": "#ff3a40"}, {"nome": "Fio branco", "hex": "#fff0ea"}], "arquivo": "sprites/gts_lua.png", "fw": 128, "fh": 128, "cols": 6, "quadros": ["voo 1", "voo 2", "voo 3", "afinada voo 1", "afinada voo 2", "afinada voo 3"], "anims": [{"nome": "voo", "quadros": [0, 1, 2], "dur": [60, 60, 60], "loop": true}, {"nome": "voo afinada", "quadros": [3, 4, 5], "dur": [60, 60, 60], "loop": true}], "uso": "Pivô no centro da lua (72,64); girar em tempo real para a direção da mira (desenhada indo para a direita). Camada de efeitos, blend aditivo opcional só no rastro. Hitbox: arco da crescente.", "w": 768, "h": 128}, {"id": "gts_lua_gigante", "nome": "Lua gigante", "categoria": "Especial: Getsuga", "mecanica": "Getsuga (GTS-07 Giant moon)", "conceito": "A carga máxima solta uma lua crescente de raio 64 px que parece cortar a própria noite. Atrás dela aparece um halo de lua cheia pálida, um disco creme-acinzentado translúcido com crateras, que lembra a lua do céu antes de ficar vermelha. A crescente tem o mesmo desenho da normal mas com borda mais grossa, fio branco duplo, veios vermelhos e faíscas soltas; o rastro é largo e pesado. Escurece a tela (tempo real) e faz tremer.", "partes": [{"parte": "Halo de lua cheia", "descricao": "disco r=72 #e8dccc alpha 60 + glow em degraus, 5 crateras #c8bca8 alpha 70, borda 1 px #f4ece0 alpha 110"}, {"parte": "Crescente", "descricao": "r=64, espessura ~30 px, miolo #120a10 com veios #4a0e1a e #7a1020, faixa vermelha 4 px, fio branco 1 px + segundo fio pontilhado"}, {"parte": "Rastro", "descricao": "14-18 faixas de 2-4 px até 90 px para a esquerda, 3 degraus de alpha, fiapos pretos, brasas"}], "paleta": [{"nome": "Lua pálida", "hex": "#e8dccc"}, {"nome": "Cratera", "hex": "#c8bca8"}, {"nome": "Preto da lua", "hex": "#120a10"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Fio branco", "hex": "#fff0ea"}], "arquivo": "sprites/gts_lua_gigante.png", "fw": 256, "fh": 256, "cols": 3, "quadros": ["voo 1", "voo 2", "voo 3"], "anims": [{"nome": "voo", "quadros": [0, 1, 2], "dur": [70, 70, 70], "loop": true}], "uso": "Pivô no centro da crescente (140,128); girar para a mira em tempo real. O halo pálido pode ser desenhado com alpha reduzido sobre o escurecimento de tela.", "w": 768, "h": 256}, {"id": "gts_impacto", "nome": "Impact frame e linha de corte", "categoria": "Especial: Getsuga", "mecanica": "Getsuga (GTS-03 Impact frame, GTS-05 Split it, GTS-09)", "conceito": "No instante do corte a tela congela: uma faixa preta diagonal com borda branca atravessa o quadro e linhas de velocidade radiais (pretas e brancas) apontam para o centro, como um quadro de quadrinho. O segundo quadro inverte os tons (faixa branca com borda preta) para o efeito de negativo. Depois, sobre cada zumbi partido, fica a linha branca de corte diagonal com halo vermelho que afina, fica pontilhada e some.", "partes": [{"parte": "Faixa diagonal", "descricao": "faixa de 22 px a 30° atravessando o quadro, #0a0608 com bordas brancas de 2 px (quadro 2 invertido: #fff8f0 com bordas pretas)"}, {"parte": "Linhas de velocidade", "descricao": "28-36 cunhas finas de 1-2 px saindo de r=26 até a borda, alternando branco/preto"}, {"parte": "Linha de corte", "descricao": "diagonal de ~80 px a -35°: 3 px branco + halo #ff5a5a e #c8323a (quadro 3); 1 px branco + halo fino (quadro 4); pontilhada com 3 faíscas (quadro 5)"}], "paleta": [{"nome": "Preto", "hex": "#0a0608"}, {"nome": "Branco", "hex": "#fff8f0"}, {"nome": "Halo", "hex": "#ff5a5a"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}], "arquivo": "sprites/gts_impacto.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["impact frame", "impact frame negativo", "corte cheio", "corte afinando", "corte sumindo"], "anims": [{"nome": "impact", "quadros": [0, 1], "dur": [45, 45], "loop": false}, {"nome": "split", "quadros": [2, 3, 4], "dur": [160, 170, 170], "loop": false}], "uso": "Impact frame: escalar para cobrir a tela inteira (NEAREST) no congelamento de 0,09 s; o negativo da imagem é pós-processo do jogo e é desligado em 'reduzir flashes' (usar só quadro 0). Linha de corte: pivô (64,64) no centro do zumbi, girar para o ângulo do corte; as metades do zumbi são o sprite dele recortado em tempo real.", "w": 640, "h": 128}, {"id": "gts_sulco", "nome": "Sulco do corte e corte na parede", "categoria": "Especial: Getsuga", "mecanica": "Getsuga (GTS-06 Scar, GTS-07)", "conceito": "A lua rasga o asfalto e deixa um sulco escuro e reto com bordas incandescentes vermelhas, cascalho levantado nos lados e fumacinha. Em 1,6 s a borda apaga (vermelho vinho, depois fuligem) e em 60 s o sulco esmaece até 30%. A lua gigante deixa um sulco 3× mais largo, com paredes visíveis e brasas. Na parede do fundo fica um corte horizontal fundo, com reboco lascado e rachaduras.", "partes": [{"parte": "Sulco", "descricao": "tira horizontal de 116×6 px afinando nas pontas, fundo #120c10, parede de cima #2e2228, lábio de baixo iluminado #5a5262; borda #ff5a5a/#c8323a com pontos #ffd0a0 (aceso)"}, {"parte": "Sulco largo", "descricao": "116×18 px, mesmas cores, 2 paredes internas, brasas laranja, pedrinhas maiores"}, {"parte": "Cascalho", "descricao": "pedrinhas 1-3 px #5a5662 e #77736e sombreadas nas bordas"}, {"parte": "Corte na parede", "descricao": "fenda 100×4 px #0a0608 com bordas vermelhas, reboco lascado #8e8a84 em volta, 6 rachaduras pretas"}, {"parte": "Estados", "descricao": "aceso (halo vermelho em degraus + brasas), apagando (borda #7a1020, fumaça), esmaecido (frio a 30%)"}], "paleta": [{"nome": "Fundo do sulco", "hex": "#120c10"}, {"nome": "Parede", "hex": "#2e2228"}, {"nome": "Brasa", "hex": "#ff5a5a"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Vinho", "hex": "#7a1020"}, {"nome": "Reboco", "hex": "#8e8a84"}], "arquivo": "sprites/gts_sulco.png", "fw": 128, "fh": 64, "cols": 8, "quadros": ["sulco aceso", "sulco apagando", "sulco esmaecido 30%", "sulco largo aceso", "sulco largo apagando", "sulco largo esmaecido 30%", "corte na parede aceso", "corte na parede frio"], "uso": "Decalque de chão (camada abaixo dos personagens), pivô (64,32), girado na direção da onda e repetido/esticado ao longo do caminho em tempo real. Apagar: cross-fade 0→1 em 1,6 s, depois alpha até 30%. Corte na parede: na parede do fundo onde a onda bateu.", "w": 1024, "h": 64}, {"id": "chd_mao", "nome": "Crepitar na mão", "categoria": "Especial: Chidori", "mecanica": "Chidori (CHD-01 Crackle)", "conceito": "Uma esfera branco-azulada de eletricidade cresce na mão do herói de 5 para 14 px, cuspindo arcos de raio em zigue-zague para todos os lados, para o braço e para o chão. Os arcos mudam a cada quadro (4 formas) para dar o crepitar nervoso. O núcleo é branco puro, o corpo azul claro e o halo azul em degraus. Na carga cheia um flash em cruz e um anel marcam o 'ding'.", "partes": [{"parte": "Esfera", "descricao": "disco 5 → 9 → 14 px: núcleo #ffffff, corpo #bfe4ff, borda #4a8fe0, contorno #10204a; halo #4a8fe0 em degraus até 2,5×"}, {"parte": "Arcos", "descricao": "5-8 zigue-zagues de 8-26 px com 1 ramo, núcleo branco 1 px, corpo #8fd0ff, halo #3f7fff alpha 80; pelo menos 1 apontando para baixo"}, {"parte": "Faíscas", "descricao": "pontos e cruzes brancas de 1-3 px"}, {"parte": "Carga cheia", "descricao": "cruz de luz branca 4 pontas de 24 px + anel 1 px #bfe4ff r=20"}], "paleta": [{"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Azul claro", "hex": "#bfe4ff"}, {"nome": "Corpo do arco", "hex": "#8fd0ff"}, {"nome": "Azul raro", "hex": "#4a8fe0"}, {"nome": "Halo", "hex": "#3f7fff"}, {"nome": "Contorno", "hex": "#10204a"}], "arquivo": "sprites/chd_mao.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["crescendo 5 px", "crescendo 9 px", "crescendo 14 px", "arcos 1", "arcos 2", "arcos 3", "arcos 4", "carga cheia"], "anims": [{"nome": "carga", "quadros": [0, 1, 2], "dur": [300, 300, 300], "loop": false}, {"nome": "crepitar", "quadros": [3, 4, 5, 6], "dur": [50, 50, 50, 50], "loop": true}, {"nome": "cheia", "quadros": [7], "dur": [120], "loop": false}], "uso": "Pivô (32,32) na mão do herói, camada de efeitos. Escolher quadro de crescimento pela carga e alternar arcos aleatoriamente; com 'reduzir flashes' trocar menos vezes os arcos e pular o quadro 7.", "w": 512, "h": 64}, {"id": "chd_rastro", "nome": "Rastro de raio do dash", "categoria": "Especial: Chidori", "mecanica": "Chidori (CHD-03 Trail, CHD-05 Afterglow)", "conceito": "Segmento horizontal de raio que o jogo repete ao longo da linha do dash. Um zigue-zague branco de 1-2 px com corpo azul e halo azul de 10 px de altura, com um ou dois ramos curtos. As pontas ficam na mesma altura (y=16) para encaixar lado a lado sem emenda. Depois do dash o rastro fica brilhando: o núcleo vira azul, o halo enfraquece e sobram faíscas soltas, até ficar só um traço tracejado.", "partes": [{"parte": "Raio", "descricao": "zigue-zague de 128 px com picos de ±6 px, núcleo #ffffff 2 px, corpo #8fd0ff 1 px de cada lado"}, {"parte": "Halo", "descricao": "#3f7fff em 2 degraus (alpha 110 e 50), altura total 10 px"}, {"parte": "Ramos", "descricao": "1-2 ramos de 6-12 px, 1 px branco/azul"}, {"parte": "Afterglow", "descricao": "quadro 4: núcleo #8fd0ff, halo alpha 60, 4 faíscas; quadro 5: traço #4a8fe0 tracejado alpha 120 + 2 faíscas"}], "paleta": [{"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Corpo", "hex": "#8fd0ff"}, {"nome": "Halo", "hex": "#3f7fff"}, {"nome": "Azul", "hex": "#4a8fe0"}], "arquivo": "sprites/chd_rastro.png", "fw": 128, "fh": 32, "cols": 5, "quadros": ["raio 1", "raio 2", "raio 3", "afterglow 1", "afterglow 2"], "anims": [{"nome": "crepitando", "quadros": [0, 1, 2], "dur": [40, 40, 40], "loop": true}, {"nome": "esmaecendo", "quadros": [3, 4], "dur": [700, 1100], "loop": false}], "uso": "Tileável na horizontal: pivô na ponta esquerda (0,16), girar para o ângulo do dash e repetir até cobrir a distância. Alpha cai em 1,8 s (tempo real). Desligado: sem rastro.", "w": 640, "h": 32}, {"id": "chd_trovao", "nome": "Trovão do céu", "categoria": "Especial: Chidori", "mecanica": "Chidori (CHD-06 Thunder, CHD-08)", "conceito": "0,3 s depois do dash um raio cai do topo da tela no ponto final e em cada zumbi perfurado. É um raio vertical em 3 camadas: halo azul largo, corpo azul claro e núcleo branco, em zigue-zague com ramos laterais. Três quadros mostram o golpe cheio, um re-golpe com outra forma e o raio afinando. Ao tocar o chão sai um flash branco com estrela de faíscas, e fica uma marca de queimado preta com rachaduras e brasas azuis.", "partes": [{"parte": "Raio", "descricao": "de y=0 a y=178, zigue-zague de segmentos 8-14 px com desvio ±7 px; núcleo branco 3 px, corpo #8fd0ff, halo #3f7fff alpha 90 (±6 px) e #2a4fd0 alpha 45 (±10 px); 3-4 ramos de 10-24 px"}, {"parte": "Flash no chão", "descricao": "quadro 4: elipse branca 30×10 em y=180 com halo azul em degraus, 8 raios de faísca e pedrinhas voando"}, {"parte": "Marca de queimado", "descricao": "quadro 5: elipse #16121a 34×12 px com borda fuligem #2a2228, 7 rachaduras radiais, 4 brasas #8fd0ff e fumacinha #5a5868"}], "paleta": [{"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Corpo", "hex": "#8fd0ff"}, {"nome": "Halo", "hex": "#3f7fff"}, {"nome": "Halo externo", "hex": "#2a4fd0"}, {"nome": "Queimado", "hex": "#16121a"}, {"nome": "Fuligem", "hex": "#2a2228"}], "arquivo": "sprites/chd_trovao.png", "fw": 64, "fh": 192, "cols": 5, "quadros": ["raio 1", "raio 2 (re-golpe)", "raio 3 (afinando)", "flash no chão", "marca de queimado"], "anims": [{"nome": "trovão", "quadros": [0, 1, 0, 2, 3], "dur": [40, 40, 30, 60, 90], "loop": false}], "uso": "Pivô no ponto de impacto no chão (32,180); esticar verticalmente em tempo real até o topo da tela. Quadro 4 é decalque de chão que fica alguns segundos. 'Reduzir flashes' pula o quadro 3 e reduz alpha do halo.", "w": 320, "h": 192}, {"id": "chd_eletrificado", "nome": "Eletrificado, halo do herói e acerto", "categoria": "Especial: Chidori", "mecanica": "Chidori (CHD-04 Pierce, CHD-05 Afterglow)", "conceito": "Overlay posto sobre o zumbi atingido: arcos de raio curtos que correm colados ao contorno de um corpo humano (cabeça, ombros, braços, pernas), faíscas pulando e pequenos estalos azuis, em 3 formas diferentes para piscar. O herói depois do dash fica envolto num halo elétrico: um contorno crepitante oval em volta do corpo e um anel no chão. No acerto aparece um símbolo de raio grande, branco-azulado com contorno escuro, para ler de longe.", "partes": [{"parte": "Arcos no corpo", "descricao": "6-9 zigue-zagues de 8-20 px seguindo a silhueta de um zumbi de ~80 px (cabeça em (64,40), pés em y 112), núcleo branco, corpo #8fd0ff, halo #3f7fff"}, {"parte": "Faíscas", "descricao": "cruzes 3-5 px e pontos brancos/azuis ao redor"}, {"parte": "Halo do herói", "descricao": "oval 44×86 px de arcos tracejados #8fd0ff/branco + anel no chão elíptico 50×10 #3f7fff, 2 variações"}, {"parte": "Símbolo de acerto", "descricao": "raio em Z de ~26×40 px, #f4fbff com faixa #8fd0ff, contorno 1 px #10204a, sombra #2a4fd0 deslocada 2 px, 4 faíscas em volta"}], "paleta": [{"nome": "Núcleo", "hex": "#ffffff"}, {"nome": "Corpo", "hex": "#8fd0ff"}, {"nome": "Halo", "hex": "#3f7fff"}, {"nome": "Contorno", "hex": "#10204a"}, {"nome": "Sombra do símbolo", "hex": "#2a4fd0"}], "arquivo": "sprites/chd_eletrificado.png", "fw": 128, "fh": 128, "cols": 6, "quadros": ["eletrificado 1", "eletrificado 2", "eletrificado 3", "halo do herói 1", "halo do herói 2", "símbolo de acerto"], "anims": [{"nome": "eletrificado", "quadros": [0, 1, 2], "dur": [60, 60, 60], "loop": true}, {"nome": "halo", "quadros": [3, 4], "dur": [70, 70], "loop": true}], "uso": "Overlay com pivô nos pés (64,112), mesma âncora do zumbi/herói, camada de efeitos acima. O tremor e o piscar branco do zumbi são tempo real (tint 'flash'). Símbolo: pivô (64,40), sobe e some em 0,5 s.", "w": 768, "h": 128}]}, {"grupo": "fogueira", "titulo": "Fogueira", "ordem": 9, "resumo": "A fogueira é o prédio principal do abrigo (1×1, fixa no centro da grade, nunca destruída — INV-07). Aqui estão os 5 níveis na escada de materiais, os estados animados da chama, a máscara de luz quente, os itens de lenha/isqueiro e a obra de evolução.", "itens": [{"id": "fog_niveis", "nome": "Fogueira — níveis 1 a 5", "categoria": "Construção (prédio principal)", "mecanica": "Fogueira (FOG-01..08), Evolução (EVO-01, EVO-02), Abrigo (ABR-01, ABR-02), Invasão (INV-07)", "conceito": "A fogueira é o coração do abrigo no Marco Zero: é onde o herói cura, salva e de onde a luz quente afasta a noite da Lua de Sangue. Ela sobe a mesma escada de materiais das outras construções, então o jogador lê o nível de longe pelo material do anel: pedras soltas e sucata (N1), anel de tocos de madeira com bancos de tronco (N2), muro baixo de pedra com argamassa e caldeirão no tripé (N3), tijolo com faixa de metal rebitado, grelha de ferro e lampião aceso (N4) e pedra escura com acabamento dourado, runas vermelhas e fogo vermelho-lua (N5). A fogueira NUNCA é destruída: a linha de baixo mostra o estado danificado depois de uma invasão — fuligem, rachaduras, uma ou duas peças soltas caídas no chão, fumaça cinza e chama fraca, mas ainda acesa. O tamanho na grade não muda entre níveis (anel de ~68 px de largura centrado no tile).", "partes": [{"parte": "Anel / base", "descricao": "Elipse centrada em x=64, chão gy=148, raio externo 34×13 px, interno 26×9 px. Nos níveis 3-5 é um muro baixo (8 a 11 px de altura) com face frontal, topo e face interna de trás visível; nos níveis 1-2 são peças soltas (pedras 5-8 px / tocos 7×9 px) em volta da elipse. Peças de trás desenhadas antes do fogo e peças da frente por cima da base da chama."}, {"parte": "Leito de carvão", "descricao": "Elipse escura #2a1a14 de 25×8 px no fundo do buraco com pontos de brasa #c8321e/#f07a1e/#ffc93a que pulsam (mais brilho com fogo maior)."}, {"parte": "Lenha", "descricao": "3 toras cruzadas (6 px de grossura, 26-30 px de comprimento), casca #6b4426 com veios escuros, ponta cortada #c8955a com anéis #8a5a30, pontas de cima carbonizadas #2a1a12 com rachas acesas."}, {"parte": "Chama", "descricao": "5 línguas em forma de gota, 4 camadas nítidas: vermelha (com contorno vinho), laranja (78%), amarela (52%) e branca (28%, só nas 3 centrais). Chama média = 34 px na linha de cima; danificada = 16 px. N5 usa paleta vermelho-lua (#8a0f1e, #c8323a, #ff5a5a, #ffd0d0)."}, {"parte": "N1 extras", "descricao": "Chapas de sucata #6b6a66 com ferrugem #8a4e2e encostadas, grelha de arame sobre duas pedras e uma lata enferrujada esquentando nela."}, {"parte": "N2 extras", "descricao": "Anel de 12 tocos de madeira em pé (#9a6a3c/#7d5430, topo com anéis), dois bancos de tronco deitados (18×8 px) à esquerda e à direita."}, {"parte": "N3 extras", "descricao": "Muro de blocos #8e8a84/#77736e com argamassa #b8b0a0 em 2 fiadas; tripé de 3 varas e caldeirão de ferro preto (12×9 px) pendurado por corrente sobre a chama."}, {"parte": "N4 extras", "descricao": "Tijolo #a5432e/#86351f com rejunte #c9b8a0 em 3 fiadas, faixa de metal #7d848c com rebites #c9ced4 a cada 6 px no topo; grelha de barras de metal rebitada passando na frente da chama; poste de ferro à direita com lampião aceso (vidro #ffd36a com brilho)."}, {"parte": "N5 extras", "descricao": "Pedra escura #2e2836/#3c3446, frisos dourados #f2c230/#b8861a no topo e na base, 5 runas vermelhas #c8323a com brilho #ff5a5a na face frontal, 2 chifres dourados atrás, brilho vermelho em volta."}, {"parte": "Dano", "descricao": "Manchas de fuligem #2a2228, rachaduras pretas em zigue-zague, uma peça caída no chão à esquerda (pedra / toco / bloco / tijolo / pedra escura com friso), buraco escuro no muro, 2-3 nuvens de fumaça cinza, chama fraca (16 px)."}], "paleta": [{"nome": "Chama vermelha", "hex": "#c8321e"}, {"nome": "Chama laranja", "hex": "#f07a1e"}, {"nome": "Chama amarela", "hex": "#ffc93a"}, {"nome": "Chama branca", "hex": "#fff4c8"}, {"nome": "Carvão", "hex": "#2a1a14"}, {"nome": "Casca da lenha", "hex": "#6b4426"}, {"nome": "Cerne da lenha", "hex": "#c8955a"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Tábua/toco", "hex": "#9a6a3c"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Brilho de runa", "hex": "#ff5a5a"}, {"nome": "Fuligem", "hex": "#2a2228"}], "arquivo": "sprites/fog_niveis.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 acesa", "N2 acesa", "N3 acesa", "N4 acesa", "N5 acesa", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada"], "uso": "Pivô no centro da base (x=64, gy=148). Camada de construções do abrigo, ordenada por y. Estes quadros mostram a chama média parada; no jogo a chama animada vem de fog_chama (ou é desenhada em tempo real por FOG-02) por cima do leito, e a luz de fog_luz é somada no mapa de luz. Não existe estado destruído (INV-07): depois da invasão ela fica danificada até reparar. O squash/stretch da obra pronta é transformação em tempo real.", "w": 640, "h": 320}, {"id": "fog_chama", "nome": "Fogueira — estados da chama (N2)", "categoria": "Construção (animação)", "mecanica": "Fogueira FOG-01 (acender), FOG-02 (shape), FOG-04 (brasas), FOG-06 (alimentar), FOG-07 (consumo)", "conceito": "Folha de animação da fogueira de referência (nível 2, anel de tocos) com todos os estados da chama, 4 quadros por estado. A chama tem 5 línguas em forma de gota com camadas vermelha, laranja, amarela e branca bem marcadas, que balançam e trocam de altura em frequências diferentes (os quadros fecham o ciclo). Brasas de 1-2 px sobem da chama apagando de amarelo para vermelho, e o leito de carvão pulsa. Ao alimentar, a labareda dobra de tamanho por um instante com flash quente e rajada de brasas; sem lenha vira brasa com fumaça fina e depois carvão cinza frio. O estado 'acendendo' segue o ritual FOG-01: duas faíscas do isqueiro ('tic') e na terceira o fogo pega com 'whoosh' e flash.", "partes": [{"parte": "Base N2", "descricao": "Mesma base de fog_niveis N2 (anel de tocos, bancos de tronco), pivô x=64, gy=148."}, {"parte": "Chama baixa", "descricao": "14 px de altura, 18 px de largura, só vermelho/laranja/amarelo, lenha bem visível, brasas raras (3)."}, {"parte": "Chama média", "descricao": "34 px de altura, 26 px de largura, 4 camadas, 7 brasas subindo."}, {"parte": "Chama alta", "descricao": "58 px de altura, 32 px de largura, núcleo branco grande, gotinhas de fogo soltas acima da ponta, 12 brasas."}, {"parte": "Labareda", "descricao": "Ao jogar lenha: quadros A (64 px + flash branco-amarelo em volta) e B (54 px), repetidos com variação, rajada de 20+ brasas."}, {"parte": "Brasa", "descricao": "Sem chama: lenha carbonizada com rachas laranja pulsando, leito vermelho, fio de fumaça cinza fina subindo e ondulando."}, {"parte": "Apagada", "descricao": "Carvão cinza #4a4448/#6a6468 e cinzas claras #8a8488, sem brilho; nos 2 primeiros quadros a última nuvem de fumaça sobe e some."}, {"parte": "Acendendo", "descricao": "Isqueiro vermelho (6×11 px) na beira esquerda do anel: faísca amarela estrelada (quadros 1-2), flash grande + chama curta 'whoosh' (quadro 3), chama subindo 20 px (quadro 4)."}], "paleta": [{"nome": "Chama vermelha", "hex": "#c8321e"}, {"nome": "Contorno da chama", "hex": "#5a1208"}, {"nome": "Chama laranja", "hex": "#f07a1e"}, {"nome": "Chama amarela", "hex": "#ffc93a"}, {"nome": "Chama branca", "hex": "#fff4c8"}, {"nome": "Brasa", "hex": "#ff7a1e"}, {"nome": "Carvão frio", "hex": "#4a4448"}, {"nome": "Cinza", "hex": "#8a8488"}, {"nome": "Fumaça", "hex": "#8a8494"}, {"nome": "Isqueiro", "hex": "#c8323a"}], "arquivo": "sprites/fog_chama.png", "fw": 128, "fh": 160, "cols": 4, "quadros": ["baixa 1", "baixa 2", "baixa 3", "baixa 4", "média 1", "média 2", "média 3", "média 4", "alta 1", "alta 2", "alta 3", "alta 4", "labareda A (flash)", "labareda B", "labareda A", "labareda B", "brasa 1", "brasa 2", "brasa 3", "brasa 4", "apagada (fumaça final 1)", "apagada (fumaça final 2)", "apagada fria", "apagada fria", "acendendo: faísca 1 (tic)", "acendendo: faísca 2 (tic)", "acendendo: pega fogo (whoosh + flash)", "acendendo: chama subindo"], "anims": [{"nome": "baixa", "quadros": [0, 1, 2, 3], "dur": [130, 130, 130, 130], "loop": true}, {"nome": "média", "quadros": [4, 5, 6, 7], "dur": [110, 110, 110, 110], "loop": true}, {"nome": "alta", "quadros": [8, 9, 10, 11], "dur": [90, 90, 90, 90], "loop": true}, {"nome": "labareda (alimentar)", "quadros": [12, 13, 14, 15, 8, 9], "dur": [60, 70, 60, 70, 90, 90], "loop": false}, {"nome": "brasa", "quadros": [16, 17, 18, 19], "dur": [220, 220, 220, 220], "loop": true}, {"nome": "apagando → fria", "quadros": [20, 21, 22], "dur": [300, 300, 800], "loop": false}, {"nome": "acendendo (FOG-01)", "quadros": [22, 24, 22, 25, 22, 26, 27, 4], "dur": [500, 120, 480, 120, 580, 120, 250, 200], "loop": false}], "uso": "Mesmo pivô de fog_niveis (x=64, gy=148). O jogo escolhe a linha pela porcentagem de lenha (baixa < 35%, média < 70%, alta acima), troca para labareda por 0,25 s ao alimentar (FOG-06), brasa em 0% e apagada após ~20 s (FOG-07). A subida rápida/descida lenta da altura (5/s e 1,4/s) é interpolação em tempo real entre as linhas; brasas extras e a rajada de 26 brasas podem ser partículas do motor usando fog_itens (brasas soltas). Para outros níveis o motor desenha só a chama (mesmas camadas) por cima da base de fog_niveis.", "w": 512, "h": 1120}, {"id": "fog_luz", "nome": "Luz da fogueira (light)", "categoria": "FX de luz", "mecanica": "Fogueira FOG-03 (Light), Dia e noite DN-04 (luzes), FOG-08 (abrigo iluminado)", "conceito": "Máscara de luz quente que a fogueira joga no chão do abrigo escuro: um halo elíptico (achatado pela câmera 3/4) em degraus nítidos de alpha, do núcleo amarelo-claro para laranja e um anel externo vermelho-escuro bem fraco, sem degradê liso para combinar com a pixel art. Há três raios prontos (pequeno, médio, grande) para chama baixa, média e alta, e um brilho vermelho de 26 px para a brasa sem chama. O jogo usa estes quadros como LUZ ADITIVA: são somados no mapa de luz antes de multiplicar a cena escura (DN-04) e um pouco do núcleo vai direto como brilho aditivo laranja. A oscilação de ±10% (3 senos) e o raio contínuo de 60 a 230 px são escala em tempo real.", "partes": [{"parte": "Luz pequena", "descricao": "Elipse 60×36 px de raio, 7 degraus de alpha (máx. ~200 no centro), núcleo #fff0b0 → #ffc060 → #ff8a30 → borda #c8421e."}, {"parte": "Luz média", "descricao": "Elipse 94×56 px de raio, mesmos degraus e cores."}, {"parte": "Luz grande", "descricao": "Elipse 124×74 px de raio (ocupa o quadro), mesmos degraus; escala até 230 px no jogo."}, {"parte": "Brasa", "descricao": "Círculo achatado de 26×16 px de raio, vermelho #c8321e → #ff5a2a no centro, 4 degraus, alpha máx. ~170."}], "paleta": [{"nome": "Núcleo", "hex": "#fff0b0"}, {"nome": "Amarelo quente", "hex": "#ffc060"}, {"nome": "Laranja", "hex": "#ff8a30"}, {"nome": "Borda", "hex": "#c8421e"}, {"nome": "Brasa", "hex": "#ff5a2a"}], "arquivo": "sprites/fog_luz.png", "fw": 256, "fh": 256, "cols": 4, "quadros": ["luz pequena (raio 60)", "luz média (raio 94)", "luz grande (raio 124)", "brilho da brasa (raio 26)"], "uso": "Centro do quadro (128,128) = centro do anel da fogueira no chão (x=64, y≈136 no quadro da fogueira). Blend ADITIVO (ou soma no lightmap antes de multiplicar a escuridão). Raio contínuo 60–230 px por escala em tempo real; oscilação ±10% com 3 senos; o herói projeta sombra para longe do fogo (calculado pelo motor). Sem fogo: nenhuma luz.", "w": 1024, "h": 256}, {"id": "fog_itens", "nome": "Itens da fogueira (lenha, isqueiro, brasas, fumaça)", "categoria": "Ícones e partículas", "mecanica": "Fogueira FOG-01 (isqueiro), FOG-04 (brasas, fumaça), FOG-06 (tora jogada), ABR-01 (cura e salva)", "conceito": "Peças pequenas usadas pelo motor em volta da fogueira e no HUD. A tora de lenha (casca escura com ponta cortada e anéis) gira no ar em 4 quadros quando o herói joga lenha em arco. A pilha de lenha é o ícone do estoque: toras empilhadas vistas pela ponta, amarradas com corda. O isqueiro de plástico vermelho com capa de metal tem três estados: fechado, faísca (tic) e chama acesa. Brasas soltas pulsam em 3 quadros e a nuvem de fumaça cinza cresce e se desfaz em 3 quadros. O ícone 'Salvar/curar' é uma fogueirinha com um + verde.", "partes": [{"parte": "Tora", "descricao": "36×11 px, casca #6b4426 com veios #4a2c18 e musgo, ponta #c8955a com 2 anéis #8a5a30, um galhinho cortado; gira 0°, 45°, 90°, 135°."}, {"parte": "Pilha de lenha", "descricao": "6 toras vistas pela ponta (círculos de 9-10 px) em pirâmide 3-2-1, corda #b59a62 amarrando, base de casca."}, {"parte": "Isqueiro", "descricao": "Corpo vermelho #c8323a 12×22 px, capa de metal #c9ced4 com furos, rodinha estriada, botão; faísca = estrela amarela; chama = gota 14 px com 3 camadas."}, {"parte": "Brasas soltas", "descricao": "5 pedaços de carvão #2a1a14 com rachas #f07a1e/#ffc93a e brilho em degraus; quadros variam a intensidade."}, {"parte": "Fumaça", "descricao": "Nuvem de 3-5 bolas #8a8494/#b0aab8 com contorno #4a4458; cresce, sobe e se abre em fiapos."}, {"parte": "Salvar/curar", "descricao": "Fogueirinha (2 toras cruzadas + chama 22 px) com + verde #6fdc7a no canto de cima."}], "paleta": [{"nome": "Casca", "hex": "#6b4426"}, {"nome": "Cerne", "hex": "#c8955a"}, {"nome": "Anel", "hex": "#8a5a30"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Isqueiro", "hex": "#c8323a"}, {"nome": "Metal", "hex": "#c9ced4"}, {"nome": "Carvão", "hex": "#2a1a14"}, {"nome": "Brasa", "hex": "#f07a1e"}, {"nome": "Fumaça", "hex": "#8a8494"}, {"nome": "Cura", "hex": "#6fdc7a"}], "arquivo": "sprites/fog_itens.png", "fw": 64, "fh": 64, "cols": 5, "quadros": ["tora girando 1", "tora girando 2", "tora girando 3", "tora girando 4", "pilha de lenha", "isqueiro fechado", "isqueiro faísca", "isqueiro aceso", "brasas 1", "brasas 2", "brasas 3", "fumaça 1", "fumaça 2", "fumaça 3", "ícone salvar/curar"], "anims": [{"nome": "tora girando", "quadros": [0, 1, 2, 3], "dur": [70, 70, 70, 70], "loop": true}, {"nome": "isqueiro", "quadros": [5, 6, 5, 6, 7], "dur": [300, 100, 300, 100, 400], "loop": false}, {"nome": "brasas", "quadros": [8, 9, 10, 9], "dur": [180, 180, 180, 180], "loop": true}, {"nome": "fumaça", "quadros": [11, 12, 13], "dur": [200, 250, 300], "loop": false}], "uso": "Centro do quadro como pivô. A tora segue um arco (posição em tempo real) da mão do herói até o fogo. Isqueiro fica na mão do herói durante FOG-01. Brasas e fumaça são partículas (subida, balanço e fade em tempo real). Pilha de lenha e salvar/curar são ícones de HUD/estoque.", "w": 320, "h": 192}, {"id": "fog_obra", "nome": "Fogueira em obra", "categoria": "Construção (obra de evolução)", "mecanica": "Evolução EVO-06, EVO-07 (visual da obra), EVO-08 (obra pronta)", "conceito": "A fogueira sendo melhorada do nível 2 para o 3: o anel de tocos ainda queima baixo (a construção continua funcionando no nível atual, EVO-06) enquanto blocos de pedra novos são assentados em volta. Um andaime improvisado de varas amarradas com corda, com uma tábua por cima, cerca a fogueira; um martelo bate num bloco com faíscas e poeira em 3 quadros. O último quadro é 'obra pronta': a fogueira nível 3 inteira, com um brilho branco atravessando e estrelas douradas saindo. A barra de tempo com contagem, o texto 'Nível N!' e o pulo (squash/stretch) são feitos pelo motor.", "partes": [{"parte": "Andaime", "descricao": "2 varas verticais (#8a6a42, 4 px) de y=70 até o chão em x=18 e x=110, travessas em y=86 e y=118, diagonal, amarras de corda #b59a62, tábua #9a6a3c em cima com pregos."}, {"parte": "Obra", "descricao": "Base N2 com chama baixa; 5 blocos de pedra #8e8a84 já assentados na frente com argamassa fresca #b8b0a0, pilha de 3 blocos e balde de argamassa à direita."}, {"parte": "Martelo", "descricao": "Cabo #9a6a3c 16 px, cabeça de ferro #7d848c 8×5 px; levantado (-70°), batendo (0°) com estrela de impacto e faíscas amarelas, voltando (-30°) com poeira."}, {"parte": "Obra pronta", "descricao": "Fogueira N3 completa, faixa diagonal de brilho branco, 4 estrelas douradas #f2c230 e brilhos."}], "paleta": [{"nome": "Vara", "hex": "#8a6a42"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Ferro", "hex": "#7d848c"}, {"nome": "Faísca", "hex": "#fff6c8"}, {"nome": "Estrela", "hex": "#f2c230"}], "arquivo": "sprites/fog_obra.png", "fw": 128, "fh": 160, "cols": 4, "quadros": ["obra: martelo levantado", "obra: martelo batendo (faíscas)", "obra: martelo voltando (poeira)", "obra pronta (brilho e estrelas)"], "anims": [{"nome": "marteladas", "quadros": [0, 1, 2], "dur": [180, 90, 150], "loop": true}, {"nome": "obra pronta", "quadros": [3], "dur": [600], "loop": false}], "uso": "Mesmo pivô da fogueira (x=64, gy=148). Mostrado enquanto a obra conta (EVO-04); a barra de tempo vai por cima (UI). Ao terminar mostra o quadro pronto com pulo squash/stretch em tempo real e depois troca para o novo nível em fog_niveis.", "w": 512, "h": 160}]}, {"grupo": "explosivos", "titulo": "Barril, bomba e explosões", "ordem": 10, "resumo": "Tudo que faz BUM: o barril vermelho de 200 L (EXP), a bomba de ferro da serralharia (BMB), a bola de fogo com impact frame, destroços, fumaça em camadas, marca queimada, círculo de perigo, anel de choque, muros rachados que só abrem com explosão e o caixote que quebra.", "itens": [{"id": "exp_barril", "nome": "Barril explosivo", "categoria": "Explosivos", "mecanica": "Barril explosivo (EXP-01..03, EXP-06, EXP-09, EXP-10)", "conceito": "Tambor de aço de 200 litros que sobrou dos postos de gasolina e do porto do Recife, ainda cheio de combustível velho. Pintado de vermelho com uma faixa amarela de perigo listrada de preto e uma etiqueta em losango com o símbolo de chama, ele lê de longe como 'não bata aqui perto'. A tinta está lascada, com ferrugem escorrendo dos aros, amassados de pancada e um trapo de pano enfiado no bocal servindo de pavio. Um golpe acende o trapo; o barril chia, pisca branco cada vez mais rápido, incha e balança antes de virar uma bola de fogo. Depois sobra só a base retorcida e chamuscada, que não volta na mesma expedição.", "partes": [{"parte": "Corpo cilíndrico", "descricao": "52 px de largura (x 39..89) por ~64 px de altura (topo y 46, fundo y 106 + elipse ry 7). Vermelho #a8262c com faixa clara vertical à esquerda #cf4a3e/#e27a5c (luz da lua) e faixa escura à direita #741a22/#4e1219, dando volume de cilindro. Textura pontilhada leve."}, {"parte": "Aros de rolagem", "descricao": "2 aros salientes de 3 px em y 58 e y 94, curvos seguindo a perspectiva (arco de elipse ry 7), vermelho mais escuro com linha de brilho no topo e ferrugem #8a4e2e escorrendo para baixo."}, {"parte": "Faixa de perigo", "descricao": "Faixa amarela #e8b830 de 14 px (y 67..81) com listras diagonais pretas #1e1a1c de 4 px; curvatura igual à dos aros; borda inferior #b8861a."}, {"parte": "Etiqueta de chama", "descricao": "Losango de 18×18 px centrado em x 60, y 74, branco sujo #e8e0cc com borda preta e uma chama vermelha #c8323a com miolo laranja #f08a3e; canto rasgado."}, {"parte": "Tampa e bocais", "descricao": "Elipse do topo 50×14 px com aro (chime) #b83a36 e miolo rebaixado #7a1e24; bocal grande com rosca cinza #9a9a94 em x 75 e bujão pequeno fechado em x 52."}, {"parte": "Pavio de pano", "descricao": "Trapo bege sujo #cdbf9a/#a89870 com manchas de óleo #6a5a40 de ~12 px saindo do bocal e caindo pela borda. Aceso: chama em 4 camadas nítidas (vermelho, laranja, amarelo, branco) de 8–12 px que alterna de forma entre 2 quadros, com faíscas de 1 px amarelas e brancas."}, {"parte": "Desgaste", "descricao": "Manchas de ferrugem irregulares (#8a4e2e, #6a3a22, #b0683a) na base e nos aros, 3 amassados (elipse escura com crescente claro), lascas de tinta mostrando metal #6b6a66, escorrido de combustível escuro."}, {"parte": "Destruído", "descricao": "Só a base até y ~86 com a borda superior rasgada em pétalas dobradas para fora, carbonizada (#2a1a1c, #3a2226) com restos de tinta vermelha embaixo, interior preto, brasas laranja e fiapo de fumaça."}, {"parte": "Marca no chão", "descricao": "Decalque de queimado 96×36 px no chão (degraus escuros + rachaduras) com brasas, para ficar onde o barril estava."}], "paleta": [{"nome": "Vermelho barril", "hex": "#a8262c"}, {"nome": "Vermelho luz", "hex": "#cf4a3e"}, {"nome": "Brilho", "hex": "#e27a5c"}, {"nome": "Vermelho sombra", "hex": "#741a22"}, {"nome": "Sombra funda", "hex": "#4e1219"}, {"nome": "Amarelo perigo", "hex": "#e8b830"}, {"nome": "Amarelo escuro", "hex": "#b8861a"}, {"nome": "Listra preta", "hex": "#1e1a1c"}, {"nome": "Etiqueta", "hex": "#e8e0cc"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Ferrugem escura", "hex": "#6a3a22"}, {"nome": "Metal exposto", "hex": "#6b6a66"}, {"nome": "Pano", "hex": "#cdbf9a"}, {"nome": "Carvão", "hex": "#2a1a1c"}, {"nome": "Fogo amarelo", "hex": "#ffd84a"}, {"nome": "Fogo laranja", "hex": "#f58a2a"}], "arquivo": "sprites/exp_barril.png", "fw": 128, "fh": 128, "cols": 10, "quadros": ["normal", "pavio aceso 1", "pavio aceso 2", "piscando branco fraco", "piscando branco forte", "inchado 115% (balança esq.)", "inchado 115% (balança dir.)", "inspira (branco total)", "destruído", "marca queimada no chão"], "anims": [{"nome": "pavio aceso", "quadros": [1, 2], "dur": [90, 90], "loop": true}, {"nome": "antecipação 0,9 s", "quadros": [1, 3, 2, 4, 1, 3, 4, 5, 4, 6, 3, 5, 4, 6, 7], "dur": [120, 90, 90, 70, 60, 50, 50, 50, 40, 40, 40, 40, 40, 40, 60], "loop": false}, {"nome": "estouro → destruído", "quadros": [7, 8], "dur": [60, 800], "loop": false}], "uso": "Pivô na base (64, 110); gy = 110, sombra incluída. Objeto sólido do mapa. O piscar acelerado da antecipação é a sequência dos quadros 3/4 (o jogo pode também aplicar tint branco em tempo real). O inchaço já está desenhado a 115% nos quadros 5–7, mas o balanço contínuo pode ser rotação em tempo real. No estouro o jogo troca para exp_explosao + exp_destrocos + exp_fumaca + exp_perigo (anel) e deixa o quadro 8 (ou 9, se o barril sumir) no chão. O círculo vermelho de raio vem de exp_perigo.", "w": 1280, "h": 128}, {"id": "exp_explosao", "nome": "Bola de fogo e impact frame", "categoria": "Explosivos", "mecanica": "Explosão (EXP-04, EXP-06, EXP-12, BMB-04)", "conceito": "A bola de fogo que nasce do barril ou da bomba e cresce até o raio de dano em 0,15 s. É uma couve-flor de fogo em camadas nítidas: núcleo branco que cega, anel amarelo, labaredas laranja e bordas vermelhas, terminando numa nuvem de fumaça escura com brasas. Cada camada é um degrau de cor sólido com pontilhado nas transições, nada de degradê liso. Os 2 quadros de impact frame são o 'flash' da Lua de Sangue: primeiro o mundo vira branco com a silhueta preta da explosão e dos estilhaços, depois tudo preto com a bola branca, como nos animes de luta.", "partes": [{"parte": "Núcleo (q0)", "descricao": "Bola de ~52 px: branco #fffbe8 ocupando 70%, aro amarelo #ffd84a e borda laranja #f58a2a; 12 raios curtos de luz em volta e brilho quantizado."}, {"parte": "Amarelo (q1)", "descricao": "Couve-flor de ~100 px: borda laranja, corpo amarelo, núcleo branco deslocado para cima; lóbulos de 14–20 px de raio; pontilhado amarelo/laranja na transição."}, {"parte": "Laranja (q2)", "descricao": "~144 px: borda vermelha #d8402a com contorno #6a1414, corpo laranja, miolo amarelo pequeno, labaredas pontiagudas saindo para cima e lados, primeiros tufos de fumaça no topo."}, {"parte": "Vermelho (q3)", "descricao": "~168 px: fogo vermelho e vermelho-escuro #8a2020 quebrado em manchas, fumaça escura #3a3038 envolvendo por cima, poucos pontos laranja ainda acesos."}, {"parte": "Fumaça (q4)", "descricao": "Nuvem escura #3a3038/#554a52 com destaque frio #6e646c no topo-esquerdo, rasgada, subindo, com brasas laranja soltas."}, {"parte": "Impact frame (q5, q6)", "descricao": "Quadro inteiro opaco. q5: fundo branco puro com silhueta preta da explosão estrelada e de estilhaços voando. q6: fundo preto com a bola branca (mesma silhueta, menor) e anel branco fino."}], "paleta": [{"nome": "Branco núcleo", "hex": "#fffbe8"}, {"nome": "Amarelo", "hex": "#ffd84a"}, {"nome": "Laranja", "hex": "#f58a2a"}, {"nome": "Vermelho fogo", "hex": "#d8402a"}, {"nome": "Vermelho escuro", "hex": "#8a2020"}, {"nome": "Contorno fogo", "hex": "#5a1010"}, {"nome": "Fumaça escura", "hex": "#3a3038"}, {"nome": "Fumaça média", "hex": "#554a52"}, {"nome": "Fumaça luz", "hex": "#6e646c"}, {"nome": "Impact preto", "hex": "#0c080a"}], "arquivo": "sprites/exp_explosao.png", "fw": 192, "fh": 192, "cols": 7, "quadros": ["núcleo branco", "amarelo", "laranja", "vermelho", "fumaça escura", "impact: branco com silhueta preta", "impact: preto com bola branca"], "anims": [{"nome": "explosão", "quadros": [5, 6, 0, 1, 2, 3, 4], "dur": [40, 40, 40, 50, 60, 120, 260], "loop": false}, {"nome": "explosão (reduzir flashes)", "quadros": [0, 1, 2, 3, 4], "dur": [40, 50, 60, 120, 260], "loop": false}], "uso": "Centro da bola em (96, 104); o ponto de chão fica em y ~150. Escalar em tempo real para casar com o raio (2,5 tiles barril, 2,2 tiles bomba). Os quadros de impact (5, 6) cobrem a tela: o jogo estica o quadro para a tela inteira ou usa como máscara e congela 80–90 ms. Com 'reduzir flashes' (EXP-12) pule 5 e 6 e use um flash laranja suave.", "w": 1344, "h": 192}, {"id": "exp_destrocos", "nome": "Destroços voando", "categoria": "Explosivos", "mecanica": "Destroços (EXP-06, BMB-06, BMB-09, HAM-06)", "conceito": "Pedaços que a explosão joga para todo lado. Do barril voam chapas de aço pintadas de vermelho, dobradas e com um pedaço da faixa amarela, que giram em 4 quadros. Do caixote e das barricadas saem lascas e tábuas com pregos. Da bomba no chão saem torrões de terra e pedras de calçamento, e de tudo sobem brasas acesas. Cada peça é pequena mas legível: contorno escuro, luz de cima-esquerda, ferrugem e farpas.", "partes": [{"parte": "Chapa de metal (q0–q3)", "descricao": "Placa curva de ~30×16 px, face vermelha #a8262c com faixa amarela #e8b830 listrada, verso de metal cinza #6b6a66 com ferrugem, borda rasgada em dente. Desenhada em 0°, 90°, 180°, 270° e com a face alternando frente/verso."}, {"parte": "Madeira (q4–q5)", "descricao": "Tábua quebrada de ~28×8 px #9a6a3c/#7d5430 com veio escuro #5a3a22, ponta em farpa e um prego #c9c3b0 torto; lasca menor junto; 2 rotações."}, {"parte": "Torrão e pedra (q6–q7)", "descricao": "Torrão de terra marrom #6a4a30 com grama verde #5f7a4a por cima e pedra de paralelepípedo cinza #8e8a84 de ~12 px; 2 rotações."}, {"parte": "Brasas (q8–q9)", "descricao": "Grupo de 5–7 brasas de 2–4 px: miolo amarelo #ffd84a, borda laranja #f58a2a/vermelha #d8402a, com brilho quantizado; pisca entre 2 quadros."}], "paleta": [{"nome": "Vermelho barril", "hex": "#a8262c"}, {"nome": "Amarelo perigo", "hex": "#e8b830"}, {"nome": "Metal", "hex": "#6b6a66"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua escura", "hex": "#5a3a22"}, {"nome": "Terra", "hex": "#6a4a30"}, {"nome": "Grama", "hex": "#5f7a4a"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Brasa", "hex": "#f58a2a"}], "arquivo": "sprites/exp_destrocos.png", "fw": 64, "fh": 64, "cols": 10, "quadros": ["chapa 0°", "chapa 90°", "chapa 180°", "chapa 270°", "madeira 1", "madeira 2", "torrão/pedra 1", "torrão/pedra 2", "brasas 1", "brasas 2"], "anims": [{"nome": "chapa girando", "quadros": [0, 1, 2, 3], "dur": [60, 60, 60, 60], "loop": true}, {"nome": "madeira girando", "quadros": [4, 5], "dur": [80, 80], "loop": true}, {"nome": "torrão girando", "quadros": [6, 7], "dur": [80, 80], "loop": true}, {"nome": "brasas", "quadros": [8, 9], "dur": [100, 100], "loop": true}], "uso": "Partícula com pivô no centro (32, 32). O jogo move em arco, gira em tempo real entre os quadros, faz quicar (30–35%) e desenha a sombra elíptica no chão separada (a sombra muda com a altura z). Escala 0,6–1,2 para variar. Brasas sobem balançando e somem com alpha.", "w": 640, "h": 64}, {"id": "exp_fumaca", "nome": "Fumaça de explosão", "categoria": "Explosivos", "mecanica": "Fumaça (EXP-06, BMB-06)", "conceito": "Fumaça de pixel art em camadas duras, como num beat'em up dos anos 90. A nuvem redonda nasce cinza-escura, cresce, sobe e clareia até se desfazer. As lufadas escuras são rápidas e esticadas para o lado, com rastro de velocidade, empurradas pela onda de choque. As colunas cinzas sobem devagar, empilhando bolos de fumaça e afinando no topo. Cada bolo tem 3 tons sólidos (sombra roxa embaixo-direita, corpo, destaque frio da lua em cima-esquerda) e pontilhado na transição.", "partes": [{"parte": "Nuvem crescendo (q0–q3)", "descricao": "Cacho de 5–9 bolos: raio total 16 → 26 → 36 → 44 px, sobe 0 → 24 px; cor #3a3038 → #554a52 → #6e646c → #8a8290; o último fica rasgado e com buracos (some)."}, {"parte": "Lufada lateral (q4–q6)", "descricao": "Bolos escuros #2e262e/#3a3038 esticados 2:1 para a direita, de 40 a 96 px de comprimento, com 3–5 riscos de velocidade na traseira; afina e abre no último quadro."}, {"parte": "Coluna (q7–q9)", "descricao": "Pilha vertical de bolos cinza #6e646c/#8a8290 de 20–30 px de largura, subindo de 40 a 100 px de altura, ondulando para os lados; topo se desfaz em fiapos."}], "paleta": [{"nome": "Fumaça preta", "hex": "#2e262e"}, {"nome": "Fumaça escura", "hex": "#3a3038"}, {"nome": "Fumaça média", "hex": "#554a52"}, {"nome": "Fumaça cinza", "hex": "#6e646c"}, {"nome": "Fumaça clara", "hex": "#8a8290"}, {"nome": "Destaque lua", "hex": "#a49cac"}, {"nome": "Contorno fumaça", "hex": "#1e1820"}], "arquivo": "sprites/exp_fumaca.png", "fw": 128, "fh": 128, "cols": 10, "quadros": ["nuvem 1", "nuvem 2", "nuvem 3", "nuvem 4 (some)", "lufada 1", "lufada 2", "lufada 3", "coluna 1", "coluna 2", "coluna 3"], "anims": [{"nome": "nuvem sobe", "quadros": [0, 1, 2, 3], "dur": [250, 350, 400, 450], "loop": false}, {"nome": "lufada", "quadros": [4, 5, 6], "dur": [200, 250, 350], "loop": false}, {"nome": "coluna", "quadros": [7, 8, 9], "dur": [600, 700, 800], "loop": false}], "uso": "Pivô na base (64, 112). Instâncias múltiplas (~10 nuvens, 9 lufadas, 7 colunas), com escala, espelho horizontal (lufada para a esquerda) e alpha decrescendo em tempo real. Camada acima dos personagens.", "w": 1280, "h": 128}, {"id": "exp_marca", "nome": "Marca queimada (scorch)", "categoria": "Explosivos", "mecanica": "Scorch (EXP-06, BMB-08)", "conceito": "O decalque que a explosão deixa no chão e que fica até a próxima Lua de Sangue. Uma elipse de queimado em degraus (fuligem marrom por fora, preto no meio, cinza de cinza no centro) com 7 rachaduras irregulares que saem do centro. Nas rachaduras ficam brasas acesas que piscam por 4 s. Em mapas de grama, a grama em volta fica seca e preta, com tufos amarelados. Com o tempo a marca esmaece até 35%.", "partes": [{"parte": "Degraus de queimado", "descricao": "Elipse 104×60 px (perspectiva 0,58) em 4 degraus de borda irregular: #3a2e2a (alpha 120), #2a2024 (170), #1a1418 (220) e centro #120c10 com salpicos de cinza #6a6264."}, {"parte": "Rachaduras", "descricao": "7 rachaduras em zigue-zague de 1–2 px #0a0608, de 18 a 44 px, com borda clara de 1 px #4a4044 no lado de cima e ramificações."}, {"parte": "Brasas", "descricao": "8–10 brasas de 1–3 px laranja #f58a2a / amarelo #ffd84a dentro das rachaduras, com brilho quantizado; alternam quais estão acesas entre os quadros 0 e 1."}, {"parte": "Grama queimada", "descricao": "Anel de 30 tufos de grama: perto da marca pretos/marrons #2a2018, #5a4428, mais longe amarelados #a08a48, com pontas chamuscadas."}], "paleta": [{"nome": "Fuligem", "hex": "#3a2e2a"}, {"nome": "Queimado", "hex": "#2a2024"}, {"nome": "Carvão", "hex": "#1a1418"}, {"nome": "Centro", "hex": "#120c10"}, {"nome": "Cinza", "hex": "#6a6264"}, {"nome": "Rachadura", "hex": "#0a0608"}, {"nome": "Brasa", "hex": "#f58a2a"}, {"nome": "Brasa viva", "hex": "#ffd84a"}, {"nome": "Grama seca", "hex": "#a08a48"}, {"nome": "Grama preta", "hex": "#2a2018"}], "arquivo": "sprites/exp_marca.png", "fw": 128, "fh": 96, "cols": 5, "quadros": ["brasas acesas 1", "brasas acesas 2", "apagada", "esmaecida 35%", "com grama queimada em volta"], "anims": [{"nome": "brasas piscando (4 s)", "quadros": [0, 1], "dur": [160, 160], "loop": true}], "uso": "Decalque de chão, centro em (64, 50), desenhado ABAIXO de tudo. 4 s de brasas (0/1), depois quadro 2 e o jogo esmaece o alpha até 35% em 60 s (o quadro 3 é a referência do estado final). Em mapas de grama use o quadro 4 por baixo. Escala com o raio.", "w": 640, "h": 96}, {"id": "exp_perigo", "nome": "Círculo de perigo e anel de choque", "categoria": "Explosivos", "mecanica": "Aviso de raio e shockwave (EXP-03, EXP-07, BMB-03, BMB-05)", "conceito": "Os avisos e ondas desenhados no chão. O círculo de perigo é uma elipse tracejada vermelho-lua com preenchimento translúcido, anel interno de pontos e mira central que pulsam, mostrando o raio para o jogador fugir. O anel de choque nasce no centro e corre para fora em elipse (perspectiva 0,6), branco quente com borda laranja, ficando mais fino ao crescer. O anel de refração é a faixa clara que o jogo usa para distorcer a cena (borda clara por dentro, escura por fora, miolo transparente).", "partes": [{"parte": "Círculo de perigo (q0–q1)", "descricao": "Elipse 112×64 px de traços de 4 px com 3 px de espaço, #c8323a com contorno #5a0e14; preenchimento #c8323a alpha 40/70; anel interno de pontos a 72% do raio e mira central; q1 2 px maior e mais forte."}, {"parte": "Anel de choque (q2–q4)", "descricao": "Elipse de raio 22 → 40 → 58 px, espessura 6 → 4 → 2 px, branco #fff4e0 por dentro, laranja #f58a2a por fora, alpha caindo; poeira nos pontos da borda."}, {"parte": "Anel com refração (q5)", "descricao": "Faixa de 6 px: linha clara #fff4e0 (alpha 200) por dentro, faixa transparente branca (alpha 60) no meio e linha escura #2a2030 (alpha 110) por fora."}], "paleta": [{"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Contorno perigo", "hex": "#5a0e14"}, {"nome": "Branco quente", "hex": "#fff4e0"}, {"nome": "Laranja", "hex": "#f58a2a"}, {"nome": "Borda escura", "hex": "#2a2030"}], "arquivo": "sprites/exp_perigo.png", "fw": 128, "fh": 96, "cols": 6, "quadros": ["perigo pulso 1", "perigo pulso 2", "anel de choque 1", "anel de choque 2", "anel de choque 3", "anel com refração"], "anims": [{"nome": "perigo pulsando", "quadros": [0, 1], "dur": [160, 160], "loop": true}, {"nome": "anel de choque", "quadros": [2, 3, 4], "dur": [80, 110, 160], "loop": false}], "uso": "Decalque de chão centrado em (64, 48). Escalar em tempo real para o raio (2,5 tiles barril / 2,2 bomba; o anel vai até 2,2× o raio). O quadro 5 serve de máscara para o shader de refração (6–10%) ou como anel simples sem shader.", "w": 768, "h": 96}, {"id": "bmb_bomba", "nome": "Bomba de ferro da serralharia", "categoria": "Explosivos", "mecanica": "Bomba (BMB-01..04, BMB-09)", "conceito": "Escolha: bomba redonda de ferro gasta, feita na serralharia do abrigo com uma boia de ferro de sucata cheia de pólvora, soldada e amarrada com uma cinta de fita silver tape e pregos para estilhaçar. Redonda para quicar e rolar bem no chão (BMB-02). Tem gargalo de latão rosqueado com pavio trançado que encurta e solta faíscas; a pintura preta está gasta mostrando ferro e ferrugem, e há um X de tinta vermelha da Lua marcado na frente. No aviso ela pisca vermelho, pulsa e no último instante fica branca e incha até 135%.", "partes": [{"parte": "Esfera", "descricao": "Raio 12 px (24 px de diâmetro) centrada em (32, 42); ferro preto-azulado #2e2c34 com faixa de luz #4a4856, brilho especular de 3 px #9a98a8 no topo-esquerdo e sombra roxa; ferrugem #8a4e2e e ferro exposto #6b6a66."}, {"parte": "Cinta de fita", "descricao": "Faixa de 4 px de silver tape #9a9a94/#c9c3b0 dando volta na esfera em curva, com 3 cabeças de prego #c9c3b0 espetadas e ponta descolada."}, {"parte": "Marca vermelha", "descricao": "X de tinta vermelho-lua #c8323a de 6 px pintado à mão abaixo da fita."}, {"parte": "Gargalo e pavio", "descricao": "Gargalo de latão #b8861a/#f2c230 de 6×4 px no topo; pavio trançado bege #b59a62 com 14/9/4 px de comprimento (longo/médio/curto), ponta acesa com faíscas em estrela amarelas/brancas."}, {"parte": "Mão (erguida)", "descricao": "Mão do herói em pele #b07a52 segurando por baixo, dedos de 3 px com contorno, manga vermelha #c8323a do herói."}, {"parte": "Contador HUD", "descricao": "No quadro de item, número 'x8' em fonte 3×5 ×2 branca com contorno no canto inferior-direito."}], "paleta": [{"nome": "Ferro", "hex": "#2e2c34"}, {"nome": "Ferro luz", "hex": "#4a4856"}, {"nome": "Brilho", "hex": "#9a98a8"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Fita silver", "hex": "#9a9a94"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Latão", "hex": "#b8861a"}, {"nome": "Pavio", "hex": "#b59a62"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Faísca", "hex": "#ffd84a"}, {"nome": "Pele", "hex": "#b07a52"}], "arquivo": "sprites/bmb_bomba.png", "fw": 64, "fh": 64, "cols": 9, "quadros": ["item HUD (x8)", "chão pavio longo", "chão pavio médio", "chão pavio curto", "piscando vermelho fraco", "piscando vermelho forte", "branca inchada 135% (último aviso)", "squash ao quicar", "sendo erguida (na mão)"], "anims": [{"nome": "pavio queimando 1,8 s", "quadros": [1, 4, 2, 5, 3, 5, 3, 5, 6], "dur": [500, 120, 400, 100, 200, 80, 120, 60, 220], "loop": false}, {"nome": "quique", "quadros": [7, 2], "dur": [60, 100], "loop": false}], "uso": "Pivô na base (32, 56), gy = 56, sombra incluída nos quadros de chão. Voo em arco e rotação de rolagem são em tempo real; o pulso até 108% é escala em tempo real; os quadros 4/5 alternam com 1–3 no bipe (intervalo 0,32 → 0,05 s). Quadro 8 é desenhado sobre a mão do herói por 0,16 s antes do arremesso. Quadro 0 é o ícone do inventário.", "w": 576, "h": 64}, {"id": "bmb_hud", "nome": "Ícone HUD de bombas", "categoria": "Explosivos", "mecanica": "Inventário de bombas (BMB-01)", "conceito": "O contador de bombas do HUD: uma pilha de bombas de ferro (as mesmas da serralharia) sobre um selo escuro, com o número grande no canto. Com o estoque cheio aparecem 3 bombas empilhadas e o número em dourado; com poucas a pilha diminui e o número fica branco; com zero sobra só a silhueta vazia e o número em vermelho-lua, para avisar que acabou. Precisa ler bem pequeno no canto da tela.", "partes": [{"parte": "Selo de fundo", "descricao": "Círculo de 52 px #1c1822 com aro #3c3446 e borda de 2 px, leve brilho em cima."}, {"parte": "Pilha", "descricao": "3 bombas de raio 9 px (2 embaixo, 1 em cima) com pavio e faísca na de cima; com 3 bombas: 2 bombas; com 0: silhueta tracejada cinza #4a4458."}, {"parte": "Número", "descricao": "Dígito 3×5 em escala 3 (9×15 px) com contorno preto de 1 px no canto inferior-direito: 8 dourado #f2c230, 3 branco #fff4e0, 0 vermelho #c8323a."}], "paleta": [{"nome": "Selo", "hex": "#1c1822"}, {"nome": "Aro", "hex": "#3c3446"}, {"nome": "Ferro", "hex": "#2e2c34"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Branco", "hex": "#fff4e0"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}], "arquivo": "sprites/bmb_hud.png", "fw": 64, "fh": 64, "cols": 3, "quadros": ["8 bombas (cheio)", "3 bombas", "0 bombas (vazio)"], "uso": "Ícone fixo do HUD (canto). Para outros números o jogo pode desenhar o dígito por cima do quadro 1 (pilha média); o quadro 2 é o estado sem bombas. Sem sombra de chão.", "w": 192, "h": 64}, {"id": "bmb_parede", "nome": "Muro rachado (passagem secreta)", "categoria": "Explosivos", "mecanica": "Paredes rachadas (BMB-10, HAM-08)", "conceito": "Muros de 1 tile que escondem passagens, baús e atalhos, no estilo Zelda: a rachadura é grande, clara e reconhecível para o jogador saber que ali dá para explodir. A versão principal é de blocos de pedra cinza com argamassa; quando a bomba ou barril estoura ao lado ela racha mais e solta poeira, e depois abre num buraco escuro com blocos caídos na frente. Há também a versão de tijolo vermelho com reboco caído e a de concreto pichado, típica das ruas do Recife, com tags e a lua vermelha.", "partes": [{"parte": "Muro (pedra)", "descricao": "Face frontal 120×100 px (x 4..124, y 48..148) com topo de 12 px visto de cima; blocos de 24×14 px #8e8a84/#77736e com argamassa #b8b0a0, musgo #5f7a4a na base, manchas de umidade."}, {"parte": "Rachadura (estilo Zelda)", "descricao": "Rachadura central em raio de 5 braços em zigue-zague, 2–3 px de largura preta #120c10 com borda clara #c9c2b4, de ~70×60 px, blocos deslocados 1 px em volta; marca em X branca de giz opcional."}, {"parte": "Rachando (q1, q2)", "descricao": "Rachaduras ficam mais largas e com novos ramos; nuvens de poeira bege #9c8a70 e pedrinhas soltando; q2 com lascas no ar."}, {"parte": "Aberto (q3)", "descricao": "Buraco irregular de ~64×76 px até o chão, interior em 3 degraus escuros #0e0a10/#1c1622/#2a2230 revelando passagem com chão e frestas mal iluminadas; borda quebrada com blocos soltos, 5–7 blocos caídos e poeira na base."}, {"parte": "Tijolo (q4, q5)", "descricao": "Tijolos 16×8 px #a5432e/#86351f com rejunte #c9b8a0, reboco #c8bca8 caindo em placas; rachado e aberto."}, {"parte": "Concreto pichado (q6, q7)", "descricao": "Placas de concreto #8f8c86/#7a7772 com juntas, pichação: lua vermelha #c8323a, tags pretas e brancas, seta amarela e escorridos; rachado e aberto com ferro de armadura #8a4e2e saindo."}], "paleta": [{"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra escura", "hex": "#77736e"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Tijolo escuro", "hex": "#86351f"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Concreto", "hex": "#8f8c86"}, {"nome": "Rachadura", "hex": "#120c10"}, {"nome": "Passagem", "hex": "#0e0a10"}, {"nome": "Poeira", "hex": "#9c8a70"}, {"nome": "Musgo", "hex": "#5f7a4a"}, {"nome": "Pichação lua", "hex": "#c8323a"}], "arquivo": "sprites/bmb_parede.png", "fw": 128, "fh": 160, "cols": 8, "quadros": ["pedra: rachado (intacto)", "pedra: rachando 1 (poeira)", "pedra: rachando 2 (poeira)", "pedra: aberto (passagem)", "tijolo: rachado", "tijolo: aberto", "concreto pichado: rachado", "concreto pichado: aberto"], "anims": [{"nome": "abrindo", "quadros": [0, 1, 2, 3], "dur": [80, 90, 110, 600], "loop": false}], "uso": "Tile de muro 1×1 (128×160), base em gy = 148, sombra incluída. Sólido até abrir; ao abrir (explosão de bomba/barril no raio, ou martelo HAM-08) vira passável e mostra o quadro aberto. Para tijolo/concreto o jogo pula direto do rachado ao aberto, com exp_destrocos e poeira por cima.", "w": 1024, "h": 160}, {"id": "exp_caixa_quebra", "nome": "Caixote de madeira quebrável", "categoria": "Explosivos", "mecanica": "Caixas quebráveis (HAM-06, BMB-09)", "conceito": "Caixote de feira/porto de ripas de madeira com cantoneiras de metal, espalhado nos mapas como obstáculo e loot pequeno. Tem estêncil desbotado de 'frágil', pregos enferrujados e tábuas manchadas de umidade. O martelo (shockwave) ou uma explosão no raio racha e depois estoura o caixote em tábuas e lascas, soltando madeira. A leitura é clara: inteiro, rachado (aguenta mais um), quebrando, e o monte de tábuas no chão.", "partes": [{"parte": "Caixote", "descricao": "Cubo em 3/4: frente 64×44 px (x 32..96, y 66..110) e topo 64×18 px; 4 ripas horizontais de 11 px #9a6a3c/#7d5430 com frestas escuras #3a2414, travessa diagonal em X, cantoneiras de metal #7d848c com rebites #c9ced4."}, {"parte": "Detalhes", "descricao": "Estêncil vermelho desbotado #8a3a2a com seta para cima, pregos #c9c3b0 com ferrugem, veios #5a3a22, manchas de umidade escuras, uma farpa levantada."}, {"parte": "Rachado", "descricao": "2 ripas partidas com rachadura preta em zigue-zague, uma ripa solta inclinada, cantoneira torta, lascas no chão."}, {"parte": "Quebrando", "descricao": "Caixote abrindo para fora: tábuas voando inclinadas, lascas e poeira #9c8a70, estrela de impacto."}, {"parte": "Quebrado", "descricao": "Monte de 7–9 tábuas quebradas cruzadas no chão com pregos à mostra, 2 cantoneiras soltas, serragem."}], "paleta": [{"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua sombra", "hex": "#7d5430"}, {"nome": "Tábua escura", "hex": "#5a3a22"}, {"nome": "Fresta", "hex": "#3a2414"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Estêncil", "hex": "#8a3a2a"}, {"nome": "Poeira", "hex": "#9c8a70"}], "arquivo": "sprites/exp_caixa_quebra.png", "fw": 128, "fh": 128, "cols": 4, "quadros": ["inteiro", "rachado", "quebrando", "quebrado (tábuas no chão)"], "anims": [{"nome": "quebrar", "quadros": [1, 2, 3], "dur": [60, 90, 600], "loop": false}], "uso": "Objeto sólido de mapa, base em gy = 112, sombra incluída. 1º golpe/explosão → rachado; 2º (ou explosão direta) → quebrando → quebrado (passável). Solta madeira e lança exp_destrocos (madeira) junto.", "w": 512, "h": 128}]}, {"grupo": "construcoes_producao", "titulo": "Construções: oficinas e produção", "ordem": 11, "resumo": "As quatro construções que produzem e fabricam no abrigo: a Serralheria (armas), o Coletor de água, a Horta (comida) e a Bancada (craft básico). Cada uma tem 5 níveis na escada de materiais (lona → madeira → pedra → tijolo e metal → Lua de Sangue) × 3 estados (intacta, danificada, destruída), sempre reconhecível pela função.", "itens": [{"id": "con_serralheria", "nome": "Serralheria", "categoria": "Construção 2×2", "mecanica": "Abrigo (ABR-03, ABR-06..10, ABR-14), Evolução (EVO-01, EVO-07..10, EVO-13), Invasão (INV-05, INV-06, INV-09); bônus de vizinhança Gerador + Serralheria (2× mais rápido) e Bancada + Serralheria (craft −20%)", "conceito": "Oficina de ferreiro improvisada por sobreviventes que fabrica e melhora armas e ferramentas com a sucata trazida das expedições. É um telheiro de uma água: parede de fundo alta, dois pilares na frente e um telhado inclinado visto de cima; a frente é aberta e deixa ver o interior escuro com a forja de brasas à esquerda (chaminé furando o telhado), a bancada com morsa à direita e ferramentas penduradas no fundo. No pátio da frente ficam sempre a bigorna sobre um toco, o barril de têmpera e um monte de sucata, para que a função seja lida de longe em qualquer nível. O brilho alaranjado da forja é o ponto de luz quente da construção; no N5 a brasa vira fogo vermelho-lua com runas acesas.", "partes": [{"parte": "Telhado (ocupa y≈34–112)", "descricao": "Plano inclinado visto de cima com beiral frontal de 5 px. N1: lona azul #3f6a8c caída entre estacas, com dobras, remendo #8a7a52 e cordas #b59a62 amarradas. N2: ripas de madeira #8b5e34 em fiadas horizontais com pregos #c9c3b0. N3: telha de barro #b5562e/#8f3f22 em capa-e-canal. N4: chapa ondulada #8d969c/#6b747a com manchas de ferrugem #8a4e2e e rebites. N5: ardósia preta #1c1822 em escamas com cumeeira e beiral dourados #f2c230/#b8861a."}, {"parte": "Parede de fundo e pilares", "descricao": "Parede vista por dentro, sombreada, de y≈112 a 196, com ferramentas penduradas (martelo, tenaz, serrote, ferradura, chaves). Pilares nas pontas. N1: lona verde #5f7a4a remendada e estacas tortas #8a6a42; N2: tábuas verticais #9a6a3c/#7d5430 com pregos; N3: blocos de pedra #8e8a84/#77736e com argamassa #b8b0a0; N4: tijolo #a5432e/#86351f com faixa de metal rebitado #7d848c/#c9ced4 e lâmpada acesa #ffd36a; N5: pedra escura #2e2836/#3c3446 com frisos dourados e runas #c8323a brilhando #ff5a5a."}, {"parte": "Forja (esquerda, x≈26–92)", "descricao": "Sempre com brasa laranja e brilho. N1: tambor de óleo cortado com carvão e grelha. N2: forja de barro sobre base de tábuas e fole de couro. N3: forja de pedra com coifa e chaminé de pedra saindo do telhado. N4: forja de tijolo com coifa de chapa rebitada e chaminé de metal. N5: forja de pedra escura com coifa dourada, fogo vermelho e runas."}, {"parte": "Bancada com morsa (direita)", "descricao": "Tampo com morsa de ferro, lima, alicate; N4 ganha esmeril elétrico com faíscas e fio até a lâmpada; N5 tampo de pedra escura com dourado."}, {"parte": "Bigorna, barril e sucata (pátio)", "descricao": "Bigorna (N1 pedaço de trilho de trem sobre toco; N2–N5 bigorna de ferro, N5 com friso dourado) sobre toco com martelo apoiado; barril/balde de têmpera ao lado com água; monte de sucata (chapas, canos, engrenagem, pneu) à direita, que aumenta com o nível."}, {"parte": "Danificada", "descricao": "Rachaduras pretas na parede e no telhado, manchas de fuligem #2a2228, uma peça do material solta (lona rasgada pendurada / tábua torta / blocos caídos / tijolos e chapa entortada / bloco escuro rachado), fogo laranja pequeno e fumaça cinza saindo do telhado. A bigorna continua no lugar."}, {"parte": "Destruída", "descricao": "Monte de escombros do material do nível sobre a mesma base, vigas queimadas #2a1a12 cruzadas, brasas e fumaça; a bigorna e o toco sobrevivem na frente do monte para manter a leitura de serralheria."}], "paleta": [{"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona verde escura", "hex": "#4a6139"}, {"nome": "Remendo", "hex": "#8a7a52"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra 2", "hex": "#77736e"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Telha escura", "hex": "#8f3f22"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Tijolo 2", "hex": "#86351f"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Chapa escura", "hex": "#6b747a"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Pedra lunar 2", "hex": "#3c3446"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Brilho da runa", "hex": "#ff5a5a"}, {"nome": "Ferro da bigorna", "hex": "#4a4c52"}, {"nome": "Brasa", "hex": "#ff8a2a"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/con_serralheria.png", "fw": 256, "fh": 256, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Ocupa 2×2 tiles (256×256). Pivô no centro da base, chão em gy=244. Camada de construções do abrigo, ordenada por y da base. Queda (ABR-06), squash/stretch, pulinho dos vizinhos, andaime e barra de obra (EVO-07) e o brilho de obra pronta (EVO-08) são transformações/efeitos em tempo real, não sprites. Linha = estado, coluna = nível.", "w": 1280, "h": 768}, {"id": "con_coletor", "nome": "Coletor de água", "categoria": "Construção 1×1", "mecanica": "Abrigo (ABR-03, ABR-13 produção idle), Evolução (EVO-01, EVO-09, EVO-13), Invasão (INV-06, INV-09); bônus Coletor + Horta (+25% comida); DN-13 rende mais de madrugada", "conceito": "Coletor de água da chuva que produz Água com o tempo, mesmo com o herói em expedição. Em todos os níveis a leitura é a mesma: uma superfície que capta a chuva no alto descendo por funil/calha até um recipiente com água azul visível em cima. Começa como uma lona esticada em estacas tortas formando funil sobre um balde, vira barril de madeira com calha, cisterna redonda de pedra com telhadinho de barro e sarilho, caixa-d'água de metal rebitado sobre torre de tijolo com torneira pingando, e por fim um reservatório lunar de pedra escura com aro dourado e água que brilha.", "partes": [{"parte": "N1 Lona e sucata", "descricao": "Quatro estacas tortas #8a6a42 seguram uma lona verde #5f7a4a afunilada (remendo #8a7a52, cordas #b59a62) que pinga num balde de sucata #6b6a66 com ferrugem #8a4e2e e água azul; garrafas PET e uma lata ao lado."}, {"parte": "N2 Madeira", "descricao": "Barril de madeira #9a6a3c/#7d5430 com aros de ferro, tampa aberta mostrando água; telhadinho de ripas #8b5e34 sobre dois postes que escoa por uma calha de tábua até o barril; caneca pendurada e torneira de pau."}, {"parte": "N3 Pedra", "descricao": "Cisterna redonda de blocos de pedra #8e8a84/#77736e com argamassa #b8b0a0, borda larga mostrando água; dois pilares de pedra com telhado de telha de barro #b5562e/#8f3f22 e sarilho de madeira com corda e balde."}, {"parte": "N4 Tijolo e metal", "descricao": "Caixa-d'água cilíndrica de chapa #8d969c/#6b747a com faixas rebitadas #7d848c/#c9ced4 sobre base de tijolo #a5432e/#86351f; funil de chapa no topo, escada, cano e torneira com gota, lâmpada acesa #ffd36a e balde embaixo."}, {"parte": "N5 Lua de Sangue", "descricao": "Reservatório de pedra escura #2e2836/#3c3446 com aros e bico dourados #f2c230/#b8861a, runas vermelhas #c8323a brilhando #ff5a5a e água azul-clara luminosa no topo; pequena bandeira vermelha na haste."}, {"parte": "Danificada", "descricao": "Rachaduras e fuligem #2a2228, peça solta do material, vazamento (poça e gotas) no recipiente, foguinho e fumaça pequena."}, {"parte": "Destruída", "descricao": "Escombros do material do nível, recipiente tombado/quebrado no chão com poça de água, vigas queimadas #2a1a12 e fumaça."}], "paleta": [{"nome": "Água", "hex": "#4f8fc0"}, {"nome": "Água clara", "hex": "#8fd0f0"}, {"nome": "Água lunar", "hex": "#bfeaff"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Fuligem", "hex": "#2a2228"}], "arquivo": "sprites/con_coletor.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Ocupa 1×1 tile (128 de largura, 160 de altura com sobra para o topo). Pivô no centro da base, chão em gy=148. Gotas/“+1 Água” e brilho da água são efeitos em tempo real. Linha = estado, coluna = nível.", "w": 640, "h": 480}, {"id": "con_horta", "nome": "Horta", "categoria": "Construção 2×1", "mecanica": "Abrigo (ABR-03, ABR-13 produção idle), Evolução (EVO-01, EVO-09, EVO-13), Invasão (INV-06, INV-09), Grupo (GRP-14 comida melhora o descanso); bônus Coletor + Horta (+25%); DN-13 só produz de dia", "conceito": "Horta comunitária do abrigo que produz Comida com o tempo. Três canteiros vistos de cima em 3/4, com plantas da roça nordestina: macaxeira (hastes avermelhadas e folhas em mão), milho alto com espiga, coentro miúdo e pés de alface redondos. No fundo um espantalho vestido com roupa velha e chapéu de palha vigia a plantação; à frente um regador e um balde. O cercado e a borda dos canteiros sobem na escada de materiais: pneus velhos e lona no N1, caixotes de feira de madeira no N2, canteiros de pedra com murinho no N3, estufa de base de tijolo com estrutura de chapa e irrigação no N4, e canteiros de terra escura com plantas de brilho vermelho e runas no N5.", "partes": [{"parte": "Canteiros (3 faixas, x≈28–228, y≈66–171)", "descricao": "Terra marrom #5a3e2a com sulcos. N1: bordas de pneus #2b2a2e empilhados e lona verde #5f7a4a forrando; N2: caixotes de tábua #9a6a3c/#7d5430 com pregos; N3: bordas de blocos de pedra #8e8a84 com argamassa; N4: bordas de tijolo #a5432e com cano de irrigação de metal #7d848c gotejando; N5: bordas de pedra escura #2e2836 com friso dourado #f2c230, terra quase preta #2a1e22."}, {"parte": "Plantas", "descricao": "Macaxeira (caule #9a4a3a, folhas palmadas #4f8a3a/#6fae4a), milho (colmo #8fae4a, espiga amarela #e8c44a com cabelo), coentro (tufos #5fa040), alface (rosetas #8ccf5a). Ficam mais cheias a cada nível; no N5 as folhas ganham nervuras e frutos vermelhos brilhando #ff5a5a."}, {"parte": "Cercado", "descricao": "N1 gravetos tortos #8a6a42 e corda #b59a62; N2 paliçada de ripas #8b5e34; N3 murinho de pedra; N4 estufa: mureta de tijolo com montantes de metal rebitado, arcos e painéis de plástico translúcido, lâmpada #ffd36a; N5 mureta de pedra escura com pilares de topo dourado, runas #c8323a e bandeirinha vermelha."}, {"parte": "Espantalho, regador e balde", "descricao": "Espantalho de cruz de madeira com camisa xadrez, chapéu de palha #c8a55a e rosto de saco; no N5 olhos vermelhos brilhando. Regador de lata e balde na frente."}, {"parte": "Danificada", "descricao": "Plantas pisoteadas e murchas (#8a7a3a), trecho do cercado quebrado com uma peça solta, fuligem #2a2228, rachaduras nas bordas, foguinho e fumaça; espantalho torto."}, {"parte": "Destruída", "descricao": "Canteiros revirados com terra espalhada, escombros do cercado no material do nível, plantas secas, espantalho caído, vigas queimadas #2a1a12 e fumaça."}], "paleta": [{"nome": "Terra", "hex": "#5a3e2a"}, {"nome": "Terra escura", "hex": "#3e2a1c"}, {"nome": "Folha", "hex": "#4f8a3a"}, {"nome": "Folha clara", "hex": "#6fae4a"}, {"nome": "Alface", "hex": "#8ccf5a"}, {"nome": "Milho", "hex": "#e8c44a"}, {"nome": "Caule de macaxeira", "hex": "#9a4a3a"}, {"nome": "Murcha", "hex": "#8a7a3a"}, {"nome": "Pneu", "hex": "#2b2a2e"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Palha", "hex": "#c8a55a"}], "arquivo": "sprites/con_horta.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Ocupa 2×1 tiles (256×192). Pivô no centro da base, chão em gy=180. Balanço das folhas ao vento e o “+1 Comida” são efeitos em tempo real. Linha = estado, coluna = nível.", "w": 1280, "h": 576}, {"id": "con_bancada", "nome": "Bancada", "categoria": "Construção 2×1", "mecanica": "Abrigo (ABR-03, ABR-06..10), Evolução (EVO-01, EVO-09, EVO-13), Invasão (INV-06, INV-09); bônus Bancada + Serralheria (craft −20%)", "conceito": "Bancada de trabalho para o craft básico do abrigo: ataduras, barricadas e gazuas. É um alpendre encostado (parede de fundo + cobertura vista de cima) com uma bancada comprida na frente. Em cima do tampo ficam sempre o serrote, o rolo de pano branco para ataduras, a lata de pregos, o martelo e um pano com gazuas e grampos; encostadas ao lado ficam tábuas de barricada com pregos. No fundo há um quadro de ferramentas. Cada nível troca parede, cobertura, tampo e pernas pelo material da escada, e acrescenta conforto: lampião, morsa, gaveteiro, lâmpada e por fim o brilho rúnico.", "partes": [{"parte": "Cobertura (y≈22–64)", "descricao": "N1 lona azul #3f6a8c caída com cordas #b59a62 e estacas tortas; N2 ripas #8b5e34; N3 telha de barro #b5562e/#8f3f22; N4 chapa ondulada #8d969c/#6b747a com ferrugem; N5 ardósia #1c1822 com cumeeira dourada #f2c230."}, {"parte": "Parede de fundo (y≈64–128)", "descricao": "N1 lona verde #5f7a4a remendada com chapa de sucata #6b6a66; N2 tábuas verticais com pregos; N3 blocos de pedra com argamassa; N4 tijolo com faixa de metal rebitado e lâmpada #ffd36a; N5 pedra escura com friso dourado e runas #c8323a. Quadro de ferramentas (tábua/chapa perfurada) com alicate, chave, tesoura."}, {"parte": "Bancada (tampo y≈126–138, pernas até gy=180)", "descricao": "N1 porta velha deitada sobre dois tambores de sucata enferrujados; N2 tampo de tábuas sobre cavaletes de madeira; N3 tampo grosso de madeira com pernas de pedra e morsa; N4 tampo com cantoneira de metal rebitada, gaveteiro de chapa e morsa; N5 tampo de pedra escura com borda dourada e pernas com runas."}, {"parte": "Ferramentas e itens do craft", "descricao": "Serrote (lâmina #c9ced4, cabo #8b5e34), rolo de pano #e8e0cc com ataduras desenroladas, lata de pregos, martelo, gazuas e grampos sobre pano vermelho; tábuas de barricada com pregos encostadas à esquerda; no N4 lâmpada e no N5 lanterna vermelha."}, {"parte": "Danificada", "descricao": "Rachaduras pretas, fuligem #2a2228, peça solta do material (lona rasgada, tábua torta, bloco caído, chapa entortada, bloco escuro rachado), foguinho e fumaça; itens espalhados no tampo."}, {"parte": "Destruída", "descricao": "Monte de escombros do material do nível, tampo quebrado ao meio com o serrote e o rolo de pano jogados na frente, vigas queimadas #2a1a12 e fumaça."}], "paleta": [{"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Pano de atadura", "hex": "#e8e0cc"}, {"nome": "Lâmina", "hex": "#c9ced4"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/con_bancada.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Ocupa 2×1 tiles (256×192). Pivô no centro da base, chão em gy=180. Recruta trabalhando, faíscas do martelo e o “+1” do craft são efeitos/sprites de outros grupos em tempo real. Linha = estado, coluna = nível.", "w": 1280, "h": 576}]}, {"grupo": "construcoes_defesa", "titulo": "Construções: moradia, energia e defesa", "ordem": 12, "resumo": "Barraca (moradia dos recrutas), gerador (energia), barricada, muralha e portão do abrigo. Cada um sobe a escada de materiais (lona e sucata → madeira → pedra → tijolo e metal → Lua de Sangue) e tem visual de intacta, danificada e destruída — a muralha e o portão são a primeira linha de defesa na invasão.", "itens": [{"id": "con_barraca", "nome": "Barraca / Alojamento", "categoria": "Construção", "mecanica": "Abrigo (ABR-03, ABR-06..09), Evolução (EVO-01, EVO-09), Grupo (GRP-01, GRP-09, GRP-14), Invasão (INV-06, INV-09)", "conceito": "Onde os recrutas dormem e moram: cada nível dá mais camas (GRP-01) e é para cá que o recruta cansado anda para dormir (GRP-09). Começa como uma barraca de lona verde remendada, armada com estacas tortas e cordas, com uma lona azul jogada por cima e um colchonete saindo pela porta. Vira uma cabana de tábuas com uma rede nordestina listrada na varanda, depois uma casinha de pedra com telha de barro e chaminé, um alojamento de tijolo com faixas de metal, chapa ondulada, caixa-d'água, beliche à vista na janela e lâmpada acesa, e por fim uma casa lunar de pedra escura com ardósia preta, cumeeira dourada, runas vermelhas e bandeira. Em todos os níveis há uma cama visível (colchonete, rede, cama, beliche, leito lunar) para a função ser lida de longe. Ocupa 2×1 tiles e o tamanho na grade nunca muda.", "partes": [{"parte": "Paredes / corpo", "descricao": "Faixa frontal de ~200 px de largura. N1: a própria lona da barraca (duas águas até o chão, dobras verticais, remendos costurados). N2: tábuas verticais de 7 px com frestas escuras e pregos. N3: blocos de pedra com argamassa. N4: tijolo vermelho com duas faixas de metal rebitadas. N5: pedra escura com frisos dourados em cima e embaixo e runas vermelhas brilhando."}, {"parte": "Telhado", "descricao": "N1: lona azul caída por cima, presa com cordas em estacas. N2: ripas horizontais de madeira, duas águas. N3: telha de barro em fileiras com chaminé de pedra soltando fumacinha. N4: chapa de metal ondulada com ferrugem e caixa-d'água em cima. N5: ardósia preta em escamas com cumeeira e beirais dourados."}, {"parte": "Cama (função)", "descricao": "N1: colchonete listrado com travesseiro saindo pela abertura. N2: rede listrada vermelha/amarela entre dois postes da varanda. N3: cama com cobertor vermelho vista pela janela. N4: beliche de metal na janela iluminada. N5: leito com manta vermelha atrás de janela de vitral vermelho."}, {"parte": "Porta e janelas", "descricao": "Aba de lona aberta (N1); porta de tábua (N2); porta de madeira com dobradiças e janela com venezianas verdes (N3); porta de metal rebitada com lâmpada amarela acesa e brilho (N4); porta em arco com moldura dourada e lua vermelha (N5)."}, {"parte": "Props", "descricao": "N1: caixote, lata, estacas e cordas no chão. N2: barril de madeira e banco de tronco. N3: cisterna pequena / jarro e vaso. N4: caixa-d'água, cano e varal de fios. N5: mastro com bandeira vermelha e braseiro com fogo vermelho."}, {"parte": "Danificada", "descricao": "Rachaduras pretas, manchas de fuligem #2a2228, uma peça solta caída (tábua, telha, tijolo ou chapa), buraco no telhado, fumaça cinza e um foguinho laranja pequeno."}, {"parte": "Destruída", "descricao": "Tocos de parede do material do nível, monte de escombros (lona rasgada / tábuas quebradas / blocos / tijolos e chapas / pedra escura e dourado), vigas queimadas #2a1a12 cruzadas, a cama destruída ainda visível e colunas de fumaça."}], "paleta": [{"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona verde escura", "hex": "#4a6139"}, {"nome": "Remendo", "hex": "#8a7a52"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Telha escura", "hex": "#8f3f22"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Brilho runa", "hex": "#ff5a5a"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/con_barraca.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Âncora no centro da base: x = 128, y = gy = 180 (chão). Ocupa 2×1 tiles (256 px). Camada de construções, ordenada por y da base. Queda (ABR-06), squash/stretch (EVO-08) e pulinho de vizinhança (ABR-09) são transformações em tempo real do sprite, não quadros. O 💤 do recruta dormindo é emote da UI.", "w": 1280, "h": 576}, {"id": "con_gerador", "nome": "Gerador", "categoria": "Construção", "mecanica": "Abrigo (ABR-03, ABR-10 Gerador + Serralheria, ABR-14), Evolução (EVO-01, EVO-09, EVO-13), Invasão (INV-06, INV-09)", "conceito": "Gerador a gasolina que dá energia para as outras construções (e deixa a Serralheria 2× mais rápida quando fica ao lado). No nível 1 é um motor velho de cortador de grama/bomba d'água amarrado com corda num estrado de madeira, com galão vermelho de gasolina e fios soltos enrolados no chão. No 2 o motor ganha uma casinha de tábuas com telhado de ripas e o escapamento sai pelo teto; no 3 fica numa base de pedra com meia-parede coroada de telhas e escapamento alto de ferro; no 4 vira um gabinete de metal rebitado com painel de relógios e chaves, lâmpadas acesas em cima e fios esticados até um poste; no 5 é um gerador lunar de pedra escura e ouro com um núcleo vermelho pulsando atrás de uma janela redonda. Sempre solta fumaça do escapamento (cinza escura no início, avermelhada no 5), o que o identifica de longe.", "partes": [{"parte": "Motor", "descricao": "Bloco do motor ~40×26 px cinza-ferrugem com aletas de resfriamento, tanque de combustível vermelho desbotado por cima, puxador de partida com corda e filtro de ar redondo. Presente em todos os níveis (dentro da casinha, sobre a base ou dentro do gabinete)."}, {"parte": "Base / abrigo do motor", "descricao": "N1 estrado de madeira e cordas amarrando o motor. N2 casinha de tábuas aberta na frente com telhado de ripas. N3 pedestal e meia-parede de pedra coroada por uma fileira de telhas de barro. N4 gabinete de chapa com rebites, grade de ventilação e painel (2 relógios, chaves, luz verde/vermelha) em base de tijolo. N5 caixa de pedra escura com frisos dourados, janela redonda mostrando o núcleo vermelho e runas."}, {"parte": "Escapamento e fumaça", "descricao": "Cano de 4 px subindo à direita (curto no N1, atravessando o teto no N2, alto de ferro no N3/N4, dourado no N5). Fumaça em 3-4 bolotas subindo, cinza #8a8494 / #6a6474; no N5 com brasas vermelhas."}, {"parte": "Fios e energia", "descricao": "N1 fios soltos enrolados no chão; N2/N3 fio saindo pela lateral; N4 fios esticados até um poste com 2 lâmpadas amarelas acesas; N5 cabos com brilho vermelho e faíscas."}, {"parte": "Combustível", "descricao": "Galão vermelho de gasolina (N1-N3), tambor de metal (N4), cristal/fragmento lunar (N5)."}, {"parte": "Danificada / destruída", "descricao": "Danificada: rachaduras, fuligem, uma tábua/chapa solta, fumaça mais densa e foguinho. Destruída: motor tombado e retorcido no meio dos escombros do material do nível, vigas queimadas e fumaça preta."}], "paleta": [{"nome": "Ferro do motor", "hex": "#5c5a58"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Tanque vermelho", "hex": "#a8392e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Estaca / estrado", "hex": "#8a6a42"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Núcleo vermelho", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Fumaça", "hex": "#8a8494"}, {"nome": "Fuligem", "hex": "#2a2228"}], "arquivo": "sprites/con_gerador.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Âncora x = 64, y = gy = 148. 1×1 tile; a sobra de cima (≈30 px) é para escapamento e fumaça. Vibração do motor ligado = tremor de 1 px em tempo real; a fumaça pode ganhar partículas extras no jogo. Andaime da obra (EVO-07) é um overlay separado.", "w": 640, "h": 480}, {"id": "con_barricada", "nome": "Barricada", "categoria": "Construção", "mecanica": "Abrigo (ABR-03), Evolução (EVO-01, EVO-09), Invasão (INV-02, INV-05, INV-06, INV-09)", "conceito": "Obstáculo de defesa barato que segura a horda quando ela entra no abrigo. No nível 1 é uma pilha de pneus velhos, uma porta de geladeira, chapas de sucata e um carrinho de supermercado amassado, amarrados com corda. No 2 vira um cavalete de estacas de madeira apontadas em X (cavalo de frisa) com tábuas pregadas. No 3, sacos de areia empilhados com blocos de pedra. No 4, uma chapa de metal rebitada escorada, com rolo de arame farpado em cima e placa de perigo. No 5, um bloco de pedra escura com pontas douradas apontando para fora e runa vermelha brilhando. Sempre baixa e larga, lida de longe como 'não passa'.", "partes": [{"parte": "Corpo", "descricao": "Bloco de ~100×50 px apoiado em gy. N1 3 pneus empilhados + chapa de sucata enferrujada + porta branca suja; N2 estacas de 6 px cruzadas em X com pontas claras e duas tábuas horizontais pregadas; N3 3 fileiras de sacos de areia bege com costura e blocos de pedra nas pontas; N4 chapa de metal com rebites e faixas amarelas/pretas, escoras atrás; N5 pedra lunar com frisos dourados."}, {"parte": "Topo / pontas", "descricao": "N1 vergalhões tortos e corda; N2 pontas de estaca afiadas; N3 bloco de pedra em cima; N4 rolo de arame farpado (laços cinza com farpas); N5 pontas douradas em leque."}, {"parte": "Sangue e marcas", "descricao": "Arranhões e sangue seco #5a1a1a nos níveis baixos (já segurou zumbis), marcas de mãos."}, {"parte": "Danificada / destruída", "descricao": "Danificada: rachaduras, fuligem, uma peça tombada, fumaça e foguinho. Destruída: monte esparramado do material (pneus soltos, estacas quebradas, sacos rasgados com areia, chapa dobrada, pedra escura e pontas douradas quebradas), vigas queimadas e fumaça."}], "paleta": [{"nome": "Pneu", "hex": "#2b2a2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Saco de areia", "hex": "#b8a47a"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Faixa de perigo", "hex": "#e0b52a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Sangue seco", "hex": "#5a1a1a"}], "arquivo": "sprites/con_barricada.png", "fw": 128, "fh": 128, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "Âncora x = 64, y = gy = 116. 1×1 tile. Tremor ao levar golpe (INV-05) é em tempo real.", "w": 640, "h": 384}, {"id": "con_muralha", "nome": "Muralha (segmentos)", "categoria": "Construção / Defesa", "mecanica": "Invasão (INV-03, INV-04, INV-05, INV-06, INV-09), Evolução (EVO-14: 300 → 600 → 1000 → 1600 → 2500 HP)", "conceito": "A muralha que cerca o abrigo e segura a Lua de Sangue, montada com segmentos de 1 tile que se emendam lado a lado (textura repete a cada 128 px, sem contorno nas bordas laterais). Nível 1: cerca improvisada de estacas tortas com chapas de sucata, lona verde e lona azul amarradas com corda. Nível 2: paliçada de troncos apontados com travessas pregadas. Nível 3: muro de pedra com argamassa, passarela e ameias. Nível 4: muro de tijolo com faixas de metal rebitadas, tampa de chapa, rolo de arame farpado e lâmpada acesa. Nível 5: pedra escura com frisos dourados, ameias com pontas douradas e runas vermelhas brilhando. Cada nível tem o trecho reto intacto, o reto rachado (HP baixo), o canto (a muralha vira para trás com um pilar reforçado) e a brecha aberta quando um trecho cede na invasão (INV-05), com escombros e poeira no vão.", "partes": [{"parte": "Face frontal", "descricao": "Ocupa x 0..127 inteiro. Altura cresce por nível (≈50 / 60 / 66 / 70 / 74 px acima de gy=148). Material da escada: estacas+sucata+lonas / troncos / blocos de pedra / tijolo e metal / pedra lunar."}, {"parte": "Topo", "descricao": "N1 cordas e pontas de chapa; N2 pontas afiadas dos troncos; N3 passarela de pedra vista de cima e ameias (merlões de 14 px); N4 tampa de chapa com rolo de arame farpado e poste com lâmpada amarela; N5 passarela escura, ameias com pontas douradas."}, {"parte": "Rachado", "descricao": "Rachaduras pretas ramificadas, fuligem #2a2228, um pedaço do topo faltando, uma peça caída no pé, poeira/fumacinha."}, {"parte": "Canto", "descricao": "Metade esquerda é face frontal; no centro um pilar mais largo e alto; a muralha segue para trás (para cima no quadro) como o topo visto de cima, até a borda superior."}, {"parte": "Brecha", "descricao": "Dois tocos nas laterais com quebra irregular, vão no meio com monte de escombros do material, vigas/pedaços caídos e nuvens de poeira."}], "paleta": [{"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Fuligem", "hex": "#2a2228"}], "arquivo": "sprites/con_muralha.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 reto", "N2 reto", "N3 reto", "N4 reto", "N5 reto", "N1 rachado", "N2 rachado", "N3 rachado", "N4 rachado", "N5 rachado", "N1 canto", "N2 canto", "N3 canto", "N4 canto", "N5 canto", "N1 brecha", "N2 brecha", "N3 brecha", "N4 brecha", "N5 brecha"], "uso": "Cada segmento ocupa 1 tile; âncora no canto inferior esquerdo (x = 0, y = gy = 148) e se emenda com o vizinho a cada 128 px. O 'rachado' entra quando o HP da muralha cai abaixo de ~50%; a 'brecha' substitui o trecho que cedeu (INV-05). Tremor ao levar golpe e guardas em cima (INV-04) são em tempo real. O canto pode ser espelhado horizontalmente para o lado direito.", "w": 640, "h": 640}, {"id": "con_portao", "nome": "Portão da muralha", "categoria": "Construção / Defesa", "mecanica": "Invasão (INV-03, INV-05, INV-06, INV-09), Grupo (GRP-02: a expedição sai pelo portão), Evolução (EVO-14)", "conceito": "Portão de 2 tiles por onde o herói e os recrutas saem para a expedição (GRP-02) e por onde a horda tenta entrar. Dois pilares seguram duas folhas e tocos de muralha nas bordas emendam com os segmentos da muralha do mesmo nível. Nível 1: pilares de tambores e pneus empilhados, folhas de chapa de sucata com lona sobre armação de pau, dobradiças de corda. Nível 2: pilares de tronco com folhas de tábuas com travessa em Z e pregos. Nível 3: pilares de pedra com arco e folhas de madeira grossa com ferragens. Nível 4: pilares de tijolo com faixas de metal, folhas de chapa rebitada, lâmpadas nos pilares e arame farpado. Nível 5: pilares de pedra escura com capitéis dourados, folhas escuras com lua vermelha e runas e braseiros vermelhos. Aberto mostra o caminho de terra saindo; fechado mostra a tranca; danificado tem folha torta, rachaduras, fuligem, fumaça e foguinho.", "partes": [{"parte": "Pilares", "descricao": "2 pilares de ~30 px de largura em x≈36 e x≈220, mais altos que a muralha do nível (+12 px), com capitel/tampa do material."}, {"parte": "Folhas", "descricao": "Fechado: duas folhas de ~76 px cada se encontrando no centro, com tranca/barra horizontal. Aberto: folhas abertas para dentro, vistas de lado como faixas estreitas encostadas nos pilares, e o chão de terra/pedra do caminho visível no vão."}, {"parte": "Tocos de muralha", "descricao": "Da borda do quadro até o pilar, mesma altura/material de con_muralha do nível, para emendar."}, {"parte": "Detalhes por nível", "descricao": "N1 cordas e tambores; N2 pregos e travessa Z; N3 arco de pedra e ferragens pretas; N4 lâmpadas amarelas acesas e arame farpado; N5 braseiros com fogo vermelho, lua vermelha na folha, pontas douradas."}, {"parte": "Danificado", "descricao": "Folha arrombada/torta (uma caída para dentro), rachaduras nos pilares, fuligem, uma peça solta no chão, fumaça e foguinho."}], "paleta": [{"nome": "Tambor", "hex": "#6a7a6a"}, {"nome": "Pneu", "hex": "#2b2a2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Ferragem", "hex": "#2e2a2a"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Terra do caminho", "hex": "#6a5640"}], "arquivo": "sprites/con_portao.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["N1 aberto", "N2 aberto", "N3 aberto", "N4 aberto", "N5 aberto", "N1 fechado", "N2 fechado", "N3 fechado", "N4 fechado", "N5 fechado", "N1 danificado", "N2 danificado", "N3 danificado", "N4 danificado", "N5 danificado"], "anims": [{"nome": "abrir N1", "quadros": [5, 0], "dur": [300, 600], "loop": false}, {"nome": "abrir N5", "quadros": [9, 4], "dur": [300, 600], "loop": false}], "uso": "Âncora no canto inferior esquerdo (x = 0, y = gy = 180), 2 tiles; emenda com con_muralha do mesmo nível (mesma altura de face e topo). Fica aberto quando a expedição sai/volta (GRP-02) e fechado na invasão. Destruído usa a 'brecha' da muralha do nível.", "w": 1280, "h": 576}]}, {"grupo": "estacoes", "titulo": "Estações de trabalho e obras", "ordem": 13, "resumo": "Estações onde os recrutas trabalham (Posto de guarda, Pilha de toras, Ponto de coleta, Obra — 2 vagas cada), com 5 níveis × 3 estados na escada de materiais, mais os objetos animados do trabalho, o andaime de obra, o selo de nível, os marcadores da prévia de construção e as camas.", "itens": [{"id": "est_posto_guarda", "nome": "Posto de guarda", "categoria": "Estação de trabalho", "mecanica": "Grupo GRP-07, GRP-10; Invasão INV-04; Evolução EVO-09", "conceito": "Ponto alto de onde os recrutas com especialidade Defesa vigiam a cerca do abrigo (2 vagas). Em todos os níveis é lido pela mesma silhueta: algo ALTO e estreito, com um lugar de vigia lá em cima, uma escada na frente e uma bandeirinha no topo. N1 é a gambiarra do primeiro dia: uma cadeira de plástico de bar em cima de caixotes de feira e um tambor enferrujado, com lona verde remendada amarrada em volta e uma lona azul de sombra em duas estacas tortas. N2 vira uma torre de madeira de pernas abertas com contraventamento em X, guarda-corpo de tábuas e telhadinho de ripas. N3 é uma guarita de pedra com ameias e casinha de telha de barro em cima. N4 é torre de tijolo cintada com faixas de metal rebitado, plataforma de grade, telhado de chapa ondulada, holofote aceso varrendo e arame farpado. N5 é a torre lunar de pedra escura com acabamento dourado, runas vermelhas e um braseiro de fogo vermelho no topo.", "partes": [{"parte": "Base / corpo", "descricao": "N1 caixotes de feira (ripas horizontais, fresta escura) + tambor de sucata enferrujado, ~60 px de largura; N2 quatro pernas de tronco com X; N3 tronco de pedra 68 px com seteira e porta de madeira; N4 tronco de tijolo 56 px com 2 faixas de metal rebitado e porta de chapa; N5 tronco de pedra lunar afunilado com cantoneiras douradas e runas."}, {"parte": "Plataforma de vigia", "descricao": "N1 cadeira de plástico branca encardida em y~80; N2-N5 plataforma em y~56-70 com guarda-corpo do material do nível (tábuas pregadas / ameias / grade de metal / parapeito dourado)."}, {"parte": "Cobertura", "descricao": "N1 lona azul inclinada presa por cordas; N2 telhado de ripas; N3 casinha de pedra com telha de barro; N4 chapa ondulada; N5 braseiro dourado com chama vermelha em vez de telhado."}, {"parte": "Escada", "descricao": "Escada frontal de varas amarradas (N1), de madeira (N2), degraus de pedra/porta (N3), escada de metal lateral (N4), degraus dourados (N5) — marca a função em todos os níveis."}, {"parte": "Bandeira", "descricao": "Trapo vermelho num pau (N1), bandeira de pano (N2-N4), estandarte vermelho com lua dourada (N5)."}, {"parte": "Detalhes", "descricao": "Garrafa, cordas e chapa encostada (N1); barril (N2); tocha (N3); holofote com cone de luz amarela, lâmpada, arame farpado (N4); runas brilhando e brasas (N5)."}], "paleta": [{"nome": "Cadeira de plástico", "hex": "#d4cebd"}, {"nome": "Trapo vermelho", "hex": "#b8433a"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona verde escura", "hex": "#4a6139"}, {"nome": "Remendo", "hex": "#8a7a52"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra 2", "hex": "#77736e"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Telha escura", "hex": "#8f3f22"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Tijolo 2", "hex": "#86351f"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Chapa escura", "hex": "#6b747a"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Pedra lunar 2", "hex": "#3c3446"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Runa brilho", "hex": "#ff5a5a"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/est_posto_guarda.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "1×1 tile. Pivô no centro da base (x=64, gy=148). Os guardas (sprites de recruta) aparecem sobre a plataforma; na invasão (INV-04) o jogo os desenha em cima da muralha. O cone do holofote do N4 é parte do sprite (camada fx). Selo de nível (est_selo) vai no canto superior direito.", "w": 640, "h": 480}, {"id": "est_pilha_toras", "nome": "Pilha de toras", "categoria": "Estação de trabalho", "mecanica": "Grupo GRP-07, GRP-08, GRP-10; Evolução EVO-09", "conceito": "Estação dos recrutas com especialidade Madeira (2 vagas): uma pilha de toras vista de topo (anéis do tronco virados para a câmera) à esquerda e um toco de cortar com machado cravado à direita, cercado de lascas. A pilha fica mais organizada a cada nível: N1 galhos e toras tortas amontoadas em cima de uma lona, com lona azul jogada por cima e estacas tortas; N2 pirâmide arrumada entre estacas de madeira, cavalete com tora; N3 pirâmide sobre base de blocos de pedra com pilares e telhadinho de telha; N4 estante de metal rebitado sobre tijolo, chapa ondulada, lâmpada e uma bancada de serra circular; N5 toras escuras com veios vermelhos brilhando nos anéis, base de pedra lunar com dourado e machado de lâmina dourada.", "partes": [{"parte": "Pilha", "descricao": "Toras com face de anéis (elipse ~18-22 px) e casca por cima; 3 a 4 fileiras em pirâmide (N2+), desarrumada no N1; à esquerda do quadro (x 14-140)."}, {"parte": "Toco de cortar", "descricao": "Toco largo com anéis no topo, raízes e machado cravado inclinado; à direita (x ~190-240). N1 lâmina de sucata enferrujada, N5 cabo escuro e lâmina dourada."}, {"parte": "Lascas", "descricao": "Lascas claras espalhadas pelo chão em volta do toco e serragem."}, {"parte": "Estrutura do nível", "descricao": "Lona/estacas (N1), estacas e cavalete (N2), base e pilares de pedra com telha (N3), estante metálica, chapa ondulada, lâmpada e serra circular (N4), plinto lunar dourado e runa (N5)."}], "paleta": [{"nome": "Casca", "hex": "#5a3e28"}, {"nome": "Cerne", "hex": "#d6ad72"}, {"nome": "Anel", "hex": "#a87a48"}, {"nome": "Lasca", "hex": "#e2c28a"}, {"nome": "Veio lunar", "hex": "#ff5a5a"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona verde escura", "hex": "#4a6139"}, {"nome": "Remendo", "hex": "#8a7a52"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra 2", "hex": "#77736e"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Telha escura", "hex": "#8f3f22"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Tijolo 2", "hex": "#86351f"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Chapa escura", "hex": "#6b747a"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Pedra lunar 2", "hex": "#3c3446"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Runa brilho", "hex": "#ff5a5a"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/est_pilha_toras.png", "fw": 256, "fh": 192, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "2×1 tiles. Pivô no centro da base (x=128, gy=180). O recruta lenhador fica ao lado do toco; a animação do machado e lascas está em est_trabalho (linha 0). O '+1 Madeira' sobe do toco.", "w": 1280, "h": 576}, {"id": "est_ponto_coleta", "nome": "Ponto de coleta", "categoria": "Estação de trabalho", "mecanica": "Grupo GRP-07, GRP-08, GRP-10; Evolução EVO-09", "conceito": "Onde os recrutas de Coleta juntam Sucata e Pano (2 vagas). Em todo nível há dois montes lado a lado, sucata cinza (engrenagens, latas, canos, chapas) e pano colorido (trouxas e rolos), e um cesto de palha na frente — assim a função é lida de longe. N1: carrinho de supermercado roubado lotado de tralha e um cesto, sobre lona, com placa de papelão. N2: caixotes de madeira abertos e empilhados, placa de tábua. N3: duas baias de pedra com toldo de telha. N4: caçamba de metal rebitada sobre base de tijolo, lâmpada no poste e arame farpado. N5: depósito lunar, um baú grande de pedra escura com cantos dourados, tampa aberta brilhando vermelho por dentro e runas.", "partes": [{"parte": "Recipiente principal", "descricao": "carrinho de arame (N1), caixotes de ripas (N2), baias de pedra em U (N3), caçamba trapezoidal de chapa com rebites (N4), baú lunar (N5); ~80-100 px de largura."}, {"parte": "Monte de sucata", "descricao": "engrenagens com dentes, latas, cano, chapas tortas com ferrugem."}, {"parte": "Monte de pano", "descricao": "trouxas e rolos de pano azul, vermelho, bege e verde com dobras e listras."}, {"parte": "Cesto", "descricao": "cesto de palha trançada (linhas cruzadas) na frente, igual em todos os níveis (N5 com aro dourado)."}, {"parte": "Cobertura/extra", "descricao": "placa de papelão (N1), placa de tábua (N2), toldo de telha (N3), poste com lâmpada (N4), estandarte e brilho (N5)."}], "paleta": [{"nome": "Palha", "hex": "#c9a45a"}, {"nome": "Arame do carrinho", "hex": "#a9b0b6"}, {"nome": "Pano vermelho", "hex": "#b8433a"}, {"nome": "Pano bege", "hex": "#d2c09a"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Lona verde escura", "hex": "#4a6139"}, {"nome": "Remendo", "hex": "#8a7a52"}, {"nome": "Lona azul", "hex": "#3f6a8c"}, {"nome": "Corda", "hex": "#b59a62"}, {"nome": "Estaca", "hex": "#8a6a42"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Sucata", "hex": "#6b6a66"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Ripa", "hex": "#8b5e34"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Pedra 2", "hex": "#77736e"}, {"nome": "Argamassa", "hex": "#b8b0a0"}, {"nome": "Telha", "hex": "#b5562e"}, {"nome": "Telha escura", "hex": "#8f3f22"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Tijolo 2", "hex": "#86351f"}, {"nome": "Rejunte", "hex": "#c9b8a0"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Chapa escura", "hex": "#6b747a"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Pedra lunar 2", "hex": "#3c3446"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Ardósia", "hex": "#1c1822"}, {"nome": "Runa", "hex": "#c8323a"}, {"nome": "Runa brilho", "hex": "#ff5a5a"}, {"nome": "Fuligem", "hex": "#2a2228"}, {"nome": "Viga queimada", "hex": "#2a1a12"}], "arquivo": "sprites/est_ponto_coleta.png", "fw": 128, "fh": 160, "cols": 5, "quadros": ["N1 intacta", "N2 intacta", "N3 intacta", "N4 intacta", "N5 intacta", "N1 danificada", "N2 danificada", "N3 danificada", "N4 danificada", "N5 danificada", "N1 destruída", "N2 destruída", "N3 destruída", "N4 destruída", "N5 destruída"], "uso": "1×1 tile. Pivô no centro da base (x=64, gy=148). O recruta coletor agacha e joga coisas no cesto (est_trabalho linha 2); '+1 Sucata'/'+1 Pano' sobem daqui.", "w": 640, "h": 480}, {"id": "est_trabalho", "nome": "Objetos do trabalho (animados)", "categoria": "Estação de trabalho", "mecanica": "Grupo GRP-08 (+1 recurso subindo), GRP-10 (animação por trabalho)", "conceito": "Folha de animações de objetos que acompanham o recruta trabalhando, desenhadas para sobrepor a estação. Linha 0: toco com tora e machado descendo — levantado, no meio do golpe, impacto com estrela e lascas voando, machado cravado e lascas caindo. Linha 1: martelo batendo num prego sobre uma tábua num cavalete, com faíscas no impacto. Linha 2: cesto de palha recebendo coisas jogadas em arco (uma engrenagem e um trapo), que pula e solta poeira. Linhas 3-7: o texto '+1' com o ícone do recurso (Madeira, Sucata, Pano, Água, Comida) subindo e sumindo em 4 quadros; como são 5 recursos, cada recurso é UMA linha de 4 quadros (grade de 4 colunas × 8 linhas).", "partes": [{"parte": "Machado", "descricao": "cabo de madeira 30 px, lâmina de aço com fio claro; 4 posições de golpe."}, {"parte": "Toco e tora", "descricao": "toco com anéis, tora curta em pé que racha no impacto."}, {"parte": "Lascas", "descricao": "lascas claras #e2c28a de 2-4 px voando em leque e caindo."}, {"parte": "Martelo e cavalete", "descricao": "martelo de cabeça de aço, tábua com prego no cavalete; faíscas amarelas e estrela de impacto."}, {"parte": "Cesto", "descricao": "cesto trançado 34 px; achata ao receber; poeira."}, {"parte": "+1 e ícones", "descricao": "'+1' creme com contorno escuro em fonte de pixel e ícone 18 px: tora (Madeira), engrenagem (Sucata), pano dobrado (Pano), gota azul (Água), espiga de milho (Comida); sobe ~40 px e fica transparente."}], "paleta": [{"nome": "Lasca", "hex": "#e2c28a"}, {"nome": "Faísca", "hex": "#ffd36a"}, {"nome": "Faísca branca", "hex": "#fff6c8"}, {"nome": "Texto +1", "hex": "#fff4e0"}, {"nome": "Água", "hex": "#4a8fe0"}, {"nome": "Milho", "hex": "#f2c230"}, {"nome": "Palha", "hex": "#c9a45a"}, {"nome": "Aço", "hex": "#9aa3ab"}], "arquivo": "sprites/est_trabalho.png", "fw": 128, "fh": 128, "cols": 4, "quadros": ["machado 1", "machado 2", "machado 3", "machado 4", "martelo 1", "martelo 2", "martelo 3", "martelo 4", "cesto 1", "cesto 2", "cesto 3", "cesto 4", "+1 Madeira 1", "+1 Madeira 2", "+1 Madeira 3", "+1 Madeira 4", "+1 Sucata 1", "+1 Sucata 2", "+1 Sucata 3", "+1 Sucata 4", "+1 Pano 1", "+1 Pano 2", "+1 Pano 3", "+1 Pano 4", "+1 Água 1", "+1 Água 2", "+1 Água 3", "+1 Água 4", "+1 Comida 1", "+1 Comida 2", "+1 Comida 3", "+1 Comida 4"], "anims": [{"nome": "machado", "quadros": [0, 1, 2, 3], "dur": [260, 90, 140, 220], "loop": true}, {"nome": "martelo", "quadros": [4, 5, 6, 7], "dur": [200, 80, 120, 160], "loop": true}, {"nome": "cesto", "quadros": [8, 9, 10, 11], "dur": [140, 140, 120, 260], "loop": true}, {"nome": "+1 Madeira", "quadros": [12, 13, 14, 15], "dur": [140, 160, 180, 220], "loop": false}, {"nome": "+1 Sucata", "quadros": [16, 17, 18, 19], "dur": [140, 160, 180, 220], "loop": false}, {"nome": "+1 Pano", "quadros": [20, 21, 22, 23], "dur": [140, 160, 180, 220], "loop": false}, {"nome": "+1 Água", "quadros": [24, 25, 26, 27], "dur": [140, 160, 180, 220], "loop": false}, {"nome": "+1 Comida", "quadros": [28, 29, 30, 31], "dur": [140, 160, 180, 220], "loop": false}], "uso": "Overlay 128×128 com chão em gy=112, centrado no recruta/estação. Linha r começa no índice 4*r. Os '+1' são soltos acima da estação e podem também ser movidos em tempo real (o sprite já traz a subida).", "w": 512, "h": 1024}, {"id": "est_obra_1x1", "nome": "Obra de evolução (andaime 1×1)", "categoria": "Estação de trabalho", "mecanica": "Evolução EVO-05, EVO-07, EVO-08, EVO-11; Grupo GRP-07 (estação Obra); Invasão INV-09", "conceito": "Overlay transparente que se põe por cima de QUALQUER construção de tamanho 1×1 enquanto ela evolui ou é reconstruída. Andaime de tubos galvanizados com braçadeiras amarelas, tábuas de piso em 2-3 andares, travas em X, rede de proteção verde (trama de pixels, deixa ver a construção) e uma lona verde remendada pendurada num canto. No chão: tábua listrada amarelo/preto, cone, balde de massa, pilha de tijolos e placa '!'. Um martelo bate numa tábua do andaime soltando faíscas (3 quadros), um quadro com nuvens de poeira, e dois quadros de 'obra pronta' sem andaime: brilho dourado, estrelas e cintilantes se abrindo (EVO-08).", "partes": [{"parte": "Tubos", "descricao": "verticais nas bordas (e no meio nos tamanhos largos), tubo #8d969c com braçadeira amarela #f2c230."}, {"parte": "Pisos", "descricao": "tábuas #9a6a3c com pregos em cada andar, rodapé."}, {"parte": "Rede e lona", "descricao": "rede verde em xadrez de pixels (transparente entre os fios) e lona #5f7a4a remendada amarrada com corda."}, {"parte": "Chão de obra", "descricao": "cone laranja, balde, tijolos, tábua zebrada, placa de aviso."}, {"parte": "Martelo e faíscas", "descricao": "martelo no andar de cima, estrela de impacto e faíscas amarelas."}, {"parte": "Obra pronta", "descricao": "estrelas douradas, cintilantes brancos, anel de brilho na base; sem andaime."}], "paleta": [{"nome": "Tubo", "hex": "#8d969c"}, {"nome": "Braçadeira", "hex": "#f2c230"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Rede", "hex": "#4f8a3a"}, {"nome": "Lona", "hex": "#5f7a4a"}, {"nome": "Cone", "hex": "#e0702a"}, {"nome": "Zebrado preto", "hex": "#1c1820"}, {"nome": "Faísca", "hex": "#ffd36a"}, {"nome": "Estrela", "hex": "#f2c230"}], "arquivo": "sprites/est_obra_1x1.png", "fw": 128, "fh": 160, "cols": 7, "quadros": ["andaime + lona", "martelo 1 (levantado)", "martelo 2 (impacto, faíscas)", "martelo 3 (faíscas caindo)", "poeira", "obra pronta 1 (brilho e estrelas)", "obra pronta 2 (estrelas se abrindo)"], "anims": [{"nome": "obra", "quadros": [0, 1, 2, 3, 1, 2, 3, 4], "dur": [300, 160, 80, 140, 160, 80, 140, 300], "loop": true}, {"nome": "pronta", "quadros": [5, 6], "dur": [160, 260], "loop": false}], "uso": "Mesmo quadro e mesmo gy (altura−12) da construção; desenhar POR CIMA dela, alinhado pelo canto. A barra de tempo com contagem regressiva é UI do jogo (não está no sprite). Pulo squash/stretch da obra pronta é transformação em tempo real na construção.", "w": 896, "h": 160}, {"id": "est_obra_2x1", "nome": "Obra de evolução (andaime 2×1)", "categoria": "Estação de trabalho", "mecanica": "Evolução EVO-05, EVO-07, EVO-08, EVO-11; Grupo GRP-07 (estação Obra); Invasão INV-09", "conceito": "Overlay transparente que se põe por cima de QUALQUER construção de tamanho 2×1 enquanto ela evolui ou é reconstruída. Andaime de tubos galvanizados com braçadeiras amarelas, tábuas de piso em 2-3 andares, travas em X, rede de proteção verde (trama de pixels, deixa ver a construção) e uma lona verde remendada pendurada num canto. No chão: tábua listrada amarelo/preto, cone, balde de massa, pilha de tijolos e placa '!'. Um martelo bate numa tábua do andaime soltando faíscas (3 quadros), um quadro com nuvens de poeira, e dois quadros de 'obra pronta' sem andaime: brilho dourado, estrelas e cintilantes se abrindo (EVO-08).", "partes": [{"parte": "Tubos", "descricao": "verticais nas bordas (e no meio nos tamanhos largos), tubo #8d969c com braçadeira amarela #f2c230."}, {"parte": "Pisos", "descricao": "tábuas #9a6a3c com pregos em cada andar, rodapé."}, {"parte": "Rede e lona", "descricao": "rede verde em xadrez de pixels (transparente entre os fios) e lona #5f7a4a remendada amarrada com corda."}, {"parte": "Chão de obra", "descricao": "cone laranja, balde, tijolos, tábua zebrada, placa de aviso."}, {"parte": "Martelo e faíscas", "descricao": "martelo no andar de cima, estrela de impacto e faíscas amarelas."}, {"parte": "Obra pronta", "descricao": "estrelas douradas, cintilantes brancos, anel de brilho na base; sem andaime."}], "paleta": [{"nome": "Tubo", "hex": "#8d969c"}, {"nome": "Braçadeira", "hex": "#f2c230"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Rede", "hex": "#4f8a3a"}, {"nome": "Lona", "hex": "#5f7a4a"}, {"nome": "Cone", "hex": "#e0702a"}, {"nome": "Zebrado preto", "hex": "#1c1820"}, {"nome": "Faísca", "hex": "#ffd36a"}, {"nome": "Estrela", "hex": "#f2c230"}], "arquivo": "sprites/est_obra_2x1.png", "fw": 256, "fh": 192, "cols": 7, "quadros": ["andaime + lona", "martelo 1 (levantado)", "martelo 2 (impacto, faíscas)", "martelo 3 (faíscas caindo)", "poeira", "obra pronta 1 (brilho e estrelas)", "obra pronta 2 (estrelas se abrindo)"], "anims": [{"nome": "obra", "quadros": [0, 1, 2, 3, 1, 2, 3, 4], "dur": [300, 160, 80, 140, 160, 80, 140, 300], "loop": true}, {"nome": "pronta", "quadros": [5, 6], "dur": [160, 260], "loop": false}], "uso": "Mesmo quadro e mesmo gy (altura−12) da construção; desenhar POR CIMA dela, alinhado pelo canto. A barra de tempo com contagem regressiva é UI do jogo (não está no sprite). Pulo squash/stretch da obra pronta é transformação em tempo real na construção.", "w": 1792, "h": 192}, {"id": "est_obra_2x2", "nome": "Obra de evolução (andaime 2×2)", "categoria": "Estação de trabalho", "mecanica": "Evolução EVO-05, EVO-07, EVO-08, EVO-11; Grupo GRP-07 (estação Obra); Invasão INV-09", "conceito": "Overlay transparente que se põe por cima de QUALQUER construção de tamanho 2×2 enquanto ela evolui ou é reconstruída. Andaime de tubos galvanizados com braçadeiras amarelas, tábuas de piso em 2-3 andares, travas em X, rede de proteção verde (trama de pixels, deixa ver a construção) e uma lona verde remendada pendurada num canto. No chão: tábua listrada amarelo/preto, cone, balde de massa, pilha de tijolos e placa '!'. Um martelo bate numa tábua do andaime soltando faíscas (3 quadros), um quadro com nuvens de poeira, e dois quadros de 'obra pronta' sem andaime: brilho dourado, estrelas e cintilantes se abrindo (EVO-08).", "partes": [{"parte": "Tubos", "descricao": "verticais nas bordas (e no meio nos tamanhos largos), tubo #8d969c com braçadeira amarela #f2c230."}, {"parte": "Pisos", "descricao": "tábuas #9a6a3c com pregos em cada andar, rodapé."}, {"parte": "Rede e lona", "descricao": "rede verde em xadrez de pixels (transparente entre os fios) e lona #5f7a4a remendada amarrada com corda."}, {"parte": "Chão de obra", "descricao": "cone laranja, balde, tijolos, tábua zebrada, placa de aviso."}, {"parte": "Martelo e faíscas", "descricao": "martelo no andar de cima, estrela de impacto e faíscas amarelas."}, {"parte": "Obra pronta", "descricao": "estrelas douradas, cintilantes brancos, anel de brilho na base; sem andaime."}], "paleta": [{"nome": "Tubo", "hex": "#8d969c"}, {"nome": "Braçadeira", "hex": "#f2c230"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Rede", "hex": "#4f8a3a"}, {"nome": "Lona", "hex": "#5f7a4a"}, {"nome": "Cone", "hex": "#e0702a"}, {"nome": "Zebrado preto", "hex": "#1c1820"}, {"nome": "Faísca", "hex": "#ffd36a"}, {"nome": "Estrela", "hex": "#f2c230"}], "arquivo": "sprites/est_obra_2x2.png", "fw": 256, "fh": 256, "cols": 7, "quadros": ["andaime + lona", "martelo 1 (levantado)", "martelo 2 (impacto, faíscas)", "martelo 3 (faíscas caindo)", "poeira", "obra pronta 1 (brilho e estrelas)", "obra pronta 2 (estrelas se abrindo)"], "anims": [{"nome": "obra", "quadros": [0, 1, 2, 3, 1, 2, 3, 4], "dur": [300, 160, 80, 140, 160, 80, 140, 300], "loop": true}, {"nome": "pronta", "quadros": [5, 6], "dur": [160, 260], "loop": false}], "uso": "Mesmo quadro e mesmo gy (altura−12) da construção; desenhar POR CIMA dela, alinhado pelo canto. A barra de tempo com contagem regressiva é UI do jogo (não está no sprite). Pulo squash/stretch da obra pronta é transformação em tempo real na construção.", "w": 1792, "h": 256}, {"id": "est_selo", "nome": "Selo de nível", "categoria": "Estação de trabalho", "mecanica": "Evolução EVO-02, EVO-07, EVO-08, EVO-10", "conceito": "Medalhão redondo sempre visível no canto de cada construção, com o número do nível grande em creme e a borda feita do material da escada: N1 lona verde costurada com remendo e corda em volta; N2 disco de tábuas com pregos; N3 anel de blocos de pedra com centro de telha; N4 aro de metal rebitado com centro de tijolo; N5 pedra lunar com aro dourado, gema vermelha e brilho. Mais dois selos de estado: 'em obra' (aro zebrado amarelo/preto com engrenagem e martelo) e 'precisa da Fogueira' (cadeado cinza com selinho de chama).", "partes": [{"parte": "Aro", "descricao": "anel de ~6 px no material do nível."}, {"parte": "Centro", "descricao": "disco interno ~36 px, mais escuro para o número contrastar."}, {"parte": "Número", "descricao": "dígito 5×7 em escala 3 (15×21 px), creme #fff4e0 com contorno escuro (N5 dourado)."}, {"parte": "Em obra", "descricao": "engrenagem cinza de 8 dentes com martelo cruzado sobre aro zebrado."}, {"parte": "Cadeado", "descricao": "cadeado de aço com buraco de chave e chama laranja num selinho."}], "paleta": [{"nome": "Número", "hex": "#fff4e0"}, {"nome": "Engrenagem", "hex": "#9aa3ab"}, {"nome": "Zebrado", "hex": "#f2c230"}, {"nome": "Chama", "hex": "#ff8a2a"}, {"nome": "Lona verde", "hex": "#5f7a4a"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Pedra", "hex": "#8e8a84"}, {"nome": "Tijolo", "hex": "#a5432e"}, {"nome": "Pedra lunar", "hex": "#2e2836"}, {"nome": "Pedra lunar 2", "hex": "#3c3446"}, {"nome": "Dourado", "hex": "#f2c230"}], "arquivo": "sprites/est_selo.png", "fw": 64, "fh": 64, "cols": 7, "quadros": ["nível 1", "nível 2", "nível 3", "nível 4", "nível 5", "em obra", "precisa da Fogueira"], "uso": "HUD/ícone 64×64 desenhado no canto superior direito da construção (pode ser reduzido a 50%). O pulso do EVO-08 é escala em tempo real.", "w": 448, "h": 64}, {"id": "est_ghost", "nome": "Marcadores da prévia de construção", "categoria": "Estação de trabalho", "mecanica": "Abrigo ABR-04, ABR-10, ABR-11; Evolução EVO-05", "conceito": "Peças de UI desenhadas como pixel art para a prévia translúcida de construção. Tile verde (pode construir): preenchimento verde translúcido, borda clara com cantoneiras e pontilhado interno da grade. Tile vermelho (não pode): mesma forma em vermelho-lua com um X grosso no meio. Linha dourada do bônus de vizinhança em duas peças: 'ponta' (nó dourado com brilho no centro e a linha saindo para a direita) e 'meio' (linha atravessando o quadro inteiro com pontinhos brilhantes), para o jogo emendar e girar. Ícone do construtor: capacete amarelo de obra, livre (selo verde com visto) e ocupado (capacete apagado com selo vermelho de relógio).", "partes": [{"parte": "Tile", "descricao": "128×128, preenchimento alfa ~70, borda 2 px, cantoneiras de 14 px, cruz de pontos no centro."}, {"parte": "X", "descricao": "duas barras de 8 px vermelho #c8323a com brilho #ff5a5a."}, {"parte": "Linha dourada", "descricao": "3 px #f2c230 com halo, contas brilhantes a cada 16 px; ponta com nó/estrela."}, {"parte": "Capacete", "descricao": "casco amarelo com aba, faixa e brilho; selo 22 px no canto inferior direito."}], "paleta": [{"nome": "Verde pode", "hex": "#4fb06a"}, {"nome": "Verde borda", "hex": "#9ff0a8"}, {"nome": "Vermelho não", "hex": "#c8323a"}, {"nome": "Vermelho borda", "hex": "#ff5a5a"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Dourado escuro", "hex": "#b8861a"}, {"nome": "Capacete", "hex": "#f2b630"}], "arquivo": "sprites/est_ghost.png", "fw": 128, "fh": 128, "cols": 6, "quadros": ["tile verde (pode)", "tile vermelho (não pode, X)", "linha dourada ponta", "linha dourada meio", "construtor livre", "construtor ocupado"], "uso": "Os tiles são repetidos sob a prévia (um por tile ocupado). A linha dourada: 'meio' é emendada e girada entre as duas construções, 'ponta' em cada extremo (espelhar para o outro lado). O ícone do construtor vai no HUD de Evolução.", "w": 768, "h": 128}, {"id": "est_cama", "nome": "Camas e moradia", "categoria": "Estação de trabalho", "mecanica": "Grupo GRP-01, GRP-04, GRP-09, GRP-14", "conceito": "Lugares onde os recrutas dormem para recuperar energia. Colchonete de espuma listrado azul encardido no chão com travesseiro e cobertor dobrado; rede de dormir nordestina listrada com franjas, amarrada em dois mourões de madeira; beliche de madeira pregada com dois colchões, escadinha e coberta pendurada; saco de dormir verde-oliva com zíper, vazio e ocupado (cabelo e olho fechado do recruta aparecendo) com 'Z z' subindo em 2 quadros.", "partes": [{"parte": "Colchonete", "descricao": "90×22 px, listras, manchas, travesseiro creme, cobertor xadrez."}, {"parte": "Rede", "descricao": "pano em curva com listras vermelho/amarelo/verde/creme, punhos de corda, franjas, mourões de 70 px."}, {"parte": "Beliche", "descricao": "estrutura de tábuas #9a6a3c com pregos, dois colchões, escada lateral, coberta vermelha caindo."}, {"parte": "Saco de dormir", "descricao": "verde-oliva com costuras, zíper prateado, forro laranja na boca; versão ocupada com cabeça e 'Zz'."}], "paleta": [{"nome": "Espuma azul", "hex": "#5a7aa0"}, {"nome": "Travesseiro", "hex": "#e0d6c0"}, {"nome": "Rede vermelha", "hex": "#c0443a"}, {"nome": "Rede amarela", "hex": "#e8b838"}, {"nome": "Rede verde", "hex": "#4f8a4a"}, {"nome": "Saco oliva", "hex": "#5c6a3a"}, {"nome": "Forro laranja", "hex": "#d87a2a"}, {"nome": "Z", "hex": "#fff4e0"}, {"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Madeira escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}], "arquivo": "sprites/est_cama.png", "fw": 128, "fh": 128, "cols": 6, "quadros": ["colchonete", "rede", "beliche", "saco de dormir (vazio)", "saco de dormir ocupado Zz 1", "saco de dormir ocupado Zz 2"], "anims": [{"nome": "dormindo", "quadros": [4, 5], "dur": [500, 500], "loop": true}], "uso": "Objetos de chão 128×128 com base em gy=112, dentro/ao lado da barraca. O recruta dormindo usa os quadros 4-5 no lugar do próprio sprite.", "w": 768, "h": 128}]}, {"grupo": "mapa", "titulo": "Objetos de mapa, boss e spawn", "ordem": 14, "resumo": "Peças do mundo da expedição que contam regras: grades da arena do boss, gerador das regiões escuras, postes e suas luzes, portal e avisos de spawn, runas e feixe do respawn da Lua de Sangue, obstáculos que os recrutas abrem, ícones do mapa, luzes do herói e decalques de sangue. Ferro enferrujado, madeira gasta e concreto do Recife, sempre com o vermelho-lua como sinal de perigo.", "itens": [{"id": "map_grades", "nome": "Grades da arena do boss", "categoria": "Boss", "mecanica": "Boss (BOSS-01 No way back, BOSS-11 Vitória)", "conceito": "Uma grade levadiça de ferro batido, tirada de um armazém do cais e montada às pressas na boca da arena do boss. Fica pendurada num lintel de vigas de aço rebitadas entre dois pilares de concreto rachado, com correntes grossas que descem de roldanas até contrapesos nos pilares. Quando o herói cruza a linha de entrada, a grade despenca com um clangor: as pontas afiadas cravam no chão, saem faíscas e poeira. Na vitória ela sobe rangendo, soltando ferrugem. O ferro é marrom-ferrugem com manchas alaranjadas, barras quadradas com travessas rebitadas e pontas de lança escuras sujas de sangue seco; um pano vermelho rasgado amarrado no pilar marca a arena.", "partes": [{"parte": "Pilares", "descricao": "2 pilares de concreto 22×142 px (x 18..40 e 216..238) com rachaduras, fuligem #2a2228, faixa de aviso vermelha e cinza, sapata mais larga no chão; o esquerdo tem um pano vermelho #c8323a amarrado"}, {"parte": "Lintel", "descricao": "caixa de aço 244×40 px no topo (y 2..42, tampa clara em cima e frente #6b747a) que esconde a grade recolhida, rebites #c9ced4 a cada 12 px, 3 chapas de reforço, placa de aviso amarela/preta, ferrugem #8a4e2e escorrendo e 2 roldanas de 18 px nas pontas; correntes laterais descem a contrapesos que sobem quando a grade desce"}, {"parte": "Correntes", "descricao": "elos alternados (ovais 4×6 e barras 2×6) cinza-ferro #6b6a66 descendo das roldanas até ganchos nos pilares; balançam 1 px no clangor"}, {"parte": "Grade", "descricao": "13 barras verticais de 5 px a cada 14 px (x 40..216), 3 travessas horizontais de 6 px com rebites, ferro #7a4a32/#5e3826 com manchas laranja #b0603a; pontas de lança #3a2a24 de 10 px com sangue seco #5a1418. A altura de baixo varia: recolhida (só as pontas aparecem sob o lintel, y≈54), fechando (y≈100 e 146), fechada (y≈180)"}, {"parte": "Efeitos", "descricao": "clangor: faíscas amarelas/brancas #fff6c8 #ffd36a nas pontas, estrela de impacto, poeira #9c8a70 e lascas; abrindo: poeira de ferrugem caindo e brilho dourado de vitória"}], "paleta": [{"nome": "Ferro enferrujado", "hex": "#7a4a32"}, {"nome": "Ferro escuro", "hex": "#5e3826"}, {"nome": "Ferrugem viva", "hex": "#b0603a"}, {"nome": "Ponta", "hex": "#3a2a24"}, {"nome": "Concreto", "hex": "#8e8a84"}, {"nome": "Aço do lintel", "hex": "#6b747a"}, {"nome": "Rebite", "hex": "#c9ced4"}, {"nome": "Corrente", "hex": "#6b6a66"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Faísca", "hex": "#ffd36a"}], "arquivo": "sprites/map_grades.png", "fw": 256, "fh": 192, "cols": 6, "quadros": ["aberta (recolhida)", "fechando 1", "fechando 2", "fechada - clangor (faíscas)", "fechada", "abrindo (vitória)"], "anims": [{"nome": "fechar (BOSS-01)", "quadros": [0, 1, 2, 3, 4], "dur": [120, 70, 70, 260, 400], "loop": false}, {"nome": "abrir (BOSS-11)", "quadros": [4, 5, 2, 1, 0], "dur": [200, 220, 220, 220, 400], "loop": false}], "uso": "Âncora no centro da base (128, 180), gy = 180. Fica na camada dos objetos, por cima do chão da entrada da arena; a colisão da saída só existe nos quadros 3 e 4. O tremor da tela no clangor é da câmera, não do sprite.", "w": 1536, "h": 192}, {"id": "map_gerador_regiao", "nome": "Gerador da região escura", "categoria": "Mapa", "mecanica": "Câmera (CAM-09 Região de escuridão), Vasculhar (bateria do carro), LUA-02 (gerador ligado nunca reseta)", "conceito": "Um gerador a diesel velho, pintado de verde-oliva de prefeitura e todo descascado, que alimenta a iluminação de uma região inteira. Ele morreu quando a cidade caiu: o encaixe da bateria na frente está vazio e com fios soltos. O jogador traz uma bateria de carro (loot do carro), encaixa e puxa a alavanca: o motor tosse, saem faíscas azuladas e fumaça, a lâmpada do poste ao lado pisca e acende, e a escuridão da região some. Ao lado, um poste de madeira com cruzeta e isoladores leva os fios até a lâmpada. Tem mostrador de agulha, escapamento enferrujado, adesivos de aviso e uma lona rasgada por cima.", "partes": [{"parte": "Base e skid", "descricao": "estrado de aço 80×8 px (x 12..92, y 140..148) com pés, parafusos e manchas de óleo #1a1418 no chão"}, {"parte": "Corpo do gerador", "descricao": "caixa 72×56 px (x 16..88, y 86..142) verde-oliva #5f6a3a/#4a5430 descascada mostrando metal #7d848c e ferrugem #8a4e2e; grelha de ventilação com 6 ripas, faixa de aviso amarela/preta #e0b030 e adesivo de raio, tampa do tanque e lona #4a6139 dobrada no topo"}, {"parte": "Encaixe da bateria", "descricao": "recesso escuro 22×16 px na frente (x 24..46, y 112..128) com 2 terminais e fios soltos vermelho/preto; com bateria: caixa preta #2a2a2e com tampa vermelha #a8302e, terminais de chumbo #b0b0a8 e etiqueta amarela"}, {"parte": "Painel", "descricao": "mostrador redondo 12 px com agulha (repouso à esquerda, ligado à direita no verde), LED (apagado #3a2a2a, ligando âmbar, ligado verde #6fdc7a) e alavanca vermelha que muda de cima para baixo"}, {"parte": "Escapamento", "descricao": "cano 6 px subindo atrás à esquerda com ponta curva preta; fumaça cinza saindo nos quadros ligando (escura) e ligado (fina)"}, {"parte": "Poste e fios", "descricao": "poste de madeira #7d5430 de 6 px em x≈106 subindo até y 14, cruzeta com 2 isoladores brancos, braço curto e luminária; fio preto em catenária do gerador até o poste; lâmpada apagada #3a3640, piscando âmbar e acesa #ffd36a com brilho e halo"}], "paleta": [{"nome": "Verde-oliva", "hex": "#5f6a3a"}, {"nome": "Verde escuro", "hex": "#4a5430"}, {"nome": "Metal", "hex": "#7d848c"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Aviso amarelo", "hex": "#e0b030"}, {"nome": "Bateria", "hex": "#2a2a2e"}, {"nome": "Tampa da bateria", "hex": "#a8302e"}, {"nome": "Madeira do poste", "hex": "#7d5430"}, {"nome": "Lâmpada", "hex": "#ffd36a"}, {"nome": "Faísca azul", "hex": "#bfe8ff"}], "arquivo": "sprites/map_gerador_regiao.png", "fw": 128, "fh": 160, "cols": 6, "quadros": ["desligado (encaixe vazio)", "bateria encaixada", "ligando 1 (faíscas)", "ligando 2 (tosse e fumaça)", "ligado 1", "ligado 2 (luz pulsando)"], "anims": [{"nome": "ligando", "quadros": [1, 2, 3, 2, 3], "dur": [300, 90, 110, 90, 140], "loop": false}, {"nome": "ligado", "quadros": [4, 5], "dur": [260, 260], "loop": true}], "uso": "Âncora na base (52, 148), gy = 148. Ao ligar, o jogo troca a região de escura para normal e soma a luz da lâmpada (use map_luz_poste em (106, 30) projetado no chão). Estado salvo para sempre (LUA-02). Tremor do motor = wobble de 1 px em tempo real.", "w": 768, "h": 160}, {"id": "map_poste", "nome": "Poste de luz da rua", "categoria": "Mapa", "mecanica": "Dia e noite (DN-04 luzes, DN-05 postes em cascata, DN-02 postes avermelhados)", "conceito": "Poste de ferro fundido no estilo do Recife Antigo, com lanterna de quatro vidros no alto, sobrevivente do fim do mundo mas maltratado: o vidro está trincado, a pintura preta descascou em ferrugem, um fio cortado pende da cruzeta e há fita isolante, cartaz rasgado e respingos de sangue na base. De noite ele acende em cascata e às vezes pisca antes de firmar; na Lua de Sangue a luz fica vermelha. É a fonte de luz mais comum das ruas e o lugar onde o modo automático se esconde à noite.", "partes": [{"parte": "Base", "descricao": "pedestal 18×20 px (x 23..41, y 128..148) com saia larga, frisos e parafusos, ferrugem #8a4e2e e sangue seco #5a1418 respingado"}, {"parte": "Coluna", "descricao": "fuste de 6 px (x 29..35) de ferro preto #2e2c34 com anéis a cada ~26 px, cartaz de papel rasgado #cfc6ae, fita isolante #1a1a1e e escorrido de ferrugem"}, {"parte": "Cruzeta", "descricao": "braço curto em y≈44 com 2 isoladores #d8d2c2 e um fio preto cortado pendurado balançando"}, {"parte": "Lanterna", "descricao": "copa 18×28 px (x 23..41, y 10..38): telhado em ponta, 4 vidros (vistos 2) com montantes, uma trinca; apagado #3a3a46 escuro-azulado; aceso #ffe9a8/#ffd36a com núcleo branco; vermelho #ff5a5a/#c8323a; brilho glow em volta quando aceso"}], "paleta": [{"nome": "Ferro preto", "hex": "#2e2c34"}, {"nome": "Ferro realce", "hex": "#4a4652"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Vidro apagado", "hex": "#3a3a46"}, {"nome": "Luz", "hex": "#ffd36a"}, {"nome": "Luz clara", "hex": "#ffe9a8"}, {"nome": "Luz da lua", "hex": "#ff5a5a"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Cartaz", "hex": "#cfc6ae"}], "arquivo": "sprites/map_poste.png", "fw": 64, "fh": 160, "cols": 5, "quadros": ["apagado", "piscando 1 (fraco)", "piscando 2 (quase apagado)", "aceso", "aceso vermelho (Lua de Sangue)"], "anims": [{"nome": "acender (DN-05)", "quadros": [0, 1, 2, 1, 2, 3], "dur": [200, 60, 90, 50, 120, 400], "loop": false}, {"nome": "piscar", "quadros": [1, 2], "dur": [80, 140], "loop": true}], "uso": "Âncora (32, 148), gy = 148. O halo no chão é o sprite separado map_luz_poste, desenhado na camada de luz/chão embaixo dos personagens; o atraso da cascata é do jogo. Na Lua de Sangue troca para o quadro 4 e o halo vermelho.", "w": 320, "h": 160}, {"id": "map_luz_poste", "nome": "Halo de luz do poste no chão", "categoria": "Mapa", "mecanica": "Dia e noite (DN-04, DN-02)", "conceito": "A poça de luz que o poste projeta na calçada: uma elipse achatada em perspectiva 3/4, com raio de ~3 tiles, feita em degraus de transparência (pixel art, sem degradê liso). O centro é mais forte e quente, levemente deslocado para baixo do poste, e as bordas se desfazem em anéis com pontilhado. A versão da Lua de Sangue é vermelha, mais fraca e com o centro rosado, para o mundo ficar tenso mesmo perto da luz.", "partes": [{"parte": "Elipse de luz", "descricao": "elipse 188×116 px centrada em (96, 64), 6 degraus de alpha (~16 a 120) em #ffd36a/#ffe9a8; borda com pontilhado em xadrez entre degraus"}, {"parte": "Núcleo", "descricao": "elipse interna 40×22 px mais clara #fff2c8 (normal) ou #ff9a8a (vermelho)"}], "paleta": [{"nome": "Luz quente", "hex": "#ffd36a"}, {"nome": "Núcleo", "hex": "#fff2c8"}, {"nome": "Luz vermelha", "hex": "#ff5a5a"}, {"nome": "Núcleo vermelho", "hex": "#ff9a8a"}], "arquivo": "sprites/map_luz_poste.png", "fw": 192, "fh": 128, "cols": 2, "quadros": ["normal", "vermelho (Lua de Sangue)"], "uso": "Centro (96, 64) colocado no chão na base do poste. Desenhar com mistura aditiva (ou 'screen') na camada de luz; para o mapa de luz do DN-04 o alpha serve de intensidade. O tremular é variação de alpha/escala em tempo real.", "w": 384, "h": 128}, {"id": "map_portal", "nome": "Portal de spawn da Lua de Sangue", "categoria": "Spawn", "mecanica": "Spawn (SPW-03 Open a portal, SPW-04 Drop it in)", "conceito": "Um rasgo no ar, vermelho como carne viva, que se abre acima do ponto de spawn para o zumbi cair dele. Começa como uma fenda fina e torta, se alarga numa elipse escura com bordas irregulares que pulsam, rodeada por dois anéis de runas finas girando em sentidos opostos. Do lábio de baixo pingam gotas de sangue luminoso, e um brilho vermelho ilumina o chão. Ao fechar, a fenda se costura num risco e some em fagulhas. Lê de longe como 'vai cair coisa aqui'.", "partes": [{"parte": "Fenda", "descricao": "elipse vertical torta centrada em (64, 50): abrindo 4×20 → 16×34 → 30×44 px; aberta 34×46 px; miolo preto-roxo #120810 com estrelas de pontos #3a1430, borda serrilhada #c8323a/#ff5a5a de 2-3 px com dentes"}, {"parte": "Anéis", "descricao": "2 elipses de 50×20 e 60×24 px em volta da fenda, tracejadas em #ff5a5a/#c8323a com runas de 3 px, girando 30° por quadro em sentidos opostos (parte de trás atrás da fenda)"}, {"parte": "Gotas", "descricao": "gotas de 2×3 px #c8323a com brilho #ff9a8a caindo do lábio de baixo, posições diferentes por quadro; respingos no chão em y≈112"}, {"parte": "Brilho", "descricao": "glow vermelho em volta (raio 48) e mancha de luz no chão (elipse 40×10 em y 112)"}], "paleta": [{"nome": "Vazio", "hex": "#120810"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Rosado", "hex": "#ff9a8a"}, {"nome": "Sangue escuro", "hex": "#6a1420"}], "arquivo": "sprites/map_portal.png", "fw": 128, "fh": 128, "cols": 8, "quadros": ["abrindo 1", "abrindo 2", "abrindo 3", "aberto 1", "aberto 2", "aberto 3", "fechando 1", "fechando 2"], "anims": [{"nome": "abrir (0,5 s)", "quadros": [0, 1, 2], "dur": [160, 170, 170], "loop": false}, {"nome": "aberto", "quadros": [3, 4, 5], "dur": [110, 110, 110], "loop": true}, {"nome": "fechar (0,4 s)", "quadros": [6, 7], "dur": [200, 200], "loop": false}], "uso": "Âncora no chão (64, 112): o portal fica ~60 px acima do ponto de spawn. Camada de efeitos, por cima dos personagens. O zumbi cai de (64, 50) com a sombra de map_aviso_spawn crescendo.", "w": 1024, "h": 128}, {"id": "map_aviso_spawn", "nome": "Aviso de spawn no chão", "categoria": "Spawn", "mecanica": "Spawn (SPW-01 aviso, SPW-04 sombra, SPW-05 rachadura, BF-06 minions saem do chão)", "conceito": "Tudo o que aparece no chão antes e depois de um zumbi chegar. A marca de aviso é um círculo vermelho pulsante pintado em perspectiva, com um anel externo que fecha até o centro em 1 s e um '!' no meio. A versão grande, para zumbis que caem 'do céu', tem duas voltas e marcas de mira. Depois vem a sombra que cresce enquanto o corpo cai, a rachadura do impacto com torrões, que fica e some, e a terra que estufa, racha e se abre quando o zumbi 'sai do chão'. Tudo em tons de vermelho-lua e terra escura, legível sobre paralelepípedo e asfalto.", "partes": [{"parte": "Marca de aviso", "descricao": "disco 60×30 px centrado em (64, 54) em #c8323a com alpha ~110, borda #ff5a5a, '!' vermelho/branco de 5×12 px; anel externo que fecha: 120×60 → 96×48 → 76×38 → 62×31 px"}, {"parte": "Marca grande (do céu)", "descricao": "duas voltas 110×56 e 80×40, 4 marcas de mira em cruz e '!' maior; 2 quadros de pulso"}, {"parte": "Sombra crescendo", "descricao": "elipse roxa-escura #3a2850 com alpha 90/130/170 de 30×12, 60×24 e 96×38 px"}, {"parte": "Rachadura", "descricao": "estrela de rachaduras pretas #1a1014 de 70×36 px com borda clara #6a5a4a, torrões #5a4632 em volta e poeira; quadro 2 mais transparente (sumindo)"}, {"parte": "Terra abrindo", "descricao": "monte estufado #5a4632/#3e3024 com rachas, depois buraco escuro #140c0c com bordas levantadas e torrões voando, e brilho vermelho no fundo"}], "paleta": [{"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Sombra", "hex": "#3a2850"}, {"nome": "Terra", "hex": "#5a4632"}, {"nome": "Terra escura", "hex": "#3e3024"}, {"nome": "Buraco", "hex": "#140c0c"}, {"nome": "Racha", "hex": "#1a1014"}], "arquivo": "sprites/map_aviso_spawn.png", "fw": 128, "fh": 96, "cols": 7, "quadros": ["aviso 1 (anel longe)", "aviso 2", "aviso 3", "aviso 4 (anel fechado)", "aviso grande do céu 1", "aviso grande do céu 2", "sombra pequena", "sombra média", "sombra grande", "rachadura de chegada", "rachadura sumindo", "terra estufando", "terra rachando", "terra aberta (sai do chão)"], "anims": [{"nome": "aviso (1 s)", "quadros": [0, 1, 2, 3], "dur": [250, 250, 250, 250], "loop": true}, {"nome": "aviso grande", "quadros": [4, 5], "dur": [180, 180], "loop": true}, {"nome": "sombra caindo", "quadros": [6, 7, 8], "dur": [150, 150, 150], "loop": false}, {"nome": "rachadura", "quadros": [9, 10], "dur": [4000, 2000], "loop": false}, {"nome": "sai do chão (0,6 s)", "quadros": [11, 12, 13], "dur": [200, 200, 200], "loop": false}], "uso": "Centro no chão (64, 54) = ponto de spawn. Camada de chão (decal), embaixo dos personagens; a seta da borda da tela e os bipes são do HUD. O pulso da marca pode ganhar escala em tempo real.", "w": 896, "h": 192}, {"id": "map_runas_respawn", "nome": "Círculo de runas do respawn", "categoria": "Lua de Sangue", "mecanica": "Lua de Sangue (LUA-05 respawn de boss e mini boss)", "conceito": "O círculo que anuncia que um boss vai renascer: brota do chão onde ele estava, girando e crescendo em 0,4 s. São dois anéis concêntricos brilhando em vermelho-lua, com uma faixa de runas angulosas entre eles, raios ligando os anéis e um crescente de lua no centro, tudo achatado em perspectiva. As linhas parecem queimadas na pedra, com brasas e fumaça fina, e o centro ganha um brilho que prepara o feixe que vai descer. Nada de símbolo religioso: são runas inventadas da lua.", "partes": [{"parte": "Anéis", "descricao": "anel externo 176×88 px e interno 120×60 px (em escala no quadro 4), linha dupla #c8323a com núcleo #ff5a5a e pontos brancos rosados"}, {"parte": "Runas", "descricao": "12 runas de 5×7 px entre os anéis, girando 15° por quadro, cor #ff5a5a com contorno escuro"}, {"parte": "Centro", "descricao": "crescente de lua 22×12 px e 6 raios finos; brilho glow vermelho"}, {"parte": "Escala por quadro", "descricao": "0,35 / 0,6 / 0,85 / 1,0 do tamanho, com brasas subindo"}], "paleta": [{"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Rosado", "hex": "#ffb0a0"}, {"nome": "Queimado", "hex": "#2a0e12"}], "arquivo": "sprites/map_runas_respawn.png", "fw": 192, "fh": 128, "cols": 4, "quadros": ["brotando (0,35)", "crescendo (0,6)", "crescendo (0,85)", "completo"], "anims": [{"nome": "crescer (0,4 s)", "quadros": [0, 1, 2, 3], "dur": [100, 100, 100, 100], "loop": false}], "uso": "Centro (96, 64) no ponto de respawn, camada de chão. Depois do quadro 3 o jogo pode girá-lo em tempo real; o feixe map_feixe_lua desce no centro.", "w": 768, "h": 128}, {"id": "map_feixe_lua", "nome": "Feixe de luz vermelha da lua", "categoria": "Lua de Sangue", "mecanica": "Lua de Sangue (LUA-05; LUA-06 usa a mesma forma tingida de dourado)", "conceito": "Um pilar de luz vermelha que desce do céu sobre o círculo de runas, como se a própria Lua de Sangue apontasse o lugar. Começa como um fio fino, explode num feixe largo com flash branco no chão, fica estável com estrias que descem e partículas subindo, e se desfaz de cima para baixo deixando brasas. O núcleo é quase branco-rosado e as bordas vermelho-lua em degraus de transparência.", "partes": [{"parte": "Feixe", "descricao": "coluna vertical centrada em x 48 de y 0 até o chão (y 232): fino 6 px, largo 60 px, estável 40 px, sumindo 30 px com a parte de cima já apagada; 4 faixas de alpha #c8323a → #ff5a5a → #ffb0a0 → núcleo #fff0ec"}, {"parte": "Impacto no chão", "descricao": "elipse 80×20 px em y 232, flash branco no quadro 2"}, {"parte": "Partículas", "descricao": "fagulhas 1-2 px subindo e estrias horizontais mais claras descendo"}], "paleta": [{"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Brilho", "hex": "#ff5a5a"}, {"nome": "Rosado", "hex": "#ffb0a0"}, {"nome": "Núcleo", "hex": "#fff0ec"}], "arquivo": "sprites/map_feixe_lua.png", "fw": 96, "fh": 256, "cols": 4, "quadros": ["fino", "largo com flash", "estável", "sumindo"], "anims": [{"nome": "feixe", "quadros": [0, 1, 2, 3], "dur": [120, 140, 400, 200], "loop": false}], "uso": "Âncora no chão (48, 232) = centro do círculo de runas. Camada de efeitos, aditiva. Tremor e estalo são da câmera/som.", "w": 384, "h": 256}, {"id": "map_barricada_caminho", "nome": "Barricada de madeira no caminho", "categoria": "Mapa", "mecanica": "Grupo (GRP-11 especialidade na expedição: Madeira derruba barricadas)", "conceito": "Uma barricada improvisada por sobreviventes que já não estão lá: dois cavaletes em X de caibro, tábuas pregadas atravessadas, uma porta velha e uma placa de 'PARE' pintada à mão. Bloqueia um atalho e só o recruta lenhador consegue derrubar a machadadas. Primeiro inteira, depois rachada com lascas e uma tábua pendurada num prego, e por fim derrubada: tábuas espalhadas no chão, cavalete tombado e serragem. Madeira gasta e cinzenta com pregos tortos, arame enrolado e sangue seco.", "partes": [{"parte": "Cavaletes", "descricao": "2 X de caibro #7d5430/#5a3a22 de 8 px nas pontas (x 14..36 e 92..114), com amarração de arame #8d969c"}, {"parte": "Tábuas", "descricao": "4 tábuas horizontais 100×10 px #9a6a3c/#8b5e34 com veios, nós, pregos #c9c3b0, uma com listras vermelho/branco de aviso, outra com 'PARE' sugerido em vermelho"}, {"parte": "Danos", "descricao": "rachada: rachaduras pretas, lascas claras #c9a070 caindo, uma tábua pendurada torta; derrubada: tábuas no chão em ângulos, cavalete caído, serragem e lascas"}], "paleta": [{"nome": "Tábua", "hex": "#9a6a3c"}, {"nome": "Tábua 2", "hex": "#7d5430"}, {"nome": "Tábua escura", "hex": "#5a3a22"}, {"nome": "Prego", "hex": "#c9c3b0"}, {"nome": "Lasca", "hex": "#c9a070"}, {"nome": "Aviso vermelho", "hex": "#c8323a"}, {"nome": "Arame", "hex": "#8d969c"}], "arquivo": "sprites/map_barricada_caminho.png", "fw": 128, "fh": 128, "cols": 3, "quadros": ["inteira", "rachada", "derrubada"], "anims": [{"nome": "derrubar", "quadros": [0, 1, 2], "dur": [300, 300, 600], "loop": false}], "uso": "Âncora (64, 112), gy = 112. Colisão nos quadros 0 e 1; no 2 vira passagem. Chacoalhar a cada machadada é wobble em tempo real; lascas são partículas.", "w": 384, "h": 128}, {"id": "map_porta_emperrada", "nome": "Porta de enrolar emperrada", "categoria": "Mapa", "mecanica": "Grupo (GRP-11 especialidade na expedição: Construção abre portas emperradas)", "conceito": "A porta de aço de enrolar de uma loja do centro do Recife, amassada e emperrada no trilho, bloqueando a entrada de um atalho ou de um depósito. O recruta construtor força com pé de cabra: a porta sobe torta alguns centímetros com faíscas e poeira, depois mais um pouco, e por fim enrola de vez na caixa do alto, revelando o interior escuro. O aço ondulado cinza está riscado, com amassados, pichação vermelha, um cadeado arrebentado e ferrugem nas canaletas; a moldura é de concreto rachado com azulejo quebrado.", "partes": [{"parte": "Moldura", "descricao": "parede de concreto #8e8a84/#77736e de 120×140 px com batentes de 12 px, rachaduras, pedaços de azulejo azul #4a7ea8 e fuligem; trilhos laterais de aço #6b747a"}, {"parte": "Caixa do rolo", "descricao": "caixa de chapa 104×18 px no topo (y 16..34) #7d848c com parafusos e ferrugem; no aberto mostra o rolo grosso"}, {"parte": "Porta", "descricao": "lâminas onduladas horizontais de 5 px #8d969c/#6b747a, um amassado grande, pichação vermelha #c8323a, puxador e cadeado #c9c3b0 quebrado na base; forçando: sobe 10 px torta (−3°) e 26 px com fresta escura e faíscas"}, {"parte": "Interior", "descricao": "escuro #120e14 com caixas e prateleira sugeridas em roxo-escuro, uma lata no chão e luz fraca entrando pela fresta"}], "paleta": [{"nome": "Concreto", "hex": "#8e8a84"}, {"nome": "Concreto escuro", "hex": "#77736e"}, {"nome": "Chapa", "hex": "#8d969c"}, {"nome": "Chapa escura", "hex": "#6b747a"}, {"nome": "Ferrugem", "hex": "#8a4e2e"}, {"nome": "Pichação", "hex": "#c8323a"}, {"nome": "Azulejo", "hex": "#4a7ea8"}, {"nome": "Interior", "hex": "#120e14"}], "arquivo": "sprites/map_porta_emperrada.png", "fw": 128, "fh": 160, "cols": 4, "quadros": ["fechada emperrada", "forçando 1", "forçando 2", "aberta"], "anims": [{"nome": "forçar", "quadros": [1, 2], "dur": [160, 160], "loop": true}, {"nome": "abrir", "quadros": [0, 1, 2, 3], "dur": [300, 200, 200, 500], "loop": false}], "uso": "Âncora (64, 148), gy = 148, encostada numa parede de prédio. Colisão até o quadro 2; no 3 vira passagem. Tremor ao forçar é wobble em tempo real.", "w": 512, "h": 160}, {"id": "map_sobrevivente_marca", "nome": "Ícones do mapa", "categoria": "Interface", "mecanica": "Câmera / Mapa (minimapa e mapa inteiro; CAM-09, BOSS-13, REC-01, LUA-06)", "conceito": "Os pinos que aparecem no minimapa e no mapa da expedição, cada um num medalhão redondo de chapa com aro escuro para ler sobre qualquer fundo. Baú marcado tem um baú de madeira com '?' dourado; o boss é uma caveira com chifres sobre fundo vermelho-lua; o mini boss é uma caveira menor sem chifres em laranja; região limpa é um ✓ verde; região escura é uma lâmpada apagada sobre preto-roxo; sobrevivente é um rosto com balão de fala; abrigo é uma barraca com fogueira; e o herói é uma seta-pino com camisa vermelha. Formas grandes e chapadas com 1 px de brilho para ler em 16 px de longe.", "partes": [{"parte": "Medalhão", "descricao": "disco 52×52 px centrado em (32, 30) com aro de 3 px escuro #1e1418 e borda interna clara, fundo da cor do tipo; sombra embaixo"}, {"parte": "Baú ?", "descricao": "baú 26×18 #9a6a3c com cintas #c9c3b0 e '?' #f2c230"}, {"parte": "Boss", "descricao": "caveira 24×22 #e8e0cc com olhos #c8323a, chifres curvos #3a2a24 sobre fundo #c8323a/#7a1a22"}, {"parte": "Mini boss", "descricao": "caveira 18×16 sem chifres com cicatriz, fundo laranja #d07a2a"}, {"parte": "Região limpa", "descricao": "✓ grosso #6fdc7a com contorno verde escuro sobre fundo #2a5a34"}, {"parte": "Região escura", "descricao": "lâmpada apagada #5a5a66 com rosca e fundo #140e1c, raios riscados"}, {"parte": "Sobrevivente", "descricao": "rosto #c48a5a com cabelo escuro e balão 💬 branco, fundo azul #4a8fe0"}, {"parte": "Abrigo", "descricao": "barraca #5f7a4a com fogueira laranja na frente, fundo #6a5030"}, {"parte": "Herói", "descricao": "pino em gota vermelho #d23a34 com rosto do herói e seta, sem medalhão; borda branca"}], "paleta": [{"nome": "Aro", "hex": "#1e1418"}, {"nome": "Vermelho-lua", "hex": "#c8323a"}, {"nome": "Dourado", "hex": "#f2c230"}, {"nome": "Verde", "hex": "#6fdc7a"}, {"nome": "Laranja", "hex": "#d07a2a"}, {"nome": "Azul", "hex": "#4a8fe0"}, {"nome": "Osso", "hex": "#e8e0cc"}], "arquivo": "sprites/map_sobrevivente_marca.png", "fw": 64, "fh": 64, "cols": 8, "quadros": ["baú marcado ?", "boss", "mini boss", "região limpa", "região escura", "sobrevivente", "abrigo", "posição do herói"], "uso": "Âncora (32, 58) na ponta de baixo. Desenhar no minimapa reduzido (16-24 px) com NEAREST; o pulsar do boss e do herói é escala em tempo real.", "w": 512, "h": 64}, {"id": "map_lanterna_luz", "nome": "Luz da lanterna e círculo do twist", "categoria": "Mapa", "mecanica": "Dia e noite (DN-04 lanterna ~2 tiles), Câmera (CAM-09 luz em volta do herói), Boss fases (BF-07 twist das luzes apagadas)", "conceito": "As máscaras de luz que acompanham o herói no escuro. O halo da lanterna é um círculo quente de ~2 tiles, feito em degraus de transparência com pontilhado entre eles, e o cone é o facho da lanterna apontando para a direita (o jogo gira), mais forte na ponta da lente e se abrindo em leque. O círculo do twist do boss é mais frio e duro, com um anel de borda nítido, e vem também como máscara de escuridão: tudo preto-roxo com o furo do círculo, para pôr por cima da arena quando as luzes apagam.", "partes": [{"parte": "Halo", "descricao": "círculo de raio 60 px centrado (64, 64), 6 degraus de alpha 20..150 em #fff0c0/#ffd36a com núcleo branco-quente"}, {"parte": "Cone", "descricao": "leque de 50° saindo de (14, 64) para a direita até x 124, degraus de alpha por distância e por ângulo, mancha clara na ponta"}, {"parte": "Círculo do twist", "descricao": "círculo de raio 54 frio #e8e4ff com 4 degraus e anel de borda #ffffff alpha 160 de 2 px"}, {"parte": "Máscara escura", "descricao": "fundo #0c0814 alpha 235 com furo de raio 54 e degraus de penumbra de 6 px na borda"}], "paleta": [{"nome": "Luz quente", "hex": "#ffd36a"}, {"nome": "Luz clara", "hex": "#fff0c0"}, {"nome": "Luz fria", "hex": "#e8e4ff"}, {"nome": "Escuridão", "hex": "#0c0814"}], "arquivo": "sprites/map_lanterna_luz.png", "fw": 128, "fh": 128, "cols": 4, "quadros": ["halo da lanterna", "cone da lanterna (direita)", "círculo do twist (luz)", "máscara de escuridão do twist"], "uso": "Centro (64, 64) no centro do herói (o cone nasce em (14, 64) na mão e o jogo gira conforme a direção). Quadros 0-2 vão no mapa de luz (aditivo); o 3 vai por cima do mundo, escalado para cobrir a tela fora do quadro. Tremular = escala ±3% em tempo real.", "w": 512, "h": 128}, {"id": "map_sangue_decal", "nome": "Decalques de sangue no chão", "categoria": "Mapa", "mecanica": "Mapas (ambientação das regiões)", "conceito": "Manchas de chão para espalhar pelo mundo e contar o que aconteceu ali: uma poça seca que já escureceu nas bordas e racha no meio, um rastro de arrasto com marcas de dedos indo para fora do quadro, uma trilha de pegadas de tênis que vão sumindo e um grupo de respingos e gotas. Vermelho escuro quase marrom, com o centro ainda brilhante em algumas, para ficar sério sem ser exagerado. Achatados em perspectiva 3/4 e sem contorno preto, para assentar no chão.", "partes": [{"parte": "Poça seca", "descricao": "forma irregular 90×34 px #5a1418 com borda mais escura #3a0c10, miolo #7a1a22 e brilho #a8303a, rachas finas e gotas em volta"}, {"parte": "Rastro de arrasto", "descricao": "faixa 110×14 px que afina, com estrias paralelas, 4 marcas de dedos no fim e respingos"}, {"parte": "Pegadas", "descricao": "6 pegadas de tênis 7×12 px alternadas, ficando mais fracas (alpha 230 → 90)"}, {"parte": "Manchas", "descricao": "3 respingos com coroa de gotas e espirro alongado na direção do golpe"}], "paleta": [{"nome": "Sangue seco", "hex": "#5a1418"}, {"nome": "Borda", "hex": "#3a0c10"}, {"nome": "Miolo", "hex": "#7a1a22"}, {"nome": "Brilho", "hex": "#a8303a"}], "arquivo": "sprites/map_sangue_decal.png", "fw": 128, "fh": 64, "cols": 4, "quadros": ["poça seca", "rastro de arrasto", "pegadas de sangue", "manchas"], "uso": "Decal de chão, centro (64, 32), camada logo acima do chão (pode ir no cache da região, CAM-12). Pode espelhar e girar 180° para variar.", "w": 512, "h": 64}]}], "total": 127, "quadros": 1113};
